  dependency_ordinal            INTEGER NOT NULL CHECK(dependency_ordinal >= 0),
  callee_procedure_lineage      BLOB    NOT NULL CHECK(length(callee_procedure_lineage) = 32),
  callee_entry_selector_digest  BLOB    NOT NULL CHECK(length(callee_entry_selector_digest) = 32),
  expected_output_digest        BLOB    NOT NULL CHECK(length(expected_output_digest) = 32),
  consumed_child_lookup_digest  BLOB    NOT NULL CHECK(length(consumed_child_lookup_digest) = 32),
  entry_kind                    TEXT    NOT NULL CHECK(entry_kind IN ('zero', 'carrier')),
  entry_carrier_key             BLOB CHECK(entry_carrier_key IS NULL OR length(entry_carrier_key) = 32),
  entry_uncertain               INTEGER NOT NULL CHECK(entry_uncertain IN (0, 1)),
  entry_source_behavior_digest  BLOB CHECK(entry_source_behavior_digest IS NULL OR length(entry_source_behavior_digest) = 32),
  entry_source_count            INTEGER NOT NULL CHECK(entry_source_count >= 0),
  PRIMARY KEY(summary_id, dependency_ordinal),
  UNIQUE(summary_id, consumed_child_lookup_digest),
  CHECK(
    (entry_kind = 'zero' AND entry_carrier_key IS NULL AND entry_uncertain = 0
      AND entry_source_behavior_digest IS NULL AND entry_source_count = 0)
    OR
    (entry_kind = 'carrier' AND entry_carrier_key IS NOT NULL AND entry_source_count > 0)
  ),
  FOREIGN KEY(summary_id) REFERENCES class_set_summaries(summary_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE class_set_summary_dependency_sources(
  summary_id         INTEGER NOT NULL,
  dependency_ordinal INTEGER NOT NULL CHECK(dependency_ordinal >= 0),
  source_ordinal     INTEGER NOT NULL CHECK(source_ordinal >= 0),
  source_event_digest BLOB NOT NULL CHECK(length(source_event_digest) = 32),
  PRIMARY KEY(summary_id, dependency_ordinal, source_ordinal),
  UNIQUE(summary_id, dependency_ordinal, source_event_digest),
  FOREIGN KEY(summary_id, dependency_ordinal)
    REFERENCES class_set_summary_dependencies(summary_id, dependency_ordinal)
    ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE class_set_summary_exits(
  summary_id      INTEGER NOT NULL,
  exit_ordinal    INTEGER NOT NULL CHECK(exit_ordinal >= 0),
  exit_kind       TEXT    NOT NULL CHECK(exit_kind IN ('normal', 'exceptional')),
  fact_ordinal    INTEGER NOT NULL CHECK(fact_ordinal >= 0),
  quality_mask    INTEGER NOT NULL CHECK(quality_mask IN (1, 2, 4, 6, 8)),
  PRIMARY KEY(summary_id, exit_ordinal),
  FOREIGN KEY(summary_id, fact_ordinal)
    REFERENCES class_set_summary_facts(summary_id, fact_ordinal) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE class_set_summary_facts(
  summary_id       INTEGER NOT NULL,
  fact_ordinal     INTEGER NOT NULL CHECK(fact_ordinal >= 0),
  fact_kind        TEXT    NOT NULL CHECK(fact_kind IN ('zero', 'carrier', 'meeting')),
  source_kind      TEXT    NOT NULL CHECK(source_kind IN ('none', 'entry', 'event')),
  source_event_key BLOB,
  carrier_key      BLOB,
  sink_event_key   BLOB,
  uncertain        INTEGER NOT NULL CHECK(uncertain IN (0, 1)),
  PRIMARY KEY(summary_id, fact_ordinal),
  FOREIGN KEY(summary_id) REFERENCES class_set_summaries(summary_id) ON DELETE CASCADE,
  CHECK((source_kind = 'event') = (source_event_key IS NOT NULL)),
  CHECK(source_event_key IS NULL OR length(source_event_key) = 32),
  CHECK(carrier_key IS NULL OR length(carrier_key) = 32),
  CHECK(sink_event_key IS NULL OR length(sink_event_key) = 32),
  CHECK((fact_kind = 'zero') =
        (source_kind = 'none' AND carrier_key IS NULL AND sink_event_key IS NULL)),
  CHECK((fact_kind = 'carrier') = (carrier_key IS NOT NULL)),
  CHECK((fact_kind = 'meeting') = (sink_event_key IS NOT NULL)),
  CHECK(fact_kind = 'zero' OR source_kind <> 'none'),
  CHECK(fact_kind <> 'zero' OR uncertain = 0)
) WITHOUT ROWID, STRICT;

CREATE TABLE class_set_summary_reached(
  summary_id      INTEGER NOT NULL,
  reached_ordinal INTEGER NOT NULL CHECK(reached_ordinal >= 0),
  point_id        INTEGER NOT NULL CHECK(point_id >= 0),
  fact_ordinal    INTEGER NOT NULL CHECK(fact_ordinal >= 0),
  quality_mask    INTEGER NOT NULL CHECK(quality_mask IN (1, 2, 4, 6, 8)),
  PRIMARY KEY(summary_id, reached_ordinal),
  FOREIGN KEY(summary_id, fact_ordinal)
    REFERENCES class_set_summary_facts(summary_id, fact_ordinal) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE class_set_summary_reads(
  summary_id   INTEGER NOT NULL,
  read_ordinal INTEGER NOT NULL CHECK(read_ordinal >= 0),
  key_digest   BLOB    NOT NULL CHECK(length(key_digest) = 32),
  kind         TEXT    NOT NULL CHECK(kind IN (
    'file', 'path_absent', 'index', 'lookup', 'artifact', 'scope', 'models',
    'policy', 'configuration', 'epoch'
  )),
  family       TEXT,
  languages    TEXT,
  rel_path     TEXT,
  name         TEXT,
  index_key    BLOB,
  blob_oid     TEXT CHECK(blob_oid IS NULL OR
    (length(blob_oid) = 40 AND blob_oid NOT GLOB '*[^0-9a-f]*')),
  subject      BLOB CHECK(subject IS NULL OR length(subject) = 32),
  start_byte   INTEGER CHECK(start_byte IS NULL OR start_byte >= 0),
  end_byte     INTEGER CHECK(end_byte IS NULL OR end_byte >= start_byte),
  digest       BLOB CHECK(digest IS NULL OR length(digest) = 32),
  PRIMARY KEY(summary_id, read_ordinal),
  UNIQUE(summary_id, key_digest),
  FOREIGN KEY(summary_id) REFERENCES class_set_summaries(summary_id) ON DELETE CASCADE,
  CHECK((kind = 'file') = (blob_oid IS NOT NULL)),
  CHECK((kind = 'index') = (index_key IS NOT NULL)),
  CHECK(start_byte IS NULL OR kind = 'lookup'),
  CHECK(kind <> 'lookup' OR digest IS NOT NULL),
  CHECK(kind <> 'scope' OR (languages IS NOT NULL AND digest IS NOT NULL)),
  CHECK(kind <> 'artifact' OR subject IS NOT NULL),
  CHECK(kind NOT IN ('models', 'configuration', 'epoch') OR digest IS NOT NULL),
  CHECK(kind <> 'policy' OR (subject IS NOT NULL AND digest IS NOT NULL)),
  CHECK((start_byte IS NULL) = (end_byte IS NULL)),
  CHECK(CASE kind
    WHEN 'file' THEN
      family IS NULL AND languages IS NOT NULL AND rel_path IS NOT NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NOT NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NULL
    WHEN 'path_absent' THEN
      family IS NULL AND languages IS NOT NULL AND rel_path IS NOT NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NULL
    WHEN 'index' THEN
      family IS NOT NULL AND languages IS NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NOT NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NULL
    WHEN 'lookup' THEN
      family IS NOT NULL AND languages IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND digest IS NOT NULL AND (
        (rel_path IS NOT NULL AND name IS NOT NULL AND subject IS NULL
          AND start_byte IS NULL AND end_byte IS NULL)
        OR (rel_path IS NOT NULL AND name IS NULL AND subject IS NULL
          AND start_byte IS NULL AND end_byte IS NULL)
        OR (rel_path IS NOT NULL AND name IS NULL AND subject IS NOT NULL
          AND start_byte IS NOT NULL AND end_byte IS NOT NULL)
        OR (rel_path IS NULL AND name IS NULL AND subject IS NOT NULL
          AND start_byte IS NULL AND end_byte IS NULL)
      )
    WHEN 'artifact' THEN
      family IS NOT NULL AND languages IS NULL AND name IS NULL AND index_key IS NULL
      AND blob_oid IS NULL AND subject IS NOT NULL AND start_byte IS NULL
      AND end_byte IS NULL AND digest IS NULL
    WHEN 'scope' THEN
      family IS NULL AND languages IS NOT NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NOT NULL
    WHEN 'policy' THEN
      family IS NULL AND languages IS NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NOT NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NOT NULL
    WHEN 'models' THEN
      family IS NULL AND languages IS NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NOT NULL
    WHEN 'configuration' THEN
      family IS NULL AND languages IS NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NOT NULL
    WHEN 'epoch' THEN
      family IS NULL AND languages IS NULL AND rel_path IS NULL
      AND name IS NULL AND index_key IS NULL AND blob_oid IS NULL
      AND subject IS NULL AND start_byte IS NULL AND end_byte IS NULL AND digest IS NOT NULL
    ELSE 0
  END)
) WITHOUT ROWID, STRICT;

CREATE TABLE "code_unit_fq_segments"(
  blob_id      INTEGER NOT NULL,
  lang         TEXT    NOT NULL,
  unit_key     INTEGER NOT NULL,
  seg_ordinal  INTEGER NOT NULL CHECK(seg_ordinal >= 0),
  seg_kind     TEXT    NOT NULL CHECK(seg_kind IN (
    'path', 'package', 'type', 'companion', 'nested', 'member', 'unknown'
  )),
  segment      TEXT    NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, unit_key, seg_ordinal),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "code_units"(
  blob_id                  INTEGER NOT NULL,
  lang                     TEXT    NOT NULL,
  unit_key                 INTEGER NOT NULL,
  kind                     INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 5),
  short_name               TEXT    NOT NULL,
  identifier               TEXT    NOT NULL,
  content_qualifier        TEXT    NOT NULL,
  exact_fqn                TEXT,
  normalized_fqn           TEXT,
  simple_type_name         TEXT,
  signature                TEXT,
  synthetic                INTEGER NOT NULL CHECK(synthetic IN (0, 1)),
  is_type_alias            INTEGER NOT NULL CHECK(is_type_alias IN (0, 1)),
  top_level_ordinal        INTEGER CHECK(top_level_ordinal IS NULL OR top_level_ordinal >= 0),
  in_declarations          INTEGER NOT NULL CHECK(in_declarations IN (0, 1)),
  in_definition_lookup     INTEGER NOT NULL CHECK(in_definition_lookup IN (0, 1)),
  in_test_region           INTEGER NOT NULL DEFAULT 0 CHECK(in_test_region IN (0, 1)),
  fq_anchor_kind           TEXT
    CHECK(fq_anchor_kind IS NULL OR fq_anchor_kind IN ('own_module', 'crate_root')),
  fq_anchor_pop            INTEGER
    CHECK(CASE fq_anchor_kind
      WHEN 'own_module' THEN fq_anchor_pop IS NOT NULL AND fq_anchor_pop BETWEEN 0 AND 255
      WHEN 'crate_root' THEN fq_anchor_pop = 0
      ELSE fq_anchor_kind IS NULL AND fq_anchor_pop IS NULL
    END),
  fq_package_tail_segments INTEGER
    CHECK(fq_package_tail_segments IS NULL OR fq_package_tail_segments >= 0),
  exact_fqn_tail           TEXT,
  normalized_fqn_tail      TEXT
    CHECK(normalized_fqn_tail IS NULL
          OR (exact_fqn_tail IS NOT NULL AND normalized_fqn_tail <> exact_fqn_tail)),
  exact_parent_fqn_tail    TEXT,
  normalized_parent_fqn_tail TEXT
    CHECK(normalized_parent_fqn_tail IS NULL
          OR (exact_parent_fqn_tail IS NOT NULL
              AND normalized_parent_fqn_tail <> exact_parent_fqn_tail)),
  package_fqn_tail         TEXT,
  fq_segment_count         INTEGER NOT NULL DEFAULT 0 CHECK(fq_segment_count >= 0),
  fq_segment_bytes         INTEGER NOT NULL DEFAULT 0 CHECK(fq_segment_bytes >= 0),
  PRIMARY KEY(blob_id, unit_key),
  CHECK(kind <> 5),
  CHECK(NOT (kind = 3 AND lang IN ('javascript', 'python', 'typescript'))),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "import_statements"(
  occurrence_declaration_start_byte INTEGER CHECK(occurrence_declaration_start_byte >= 0) CHECK((declaration_occurrence_id IS NULL) = (occurrence_declaration_start_byte IS NULL)),
  occurrence_declaration_end_byte INTEGER CHECK(occurrence_declaration_end_byte >= occurrence_declaration_start_byte) CHECK((declaration_occurrence_id IS NULL) = (occurrence_declaration_end_byte IS NULL)),
  occurrence_binder_start_byte INTEGER CHECK(occurrence_binder_start_byte >= 0) CHECK((binder_occurrence_id IS NULL) = (occurrence_binder_start_byte IS NULL)),
  occurrence_binder_end_byte INTEGER CHECK(occurrence_binder_end_byte >= occurrence_binder_start_byte) CHECK((binder_occurrence_id IS NULL) = (occurrence_binder_end_byte IS NULL)),
  blob_id                    INTEGER NOT NULL,
  lang                       TEXT NOT NULL,
  ordinal                    INTEGER NOT NULL CHECK(ordinal >= 0),
  source_import_id           INTEGER CHECK(source_import_id >= 0),
  statement                  TEXT,
  is_wildcard                INTEGER DEFAULT 0 CHECK(is_wildcard IS NULL OR is_wildcard IN (0, 1)),
  is_global                  INTEGER DEFAULT 0 CHECK(is_global IS NULL OR is_global IN (0, 1)),
  identifier                 TEXT,
  alias                      TEXT,
  path_kind                  TEXT CHECK(path_kind IS NULL OR path_kind IN (
    'namespace', 'import_from', 'static_member', 'extern_crate'
  )),
  declaration_start_byte     INTEGER CHECK(declaration_start_byte IS NULL OR declaration_start_byte >= 0),
  binder_start               INTEGER CHECK(binder_start IS NULL OR binder_start >= 0),
  binder_end                 INTEGER CHECK(binder_end IS NULL OR binder_end >= 0),
  declaration_occurrence_id  INTEGER CHECK(declaration_occurrence_id IS NULL OR declaration_occurrence_id >= 0),
  binder_occurrence_id       INTEGER CHECK(binder_occurrence_id IS NULL OR binder_occurrence_id >= 0),
  CHECK(source_import_id IS NULL OR (
    statement IS NULL AND is_wildcard IS NULL AND is_global IS NULL
    AND identifier IS NULL AND alias IS NULL AND path_kind IS NULL
    AND declaration_start_byte IS NULL AND binder_start IS NULL
    AND binder_end IS NULL AND declaration_occurrence_id IS NULL
    AND binder_occurrence_id IS NULL
  )),
  CHECK(source_import_id IS NOT NULL OR (
    statement IS NOT NULL AND is_wildcard IS NOT NULL AND is_global IS NOT NULL
  )),
  CHECK((binder_start IS NULL) = (binder_end IS NULL)),
  CHECK(binder_start IS NULL OR binder_start <= binder_end),
  CHECK(path_kind IS NULL OR declaration_start_byte IS NOT NULL
        OR declaration_occurrence_id IS NOT NULL),
  CHECK(
    (declaration_occurrence_id IS NULL AND binder_occurrence_id IS NULL)
    OR (declaration_occurrence_id IS NOT NULL
        AND declaration_start_byte IS NULL
        AND binder_start IS NULL AND binder_end IS NULL)
  ),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, source_import_id)
    REFERENCES source_imports(blob_id, import_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE legacy_resolution_declaration_visibility_properties(
  blob_id                 INTEGER NOT NULL,
  definition_semantic_key INTEGER NOT NULL CHECK(definition_semantic_key >= 0),
  visibility              TEXT NOT NULL,
  PRIMARY KEY(blob_id, definition_semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "materialization_records"(
  blob_id  INTEGER NOT NULL,
  lang     TEXT    NOT NULL,
  ordinal  INTEGER NOT NULL,
  unit_key INTEGER,
  payload  BLOB    NOT NULL,
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE policy_evaluation_identities(
  evaluation_id INTEGER NOT NULL,
  policy_id     TEXT    NOT NULL CHECK(length(policy_id) > 0),
  finding_id    BLOB    NOT NULL CHECK(length(finding_id) = 32),
  PRIMARY KEY(evaluation_id, policy_id, finding_id),
  FOREIGN KEY(evaluation_id) REFERENCES policy_evaluations(evaluation_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE policy_evaluation_units(
  evaluation_id INTEGER NOT NULL,
  policy_id     TEXT    NOT NULL CHECK(length(policy_id) > 0),
  unit_id       INTEGER NOT NULL,
  PRIMARY KEY(evaluation_id, policy_id, unit_id),
  FOREIGN KEY(evaluation_id) REFERENCES policy_evaluations(evaluation_id) ON DELETE CASCADE,
  FOREIGN KEY(unit_id) REFERENCES policy_units(unit_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE policy_evaluations(
  evaluation_id             INTEGER PRIMARY KEY,
  base_tree_oid             TEXT    NOT NULL
    CHECK(length(base_tree_oid) = 40 AND base_tree_oid NOT GLOB '*[^0-9a-f]*'),
  policy_set_digest         TEXT    NOT NULL
    CHECK(length(policy_set_digest) = 64 AND policy_set_digest NOT GLOB '*[^0-9a-f]*'),
  options_digest            TEXT    NOT NULL
    CHECK(length(options_digest) = 64 AND options_digest NOT GLOB '*[^0-9a-f]*'),
  configuration_fingerprint TEXT    NOT NULL
    CHECK(length(configuration_fingerprint) = 64
          AND configuration_fingerprint NOT GLOB '*[^0-9a-f]*'),
  active_model_set_hash     TEXT    NOT NULL
    CHECK(length(active_model_set_hash) = 64
          AND active_model_set_hash NOT GLOB '*[^0-9a-f]*'),
  engine_epoch              TEXT    NOT NULL
    CHECK(length(engine_epoch) = 64 AND engine_epoch NOT GLOB '*[^0-9a-f]*'),
  resolved_commit           TEXT    NOT NULL
    CHECK(length(resolved_commit) = 40 AND resolved_commit NOT GLOB '*[^0-9a-f]*'),
  published_at              INTEGER NOT NULL CHECK(published_at >= 0)
) STRICT;

CREATE TABLE policy_read_keys(
  read_id     INTEGER PRIMARY KEY,
  key_digest  BLOB    NOT NULL CHECK(length(key_digest) = 32),
  kind        TEXT    NOT NULL CHECK(kind IN (
    'file', 'path_absent', 'index', 'lookup', 'artifact', 'scope', 'models',
    'policy', 'configuration', 'epoch'
  )),
  -- The index family, the lookup kind, or the derived-artifact kind.
  family      TEXT,
  -- The languages this key was folded over, as sorted configuration labels: one
  -- for a file read, the whole scope for a scope read.
  languages   TEXT,
  rel_path    TEXT,
  -- The qualified name a declaration question asks about.
  name        TEXT,
  -- The exact bytes of a name-keyed index probe.
  index_key   BLOB,
  blob_oid    TEXT
    CHECK(blob_oid IS NULL
          OR (length(blob_oid) = 40 AND blob_oid NOT GLOB '*[^0-9a-f]*')),
  -- The 32-byte identity this key names: an artifact fingerprint, a call
  -- site's artifact, a summary identity, a content identity, or a policy's
  -- semantic hash.
  subject     BLOB    CHECK(subject IS NULL OR length(subject) = 32),
  start_byte  INTEGER CHECK(start_byte IS NULL OR start_byte >= 0),
  end_byte    INTEGER CHECK(end_byte IS NULL OR end_byte >= start_byte),
  -- The digest of the answer a lookup returned, or the non-source input a
  -- models, policy, configuration or epoch key names.
  digest      BLOB    CHECK(digest IS NULL OR length(digest) = 32),
  CHECK((kind = 'file') = (blob_oid IS NOT NULL)),
  CHECK((kind = 'index') = (index_key IS NOT NULL)),
  -- Only a call-site question locates itself inside its file.
  CHECK(start_byte IS NULL OR kind = 'lookup'),
  CHECK(kind <> 'lookup' OR digest IS NOT NULL),
  CHECK(kind <> 'scope' OR (languages IS NOT NULL AND digest IS NOT NULL)),
  CHECK(kind <> 'artifact' OR subject IS NOT NULL),
  CHECK(kind NOT IN ('models', 'configuration', 'epoch') OR digest IS NOT NULL),
  CHECK(kind <> 'policy' OR (subject IS NOT NULL AND digest IS NOT NULL)),
  CHECK((start_byte IS NULL) = (end_byte IS NULL))
) STRICT;

CREATE TABLE policy_unit_reads(
  unit_id INTEGER NOT NULL,
  read_id INTEGER NOT NULL,
  PRIMARY KEY(unit_id, read_id),
  FOREIGN KEY(unit_id) REFERENCES policy_units(unit_id) ON DELETE CASCADE,
  FOREIGN KEY(read_id) REFERENCES policy_read_keys(read_id)
) WITHOUT ROWID, STRICT;

CREATE TABLE policy_units(
  unit_id                   INTEGER PRIMARY KEY,
  policy_semantic_hash      TEXT    NOT NULL
    CHECK(length(policy_semantic_hash) = 64
          AND policy_semantic_hash NOT GLOB '*[^0-9a-f]*'),
  family                    TEXT    NOT NULL CHECK(family IN (
    'match', 'assertion', 'taint', 'flow', 'typestate'
  )),
  partition_kind            TEXT    NOT NULL CHECK(partition_kind IN (
    'seed', 'binding', 'assert_file', 'root', 'selector', 'whole'
  )),
  seed_rel_path             TEXT    NOT NULL,
  seed_blob_oid             TEXT    NOT NULL
    CHECK(seed_blob_oid = ''
          OR (length(seed_blob_oid) = 40 AND seed_blob_oid NOT GLOB '*[^0-9a-f]*')),
  -- The digest of what this partition covers within its file, for a partition
  -- whose question is narrower than the file: an assert unit's subject rows,
  -- the name of the row binding a relational unit executed, the semantic
  -- locator of the procedure a typestate root unit solved, or the document
  -- path of the selector a selector unit executed. Empty for the partitions
  -- that cover a whole file or the whole workspace.
  partition_digest          TEXT    NOT NULL
    CHECK(partition_digest = ''
          OR (length(partition_digest) = 64 AND partition_digest NOT GLOB '*[^0-9a-f]*')),
  seed_blob_id              INTEGER,
  lang                      TEXT,
  configuration_fingerprint TEXT    NOT NULL
    CHECK(length(configuration_fingerprint) = 64
          AND configuration_fingerprint NOT GLOB '*[^0-9a-f]*'),
  active_model_set_hash     TEXT    NOT NULL
    CHECK(length(active_model_set_hash) = 64
          AND active_model_set_hash NOT GLOB '*[^0-9a-f]*'),
  engine_epoch              TEXT    NOT NULL
    CHECK(length(engine_epoch) = 64 AND engine_epoch NOT GLOB '*[^0-9a-f]*'),
  -- Only an exhaustive, complete unit may be published: a truncated or
  -- diagnostic-bearing execution is not a partition of a whole one, so a
  -- reader must never find one here to reject at load time.
  completion                TEXT    NOT NULL CHECK(completion = 'complete'),
  budget_mode               TEXT    NOT NULL CHECK(budget_mode = 'exhaustive'),
  product_kind              TEXT    NOT NULL CHECK(product_kind IN (
    'rows', 'assert_file', 'root', 'selector'
  )),
  product                   TEXT    NOT NULL CHECK(json_valid(product)),
  read_set_digest           BLOB    NOT NULL CHECK(length(read_set_digest) = 32),
  published_at              INTEGER NOT NULL CHECK(published_at >= 0),
  FOREIGN KEY(seed_blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE,
  -- A file-covering unit names the file it covers and the blob that path
  -- resolved to; a whole-policy unit covers the workspace and names neither.
  CHECK((partition_kind = 'whole') = (seed_rel_path = '')),
  CHECK((partition_kind = 'whole') = (seed_blob_oid = '')),
  -- An assert unit's, a binding unit's, a root unit's and a selector unit's
  -- questions are all narrower than the file they cover; a seed unit's is the
  -- file.
  CHECK((partition_kind IN ('assert_file', 'binding', 'root', 'selector'))
        = (partition_digest <> '')),
  CHECK((seed_blob_id IS NULL) = (lang IS NULL)),
  CHECK(partition_kind <> 'whole' OR seed_blob_id IS NULL),
  -- Rendered rows are a query's product, whether the query is a policy's own
  -- selector or one binding of a relational plan; a file's findings are an
  -- assert's, one root's projected violations are a root's, and one seed
  -- file's selected sites are a selector unit's.
  CHECK((partition_kind = 'assert_file') = (product_kind = 'assert_file')),
  CHECK((partition_kind = 'root') = (product_kind = 'root')),
  CHECK((partition_kind = 'selector') = (product_kind = 'selector'))
) STRICT;

CREATE TABLE reference_fact_epochs(
  lang   TEXT    PRIMARY KEY,
  epoch  INTEGER NOT NULL CHECK(epoch > 0)
) WITHOUT ROWID, STRICT;

CREATE TABLE "reference_identifiers"(
  blob_id    INTEGER NOT NULL,
  lang       TEXT    NOT NULL,
  identifier TEXT    NOT NULL,
  PRIMARY KEY(blob_id, identifier),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_additional_definition_namespaces(
  blob_id                 INTEGER NOT NULL,
  definition_semantic_key INTEGER NOT NULL CHECK(definition_semantic_key >= 0),
  namespace               TEXT NOT NULL CHECK(namespace <> 'type_or_value'),
  hoisting                 TEXT NOT NULL CHECK(hoisting IN ('scope_wide', 'source_order')),
  PRIMARY KEY(blob_id, definition_semantic_key, namespace),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_binding_projections(
  blob_id     INTEGER NOT NULL,
  reference   INTEGER NOT NULL CHECK(reference >= 0),
  output_slot INTEGER NOT NULL CHECK(output_slot >= 0),
  kind        INTEGER NOT NULL CHECK(kind >= 0),
  PRIMARY KEY(blob_id, reference, output_slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

-- `argument_slots` is the value arguments' slots in ordinal order;
-- `type_argument_slots` is `[own, owner, expected, segment]`: `own` is the
-- callable's explicit type arguments' value slots (Rust's turbofish, lifetimes
-- skipped) in position order, `owner` the same for the type segment of the
-- call's path (`Wrapper::<Square>::make()`), `expected` the value slot of the
-- type the call's context expects (a `let` annotation) or null, and `segment`
-- the identity slot of that type segment's reference, null exactly when
-- `owner` is empty. Both columns are read whole with the obligation, by the
-- one reader that decides a generic call's result.
CREATE TABLE resolution_call_obligations(
  blob_id                      INTEGER NOT NULL,
  callee_reference             INTEGER NOT NULL CHECK(callee_reference >= 0),
  call                         INTEGER NOT NULL CHECK(call >= 0),
  receiver_slot                INTEGER CHECK(receiver_slot IS NULL OR receiver_slot >= 0),
  result_slot                  INTEGER NOT NULL CHECK(result_slot >= 0),
  explicit_type_argument_count INTEGER NOT NULL CHECK(explicit_type_argument_count >= 0),
  applicability_reason         INTEGER NOT NULL CHECK(applicability_reason >= 0),
  argument_slots               BLOB NOT NULL CHECK(json_valid(argument_slots, 8)),
  type_argument_slots          BLOB NOT NULL CHECK(json_valid(type_argument_slots, 8)),
  eligible_rules               BLOB NOT NULL CHECK(json_valid(eligible_rules, 8)),
  completion                   BLOB CHECK(completion IS NULL OR json_valid(completion, 8)),
  PRIMARY KEY(blob_id, callee_reference),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

-- Stage callable validation asks which ordinary signature owns one parameter.
-- The primary key serves that lookup and the fragment-parent cascade. Signature
-- ownership is checked against the complete JSONB body when the fragment seals;
-- there is no per-signature cascading scan over all parameters in the blob.
CREATE TABLE resolution_callable_parameter_owners(
  blob_id              INTEGER NOT NULL,
  parameter_definition INTEGER NOT NULL CHECK(parameter_definition >= 0),
  signature_definition INTEGER NOT NULL CHECK(signature_definition >= 0),
  PRIMARY KEY(blob_id, parameter_definition),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_callable_signatures(
  blob_id    INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  body       BLOB NOT NULL CHECK(json_valid(body, 8)),
  PRIMARY KEY(blob_id, definition),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_construction_requirements(
  blob_id                   INTEGER NOT NULL,
  definition                INTEGER NOT NULL CHECK(definition >= 0),
  required_owner_definition INTEGER NOT NULL CHECK(required_owner_definition >= 0),
  kind                      INTEGER NOT NULL CHECK(kind >= 0),
  PRIMARY KEY(blob_id, definition, required_owner_definition, kind),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_contract_references(
  blob_id INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  member_kind INTEGER NOT NULL CHECK(member_kind BETWEEN 0 AND 4),
  position INTEGER NOT NULL CHECK(position >= 0),
  reference_site INTEGER NOT NULL CHECK(reference_site BETWEEN 0 AND 4294967295),
  PRIMARY KEY(blob_id, definition, member_kind, position),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_declaration_types(
  blob_id    INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  role       INTEGER NOT NULL CHECK(role >= 0),
  slot       INTEGER NOT NULL CHECK(slot >= 0),
  PRIMARY KEY(blob_id, definition, role, slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_deferred_member_owners(
  blob_id    INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  seq        INTEGER NOT NULL CHECK(seq >= 0),
  lookup     INTEGER NOT NULL,
  body       BLOB NOT NULL CHECK(json_valid(body, 8)),
  PRIMARY KEY(blob_id, definition, seq),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(lookup) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_definition_property_gaps(
  blob_id    INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  seq        INTEGER NOT NULL CHECK(seq >= 0),
  kind       INTEGER NOT NULL CHECK(kind >= 0),
  frontier   INTEGER NOT NULL CHECK(frontier >= 0),
  reason     INTEGER NOT NULL CHECK(reason >= 0),
  site       INTEGER NOT NULL CHECK(site >= 0),
  PRIMARY KEY(blob_id, definition, seq),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_definition_unit_crosswalks(
  blob_id                 INTEGER NOT NULL,
  definition_semantic_key INTEGER NOT NULL CHECK(definition_semantic_key >= 0),
  unit_key                INTEGER NOT NULL CHECK(unit_key >= 0),
  -- The definition's own fragment-local identity. It is blob-scoped, so it
  -- never enters the workspace-wide shared identity table, and the projection
  -- reader that wants it is operation-free and cannot produce an interior.
  identity_digest         BLOB NOT NULL
    CHECK(typeof(identity_digest) = 'blob' AND length(identity_digest) = 32),
  PRIMARY KEY(blob_id, definition_semantic_key),
  UNIQUE(blob_id, unit_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_fragment_interiors(
  blob_id                                    INTEGER NOT NULL,
  -- `lang` is the storage key carried by blobs (`typescript:tsx`, `cpp:c`).
  -- Lookup digests use the analyzer's semantic configuration label instead.
  lang                                       TEXT NOT NULL,
  semantic_language                          TEXT NOT NULL CHECK(length(semantic_language) > 0),
  producer_epoch                             TEXT NOT NULL CHECK(length(producer_epoch) > 0),
  interior_digest                            BLOB NOT NULL
    CHECK(typeof(interior_digest) = 'blob' AND length(interior_digest) = 32),
  expected_rust_reference_context_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_rust_reference_context_count >= 0),
  expected_rust_declaration_authority_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_rust_declaration_authority_count >= 0),
  expected_semantic_catalog_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_semantic_catalog_count >= 0),
  expected_node_catalog_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_node_catalog_count >= 0),
  expected_contract_reference_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_contract_reference_count >= 0),
  expected_path_endpoint_header_count        INTEGER NOT NULL DEFAULT 0
    CHECK(expected_path_endpoint_header_count >= 0),
  expected_path_terminal_header_count        INTEGER NOT NULL DEFAULT 0
    CHECK(expected_path_terminal_header_count >= 0),
  expected_reference_lookup_identity_count   INTEGER NOT NULL DEFAULT 0
    CHECK(expected_reference_lookup_identity_count >= 0),
  expected_root_route_segment_count          INTEGER NOT NULL DEFAULT 0
    CHECK(expected_root_route_segment_count >= 0),
  expected_semantic_site_count               INTEGER NOT NULL CHECK(expected_semantic_site_count >= 0),
  expected_additional_definition_namespace_count INTEGER NOT NULL DEFAULT 0
    CHECK(expected_additional_definition_namespace_count >= 0),
  expected_definition_unit_crosswalk_count   INTEGER NOT NULL DEFAULT 0
    CHECK(expected_definition_unit_crosswalk_count >= 0),
  expected_declaration_visibility_property_count INTEGER NOT NULL DEFAULT 0
    CHECK(expected_declaration_visibility_property_count >= 0),
  expected_member_scope_property_count         INTEGER NOT NULL DEFAULT 0 CHECK(expected_member_scope_property_count >= 0),
  expected_member_owner_property_count         INTEGER NOT NULL DEFAULT 0 CHECK(expected_member_owner_property_count >= 0),
  expected_trait_implementation_count          INTEGER NOT NULL DEFAULT 0
    CHECK(expected_trait_implementation_count >= 0),
  expected_typed_fact_lookup_count             INTEGER NOT NULL DEFAULT 0
    CHECK(expected_typed_fact_lookup_count >= 0),
  logical_rows                               INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes                              INTEGER NOT NULL CHECK(payload_bytes >= 0),
  publication_state                          TEXT NOT NULL
    CHECK(publication_state IN ('building', 'complete')),
  expected_path_body_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_path_body_count >= 0),
  expected_site_body_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_site_body_count >= 0),
  expected_gap_body_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_gap_body_count >= 0),
  expected_gap_reason_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_gap_reason_count >= 0),
  expected_type_frontier_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_type_frontier_count >= 0),
  expected_type_transfer_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_type_transfer_count >= 0),
  expected_intrinsic_seed_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_intrinsic_seed_count >= 0),
  expected_intrinsic_seed_identity_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_intrinsic_seed_identity_count >= 0),
  expected_binding_projection_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_binding_projection_count >= 0),
  expected_qualified_route_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_qualified_route_count >= 0),
  expected_declaration_type_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_declaration_type_count >= 0),
  expected_deferred_member_owner_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_deferred_member_owner_count >= 0),
  expected_construction_requirement_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_construction_requirement_count >= 0),
  expected_supertype_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_supertype_count >= 0),
  expected_definition_property_gap_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_definition_property_gap_count >= 0),
  expected_call_obligation_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_call_obligation_count >= 0),
  expected_callable_signature_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_callable_signature_count >= 0),
  expected_callable_parameter_owner_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_callable_parameter_owner_count >= 0),
  expected_capsule_input_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_capsule_input_count >= 0),
  expected_capsule_declaration_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_capsule_declaration_count >= 0),
  expected_capsule_reference_context_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_capsule_reference_context_count >= 0),
  PRIMARY KEY(blob_id),
  FOREIGN KEY(blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_gap_reasons(
  blob_id INTEGER NOT NULL,
  -- The reason's blob-local key. A reason has no resolution_semantic_catalog
  -- row (#3737): its key is its position after the catalog's dense rows, so
  -- it equals the in-memory SemanticId and stays below the 1 << 31 floor the
  -- selected stage allocates from. That range is what classifies a reason
  -- key as ordinary rather than stage.
  reason  INTEGER NOT NULL CHECK(reason >= 0),
  -- The `ResolutionSiteId` the lowering blamed.
  site    INTEGER NOT NULL CHECK(site BETWEEN 0 AND 4294967295),
  -- `LoweringGapOrigin`, as its position in `ALL_LOWERING_GAP_ORIGINS`.
  origin  INTEGER NOT NULL CHECK(origin >= 0),
  PRIMARY KEY(blob_id, reason),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_gaps(
  blob_id INTEGER NOT NULL,
  -- 0 fragment, 1 enumeration, 2 forward candidate inventory,
  -- 3 reverse candidate inventory, 4 reference, 5 forward candidate endpoint,
  -- 6 reverse candidate endpoint, 7 type frontier.
  covers  INTEGER NOT NULL CHECK(covers BETWEEN 0 AND 7),
  -- covers 4 and 7: a local semantic key. covers 5 and 6: a local node key,
  -- or -1 for the universal root. covers 0 to 3: 0.
  subject INTEGER NOT NULL CHECK(subject >= -1),
  -- covers 5 and 6: the `resolution_identities.id` of the lookup the branch is
  -- about, or 0 for every lookup. Otherwise 0.
  lookup  INTEGER NOT NULL CHECK(lookup >= 0),
  -- The gap's position in the fragment's digest-ordered gap list, dense from
  -- zero (#3737). A gap has no resolution_semantic_catalog row. The key is
  -- unique within the blob, orders the group the way the draft's ordinal
  -- would, and is what a reverse exclusion plan keys on. Stage gaps take
  -- keys at or above 1 << 31 so the two never collide.
  gap     INTEGER NOT NULL CHECK(gap >= 0),
  -- The gap's reason: a resolution_gap_reasons.reason key of the same blob,
  -- so a reader remounts it on the blob's own fragment.
  reason  INTEGER NOT NULL CHECK(reason >= 0),
  PRIMARY KEY(blob_id, covers, subject, lookup, gap),
  CHECK(covers >= 4 OR (subject = 0 AND lookup = 0)),
  CHECK(covers IN (5, 6) OR lookup = 0),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_identities(
  id              INTEGER PRIMARY KEY,
  identity_digest BLOB NOT NULL UNIQUE
    CHECK(typeof(identity_digest) = 'blob' AND length(identity_digest) = 32),
  -- Milestone 5 draft section 2, milestone 6 checkpoint (lane PK). A lookup
  -- recipe is a property of the name, not of a file, so it is stored once per
  -- store beside the name it belongs to instead of once per blob that mentions
  -- it. Answers question 66, `lookup_recipe`, through
  -- `SelectedResolutionLexicalSource::lookup_semantic_recipes`.
  --
  -- All three are NULL together for a shared identity that is not a lookup
  -- recipe: lane LD measured 17 of tract's 22,206 shared identities as
  -- intrinsic type identities rather than recipes.
  --
  -- `semantic_language` and `namespace` are integer codes, not text labels
  -- (owner decision, 2026-09-18). The code is the value's declaration ordinal
  -- in the vocabulary that owns it: `Language::ALL` for the language and
  -- `ALL_RESOLUTION_NAMESPACES` for the namespace. A vocabulary change rotates
  -- the resolution epoch, and there are no migrations, so the ordinals are
  -- stable for the life of a store.
  semantic_language INTEGER,
  namespace         INTEGER,
  spelling          TEXT,
  CHECK((semantic_language IS NULL) = (namespace IS NULL)),
  CHECK((semantic_language IS NULL) = (spelling IS NULL))
) STRICT;

CREATE TABLE resolution_intrinsic_seed_identities(
  blob_id     INTEGER NOT NULL,
  identity_id INTEGER NOT NULL,
  slot        INTEGER NOT NULL CHECK(slot >= 0),
  PRIMARY KEY(blob_id, identity_id, slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(identity_id) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_intrinsic_seeds(
  blob_id         INTEGER NOT NULL,
  slot            INTEGER NOT NULL CHECK(slot >= 0),
  kind            INTEGER NOT NULL CHECK(kind >= 0),
  spelling        TEXT NOT NULL CHECK(length(spelling) > 0),
  possible_values BLOB NOT NULL CHECK(json_valid(possible_values, 8)),
  completion      BLOB CHECK(completion IS NULL OR json_valid(completion, 8)),
  PRIMARY KEY(blob_id, slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_member_owner_properties(
  blob_id                       INTEGER NOT NULL,
  definition_semantic_key       INTEGER NOT NULL CHECK(definition_semantic_key >= 0),
  owner_definition_semantic_key INTEGER NOT NULL CHECK(owner_definition_semantic_key >= 0),
  owner_scope_head_node_key     INTEGER NOT NULL CHECK(owner_scope_head_node_key >= 0),
  member_kind                   TEXT NOT NULL CHECK(member_kind IN (
    'nested_type', 'method', 'constructor', 'field', 'associated_type'
  )),
  member_access                 TEXT NOT NULL CHECK(member_access IN ('instance', 'type')),
  qualifier_compatibility       TEXT NOT NULL CHECK(qualifier_compatibility IN (
    'runtime_only', 'type_only', 'runtime_or_type'
  )),
  PRIMARY KEY(
    blob_id, definition_semantic_key, owner_definition_semantic_key,
    owner_scope_head_node_key, member_kind, member_access, qualifier_compatibility
  ),
  UNIQUE(blob_id, definition_semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, owner_definition_semantic_key, owner_scope_head_node_key)
    REFERENCES resolution_member_scope_properties(
      blob_id, definition_semantic_key, scope_head_node_key
    ) DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_member_scope_properties(
  blob_id                 INTEGER NOT NULL,
  definition_semantic_key INTEGER NOT NULL CHECK(definition_semantic_key >= 0),
  scope_head_node_key     INTEGER NOT NULL CHECK(scope_head_node_key >= 0),
  PRIMARY KEY(blob_id, definition_semantic_key),
  UNIQUE(blob_id, scope_head_node_key),
  UNIQUE(blob_id, definition_semantic_key, scope_head_node_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_node_catalog(
  blob_id INTEGER NOT NULL,
  local_key INTEGER NOT NULL CHECK(local_key >= 0),
  identity_digest BLOB NOT NULL CHECK(typeof(identity_digest)='blob' AND length(identity_digest)=32),
  source_scope INTEGER CHECK(source_scope IS NULL OR source_scope >= 0),
  kind INTEGER CHECK(kind IS NULL OR kind BETWEEN 0 AND 9),
  -- A NULL kind is catalog-only provenance, not an inferred node declaration.
  semantic_local_key INTEGER CHECK(semantic_local_key IS NULL OR semantic_local_key >= 0),
  semantic_shared_identity INTEGER REFERENCES resolution_identities(id),
  target_local_key INTEGER CHECK(target_local_key IS NULL OR target_local_key >= 0),
  target_boundary_key INTEGER CHECK(target_boundary_key IS NULL OR target_boundary_key = 0),
  CHECK((semantic_local_key IS NOT NULL) + (semantic_shared_identity IS NOT NULL)
    = CASE WHEN kind IN (2,3,4,5,8,9) THEN 1 ELSE 0 END),
  CHECK((target_local_key IS NOT NULL) + (target_boundary_key IS NOT NULL)
    = CASE WHEN kind=7 THEN 1 ELSE 0 END),
  PRIMARY KEY(blob_id, local_key),
  UNIQUE(blob_id, identity_digest),
  UNIQUE(blob_id, source_scope),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_path_endpoint_headers(
  blob_id            INTEGER NOT NULL,
  direction          TEXT NOT NULL CHECK(direction IN ('forward', 'reverse')),
  identity_id        INTEGER,
  symbol_fixed_count INTEGER NOT NULL CHECK(symbol_fixed_count >= 0),
  open_tail          INTEGER NOT NULL CHECK(open_tail IN (0, 1)),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(identity_id) REFERENCES resolution_identities(id),
  CHECK(symbol_fixed_count > 0 OR identity_id IS NULL)
) STRICT;

CREATE TABLE resolution_path_terminal_headers(
  blob_id            INTEGER NOT NULL,
  direction          TEXT NOT NULL CHECK(direction IN ('forward', 'reverse')),
  identity_id        INTEGER NOT NULL,
  symbol_fixed_count INTEGER NOT NULL CHECK(symbol_fixed_count > 0),
  PRIMARY KEY(blob_id, direction, identity_id, symbol_fixed_count),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(identity_id) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_paths(
  blob_id             INTEGER NOT NULL,
  path                INTEGER NOT NULL CHECK(path >= 0),
  start_node          INTEGER NOT NULL CHECK(start_node >= -1),
  start_lead_local    INTEGER CHECK(start_lead_local IS NULL OR start_lead_local >= 0),
  start_lead_identity INTEGER,
  start_lead_scoped   INTEGER NOT NULL CHECK(start_lead_scoped IN (0, 1)),
  end_node            INTEGER NOT NULL CHECK(end_node >= -1),
  end_lead_local      INTEGER CHECK(end_lead_local IS NULL OR end_lead_local >= 0),
  end_lead_identity   INTEGER,
  end_lead_scoped     INTEGER NOT NULL CHECK(end_lead_scoped IN (0, 1)),
  root_terminal       INTEGER,
  body                BLOB NOT NULL CHECK(json_valid(body, 8)),
  end_fixed_key       TEXT COLLATE BINARY,
  end_open_tail       INTEGER,
  CHECK(start_lead_local IS NULL OR start_lead_identity IS NULL),
  CHECK(end_lead_local IS NULL OR end_lead_identity IS NULL),
  CHECK((end_node = -1 AND end_fixed_key IS NOT NULL
         AND end_open_tail IS NOT NULL AND end_open_tail IN (0, 1))
     OR (end_node <> -1 AND end_fixed_key IS NULL AND end_open_tail IS NULL)),
  CHECK(end_fixed_key IS NULL OR (
    json_valid(end_fixed_key) AND json_type(end_fixed_key) = 'array'
    AND json(end_fixed_key) = end_fixed_key
    AND json_type(body, '$[4]') = 'array'
    AND json_array_length(end_fixed_key) = json_array_length(body, '$[4]')
    AND json_type(body, '$[5]') IN ('null', 'integer')
    AND end_open_tail = (json_type(body, '$[5]') = 'integer')
  ) IS TRUE),
  PRIMARY KEY(blob_id, path),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(start_lead_identity) REFERENCES resolution_identities(id),
  FOREIGN KEY(end_lead_identity) REFERENCES resolution_identities(id),
  FOREIGN KEY(root_terminal) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_producer_epochs(
  lang           TEXT NOT NULL,
  producer_epoch TEXT NOT NULL CHECK(length(producer_epoch) > 0),
  PRIMARY KEY(lang)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_qualified_routes(
  blob_id                 INTEGER NOT NULL,
  reference               INTEGER NOT NULL CHECK(reference >= 0),
  precedence_ordinal      INTEGER NOT NULL CHECK(precedence_ordinal >= 0),
  qualifier_slot          INTEGER NOT NULL CHECK(qualifier_slot >= 0),
  lookup                  INTEGER NOT NULL,
  source_lookup           INTEGER NOT NULL,
  namespace               INTEGER NOT NULL CHECK(namespace >= 0),
  projection_output_slot  INTEGER NOT NULL CHECK(projection_output_slot >= 0),
  projection_kind         INTEGER NOT NULL CHECK(projection_kind >= 0),
  coarse_gap_reason       INTEGER NOT NULL CHECK(coarse_gap_reason >= 0),
  -- The producer's statement that this owner's member surface is not closed,
  -- so a hierarchy walk that reaches no declaring owner has proved nothing.
  -- Rust sets it for a qualified member lookup on a nominal owner, where a
  -- blanket impl, a trait bound, a Deref chain or a trait from an unindexed
  -- crate can each supply a member the indexed impls never mention. A
  -- language whose member surface is closed leaves it 0 and keeps its proved
  -- absences.
  open_member_surface     INTEGER NOT NULL DEFAULT 0 CHECK(open_member_surface IN (0, 1)),
  PRIMARY KEY(blob_id, reference, precedence_ordinal, projection_output_slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(lookup) REFERENCES resolution_identities(id),
  FOREIGN KEY(source_lookup) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_reference_lookup_identities(
  blob_id INTEGER NOT NULL,
  semantic_key INTEGER NOT NULL,
  identity_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(identity_id) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_root_route_segments (
  blob_id INTEGER NOT NULL,
  path_key INTEGER NOT NULL,
  position INTEGER NOT NULL CHECK(position >= 0),
  -- Positions 0..n-1 spell the module path one segment at a time; the row at
  -- position n closes the route with the name it demands and the reference
  -- site that demands it. Exactly one of the two shapes is present per row.
  segment TEXT CHECK(segment IS NULL OR length(segment) > 0),
  terminal_spelling TEXT CHECK(terminal_spelling IS NULL OR length(terminal_spelling) > 0),
  reference_source_site INTEGER
    CHECK(reference_source_site IS NULL OR reference_source_site BETWEEN 0 AND 4294967295),
  reference_start_byte INTEGER CHECK(reference_start_byte IS NULL OR reference_start_byte >= 0),
  reference_end_byte INTEGER
    CHECK(reference_end_byte IS NULL OR reference_end_byte >= reference_start_byte),
  PRIMARY KEY(blob_id, path_key, position),
  CHECK((segment IS NULL) = (terminal_spelling IS NOT NULL)),
  CHECK((terminal_spelling IS NULL) = (reference_source_site IS NULL)),
  CHECK((terminal_spelling IS NULL) = (reference_start_byte IS NULL)),
  CHECK((terminal_spelling IS NULL) = (reference_end_byte IS NULL)),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_rust_declaration_authorities(
  blob_id INTEGER NOT NULL,
  semantic_key INTEGER NOT NULL CHECK(semantic_key >= 0),
  source_site INTEGER NOT NULL CHECK(source_site >= 0),
  declaration INTEGER NOT NULL CHECK(declaration >= 0),
  visibility BLOB CHECK(visibility IS NULL OR (json_valid(visibility, 8) AND json_type(visibility)='array')),
  module_context INTEGER NOT NULL CHECK(module_context >= 0),
  module_declaration INTEGER CHECK(module_declaration IS NULL OR module_declaration >= 0),
  cfg_condition BLOB NOT NULL CHECK(json_valid(cfg_condition, 8) AND json_type(cfg_condition)='array'),
  activation_reason INTEGER CHECK(activation_reason IS NULL OR activation_reason >= 0),
  PRIMARY KEY(blob_id, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_rust_reference_contexts(
  blob_id INTEGER NOT NULL,
  semantic_key INTEGER NOT NULL CHECK(semantic_key >= 0),
  source_site INTEGER NOT NULL CHECK(source_site >= 0),
  source_occurrence INTEGER NOT NULL CHECK(source_occurrence >= 0),
  module_context INTEGER NOT NULL CHECK(module_context >= 0),
  module_declaration INTEGER CHECK(module_declaration IS NULL OR module_declaration >= 0),
  cfg_condition BLOB NOT NULL CHECK(json_valid(cfg_condition, 8) AND json_type(cfg_condition)='array'),
  PRIMARY KEY(blob_id, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_semantic_catalog(
  blob_id INTEGER NOT NULL,
  local_key INTEGER NOT NULL CHECK(local_key >= 0),
  identity_digest BLOB CHECK(identity_digest IS NULL OR (typeof(identity_digest)='blob' AND length(identity_digest)=32)),
  shared_identity INTEGER REFERENCES resolution_identities(id),
  CHECK((identity_digest IS NULL) <> (shared_identity IS NULL)),
  PRIMARY KEY(blob_id, local_key),
  UNIQUE(blob_id, identity_digest),
  UNIQUE(blob_id, shared_identity),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_semantic_sites(
  blob_id       INTEGER NOT NULL,
  source_site   INTEGER NOT NULL CHECK(source_site BETWEEN 0 AND 4294967295),
  namespace     TEXT NOT NULL,
  semantic_role TEXT NOT NULL CHECK(semantic_role IN ('reference', 'definition')),
  semantic_key  INTEGER NOT NULL CHECK(semantic_key >= 0),
  PRIMARY KEY(blob_id, source_site),
  UNIQUE(blob_id, semantic_role, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_sites(
  blob_id         INTEGER NOT NULL,
  -- ResolutionSiteId, and equally the blob-local semantic key and node key.
  site            INTEGER NOT NULL CHECK(site BETWEEN 0 AND 4294967295),
  role            INTEGER NOT NULL CHECK(role IN (0, 1)),   -- 0 reference, 1 definition
  namespace       INTEGER NOT NULL CHECK(namespace >= 0),
  -- A site with no published reference metadata carries no kind, range,
  -- qualification or receiver: on tract that is exactly the definition rows.
  site_kind       INTEGER CHECK(site_kind IS NULL OR site_kind >= 0),
  start_byte      INTEGER CHECK(start_byte IS NULL OR start_byte >= 0),
  end_byte        INTEGER CHECK(end_byte IS NULL OR end_byte >= start_byte),
  unqualified     INTEGER CHECK(unqualified IS NULL OR unqualified IN (0, 1)),
  -- The declaration the reference sits in, as a blob-local semantic key.
  -- -1 means "in no declaration"; NULL means the producer published no
  -- ownership at all.
  owner           INTEGER CHECK(owner IS NULL OR owner >= -1),
  receiver_origin INTEGER CHECK(receiver_origin IS NULL OR receiver_origin >= 0),
  CHECK((site_kind IS NULL) = (start_byte IS NULL)),
  CHECK((site_kind IS NULL) = (end_byte IS NULL)),
  CHECK((site_kind IS NULL) = (unqualified IS NULL)),
  PRIMARY KEY(blob_id, site),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_supertypes(
  blob_id    INTEGER NOT NULL,
  definition INTEGER NOT NULL CHECK(definition >= 0),
  kind       INTEGER NOT NULL CHECK(kind >= 0),
  reference  INTEGER NOT NULL CHECK(reference >= 0),
  frontier   INTEGER NOT NULL CHECK(frontier >= 0),
  -- The draft keyed this `(blob_id, definition, reference)`. The lowering's own
  -- uniqueness assertion is over `(definition, kind, reference, frontier)`
  -- (`typed_fact_lowering.rs`, `assert_unique_lowered_rows`), which is also the
  -- row's `natural_identity`, so the narrower key would have made a legal
  -- fragment fail at index time on a constraint rather than answer.
  PRIMARY KEY(blob_id, definition, kind, reference, frontier),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_trait_implementations (
  blob_id INTEGER NOT NULL,
  relation_key INTEGER NOT NULL CHECK(relation_key >= 0),
  -- Which half of `impl Trait for Type` this route spells.
  side TEXT NOT NULL CHECK(side IN ('subject', 'trait')),
  position INTEGER NOT NULL CHECK(position >= 0),
  -- Positions 0..n-1 spell the module path one segment at a time; the row at
  -- position n closes the side with the head nominal name it demands. Exactly
  -- one of the two shapes is present per row. A bare name has no segment row,
  -- so its terminal sits at position 0 and the derivation walks from the
  -- impl's own module.
  segment TEXT CHECK(segment IS NULL OR length(segment) > 0),
  terminal_spelling TEXT CHECK(terminal_spelling IS NULL OR length(terminal_spelling) > 0),
  -- The subject type reference's source site and byte span, which place the
  -- impl in the module whose body contains it, inline modules included.
  impl_site INTEGER NOT NULL CHECK(impl_site BETWEEN 0 AND 4294967295),
  impl_start_byte INTEGER NOT NULL CHECK(impl_start_byte >= 0),
  impl_end_byte INTEGER NOT NULL CHECK(impl_end_byte >= impl_start_byte),
  PRIMARY KEY(blob_id, relation_key, side, position),
  CHECK((segment IS NULL) = (terminal_spelling IS NOT NULL)),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_type_frontiers(
  blob_id            INTEGER NOT NULL,
  slot               INTEGER NOT NULL CHECK(slot >= 0),
  role               INTEGER NOT NULL CHECK(role >= 0),
  identity_reference INTEGER CHECK(identity_reference IS NULL OR identity_reference >= 0),
  PRIMARY KEY(blob_id, slot),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_type_transfers(
  blob_id                     INTEGER NOT NULL,
  source_slot                 INTEGER NOT NULL CHECK(source_slot >= 0),
  rule                        INTEGER NOT NULL CHECK(rule >= 0),
  target_slot                 INTEGER NOT NULL CHECK(target_slot >= 0),
  kind                        INTEGER NOT NULL CHECK(kind >= 0),
  indirection_delta           INTEGER NOT NULL,
  reference_indirection_delta INTEGER NOT NULL,
  value_transform             INTEGER NOT NULL CHECK(value_transform BETWEEN 0 AND 3),
  completion                  BLOB CHECK(completion IS NULL OR json_valid(completion, 8)),
  PRIMARY KEY(blob_id, source_slot, rule),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_typed_fact_lookups(
  blob_id     INTEGER NOT NULL,
  relation    INTEGER NOT NULL CHECK(relation >= 0),
  identity_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, relation, identity_id),
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(identity_id) REFERENCES resolution_identities(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE "ruby_method_dispatch_modes"(
  blob_id  INTEGER NOT NULL,
  lang     TEXT    NOT NULL,
  unit_key INTEGER NOT NULL,
  mode     INTEGER NOT NULL CHECK(mode BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, unit_key),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_container_sources(
  topology_id       INTEGER NOT NULL,
  container_path    TEXT NOT NULL,
  blob_id           INTEGER NOT NULL,
  scope_ordinal     INTEGER CHECK(scope_ordinal >= 0),
  rel_path          TEXT NOT NULL CHECK(length(rel_path) > 0),
  source_kind       TEXT NOT NULL CHECK(source_kind IN ('declared', 'include')),
  enum_scope_node_key INTEGER CHECK(enum_scope_node_key >= 0),
  -- The container that declares this one, which the module walk and the enum
  -- derivation both hold when they build `container_path` from it. NULL only
  -- for the crate root. The textual-macro climb seeks the declaring
  -- container's own source rows on it through the primary key.
  parent_container_path TEXT,
  CHECK((scope_ordinal IS NULL) <> (enum_scope_node_key IS NULL)),
  CHECK((container_path = 'crate') = (parent_container_path IS NULL)),
  PRIMARY KEY(topology_id, container_path, blob_id),
  FOREIGN KEY(topology_id, container_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE,
  FOREIGN KEY(blob_id) REFERENCES blobs(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_containers(
  topology_id       INTEGER NOT NULL,
  container_path    TEXT NOT NULL CHECK(container_path = 'crate' OR container_path LIKE 'crate::%'),
  kind              TEXT NOT NULL CHECK(kind IN ('module', 'enum')),
  placement         TEXT NOT NULL CHECK(placement IN
    ('root', 'mod_declaration', 'path_attribute', 'inline', 'enum_declaration')),
  PRIMARY KEY(topology_id, container_path),
  CHECK((container_path = 'crate') = (placement = 'root')),
  CHECK((kind = 'enum') = (placement = 'enum_declaration')),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_dependencies(
  topology_id           INTEGER NOT NULL,
  extern_name           TEXT NOT NULL CHECK(length(extern_name) > 0),
  boundary              TEXT NOT NULL CHECK(boundary IN ('workspace', 'external', 'std')),
  dependency_crate_key  BLOB
    CHECK(dependency_crate_key IS NULL OR
          (typeof(dependency_crate_key) = 'blob' AND length(dependency_crate_key) = 32)),
  dependency_kind       TEXT NOT NULL CHECK(dependency_kind IN ('normal', 'dev', 'build')),
  PRIMARY KEY(topology_id, extern_name),
  CHECK((boundary = 'workspace') = (dependency_crate_key IS NOT NULL)),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_exports(
  topology_id             INTEGER NOT NULL,
  module_path             TEXT NOT NULL,
  namespace               TEXT NOT NULL CHECK(namespace IN ('type', 'value', 'macro')),
  name                    TEXT NOT NULL CHECK(length(name) > 0),
  origin                  TEXT NOT NULL CHECK(origin IN ('declaration', 'reexport', 'glob_reexport')),
  visibility              TEXT NOT NULL CHECK(visibility IN ('public', 'crate', 'restricted', 'private')),
  restricted_module_path  TEXT CHECK(restricted_module_path IS NULL OR restricted_module_path LIKE 'crate%'),
  declaration_blob_id     INTEGER NOT NULL,
  declaration_site        INTEGER NOT NULL CHECK(declaration_site >= 0),   -- resolution_semantic_sites.source_site
  PRIMARY KEY(topology_id, module_path, namespace, name),
  CHECK((visibility = 'restricted') = (restricted_module_path IS NOT NULL)),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE,
  FOREIGN KEY(declaration_blob_id) REFERENCES blobs(id)
) WITHOUT ROWID, STRICT;

-- The item-position macro invocations crate derivation decided
-- (`rust_crate_item_macro_decisions.sql`), one row per crate and invocation.
-- A row means the visible definition is a passthrough whose rules replay each
-- argument item and add nothing but a `cfg` decoration to it, so the
-- expansion is the arguments' items, each under `decoration_cfg` (encoded like
-- an item's `cfg_condition`, `always` when the rules add nothing). An
-- invocation without a row is undecided: its expansion is not known. Reader:
-- the member-family walk, which does not replay an invocation written at
-- statement position and so asks whether its expansion could declare an impl;
-- only a decided one cannot add one beyond its own arguments.
CREATE TABLE rust_crate_decided_item_macros(
  topology_id              INTEGER NOT NULL REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE,
  blob_id                  INTEGER NOT NULL REFERENCES blobs(id),
  invocation_occurrence_id INTEGER NOT NULL CHECK(invocation_occurrence_id >= 0),
  decoration_cfg           TEXT NOT NULL CHECK(length(decoration_cfg) > 0),
  PRIMARY KEY(topology_id, blob_id, invocation_occurrence_id)
) WITHOUT ROWID, STRICT;

-- The items a decided passthrough invocation declares when the invoking file
-- could not declare them (the macro is defined in another file). Written by
-- crate derivation (`rust_crate_macro_items.sql`), one row per item: its
-- identity is declaration replay's declaration in the invoking file, which
-- carries the `CodeUnit`. Readers: the crate route's module step (a `mod`
-- item names the container `module_path::name`), the point route's terminal
-- lookup by (topology, module, namespace, name), the request's preparation,
-- which asks for the invoking files of items with one name, and the
-- definition projection, which links the invoking file's staged capsule
-- definition to the item's `CodeUnit`.
CREATE TABLE rust_crate_macro_items(
  topology_id              INTEGER NOT NULL,
  module_path              TEXT NOT NULL,
  namespace                TEXT NOT NULL CHECK(namespace IN ('type', 'value')),
  name                     TEXT NOT NULL CHECK(length(name) > 0),
  visibility               TEXT NOT NULL CHECK(visibility IN ('public', 'crate', 'restricted', 'private')),
  restricted_module_path   TEXT CHECK(restricted_module_path IS NULL OR restricted_module_path LIKE 'crate%'),
  blob_id                  INTEGER NOT NULL,   -- the invoking file
  invocation_occurrence_id INTEGER NOT NULL CHECK(invocation_occurrence_id >= 0),
  declaration_id           INTEGER NOT NULL CHECK(declaration_id >= 0),   -- declaration replay's
  module_item              INTEGER NOT NULL CHECK(module_item IN (0, 1)),
  PRIMARY KEY(topology_id, module_path, namespace, name, blob_id, declaration_id),
  CHECK((visibility = 'restricted') = (restricted_module_path IS NOT NULL)),
  CHECK(module_item = 0 OR namespace = 'type'),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE,
  FOREIGN KEY(blob_id) REFERENCES blobs(id)
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_file_naming(
  topology_id INTEGER NOT NULL REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE,
  rel_path TEXT NOT NULL,
  package_components BLOB NOT NULL CHECK(json_valid(package_components,8) AND json_type(package_components)='array'),
  root_components BLOB NOT NULL CHECK(json_valid(root_components,8) AND json_type(root_components)='array'),
  PRIMARY KEY(topology_id, rel_path)
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_gaps(
  topology_id     INTEGER NOT NULL,
  gap_kind        TEXT NOT NULL CHECK(gap_kind IN
    ('external_dependency', 'unsupported_manifest', 'inactive_placement', 'unknown_activation',
     'unplaced_module', 'duplicate_placement', 'unresolved_import', 'unresolved_reexport',
     'open_export_inventory', 'unresolved_visibility', 'unresolved_trait_impl')),
  subject         TEXT NOT NULL,                               -- module path, extern name, or rel_path the gap is about
  detail          BLOB NOT NULL CHECK(json_valid(detail, 8) AND json_type(detail) = 'object'),
  PRIMARY KEY(topology_id, gap_kind, subject),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_glob_imports(
  topology_id           INTEGER NOT NULL,
  module_path           TEXT NOT NULL,
  blob_id               INTEGER NOT NULL REFERENCES blobs(id),
  import_ordinal        INTEGER NOT NULL CHECK(import_ordinal >= 0),
  binder_scope          INTEGER NOT NULL CHECK(binder_scope >= 0),
  target_crate_key      BLOB NOT NULL
    CHECK(typeof(target_crate_key) = 'blob' AND length(target_crate_key) = 32),
  target_module_path    TEXT NOT NULL,
  PRIMARY KEY(topology_id, module_path, blob_id, binder_scope, import_ordinal),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_glob_reexport_routes(
  topology_id           INTEGER NOT NULL,
  module_path           TEXT NOT NULL,
  target_crate_key       BLOB NOT NULL
    CHECK(typeof(target_crate_key) = 'blob' AND length(target_crate_key) = 32),
  target_module_path     TEXT NOT NULL,
  visibility            TEXT NOT NULL CHECK(visibility IN ('public', 'crate', 'restricted', 'private')),
  restricted_module_path TEXT,
  PRIMARY KEY(topology_id, module_path, target_crate_key, target_module_path),
  CHECK((visibility = 'restricted') = (restricted_module_path IS NOT NULL)),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_imports(
  topology_id           INTEGER NOT NULL,
  module_path           TEXT NOT NULL,
  namespace             TEXT NOT NULL CHECK(namespace IN ('type', 'value', 'macro')),
  bound_name            TEXT NOT NULL CHECK(length(bound_name) > 0),
  blob_id               INTEGER NOT NULL REFERENCES blobs(id),
  import_ordinal        INTEGER NOT NULL CHECK(import_ordinal >= 0),   -- source_rust_import_targets.ordinal in the module's blob
  binder_scope          INTEGER NOT NULL CHECK(binder_scope >= 0),     -- blob-local ResolutionScopeId the binder lives in
  target_crate_key      BLOB NOT NULL
    CHECK(typeof(target_crate_key) = 'blob' AND length(target_crate_key) = 32),
  target_module_path    TEXT NOT NULL,
  target_name           TEXT NOT NULL,
  PRIMARY KEY(topology_id, module_path, blob_id, binder_scope, namespace, bound_name),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_reexport_routes(
  topology_id           INTEGER NOT NULL,
  module_path           TEXT NOT NULL,
  bound_name            TEXT NOT NULL,
  target_crate_key       BLOB NOT NULL
    CHECK(typeof(target_crate_key) = 'blob' AND length(target_crate_key) = 32),
  target_module_path     TEXT NOT NULL,
  target_name            TEXT NOT NULL,
  visibility            TEXT NOT NULL CHECK(visibility IN ('public', 'crate', 'restricted', 'private')),
  restricted_module_path TEXT,
  PRIMARY KEY(topology_id, module_path, bound_name, target_crate_key, target_module_path, target_name),
  CHECK((visibility = 'restricted') = (restricted_module_path IS NOT NULL)),
  FOREIGN KEY(topology_id, module_path) REFERENCES rust_crate_containers(topology_id, container_path) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_root_references (
  topology_id INTEGER NOT NULL,
  module_path TEXT NOT NULL,
  blob_id INTEGER NOT NULL,
  path_key INTEGER NOT NULL,
  reference_source_site INTEGER NOT NULL
    CHECK(reference_source_site BETWEEN 0 AND 4294967295),
  target_crate_key BLOB NOT NULL
    CHECK(typeof(target_crate_key) = 'blob' AND length(target_crate_key)=32),
  target_module_path TEXT NOT NULL,
  target_name TEXT NOT NULL,
  PRIMARY KEY(topology_id, module_path, blob_id, path_key),
  FOREIGN KEY(topology_id, module_path, blob_id)
    REFERENCES rust_crate_container_sources(topology_id, container_path, blob_id)
    ON DELETE CASCADE,
  FOREIGN KEY(blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_topologies(
  topology_id           INTEGER PRIMARY KEY,
  topology_digest       BLOB NOT NULL UNIQUE
    CHECK(typeof(topology_digest) = 'blob' AND length(topology_digest) = 32),
  crate_key             BLOB NOT NULL
    CHECK(typeof(crate_key) = 'blob' AND length(crate_key) = 32),
  producer_epoch        TEXT NOT NULL CHECK(length(producer_epoch) > 0),
  target_kind           TEXT NOT NULL CHECK(target_kind IN
    ('lib', 'bin', 'test', 'example', 'bench', 'build', 'detached')),
  crate_name            TEXT NOT NULL CHECK(length(crate_name) > 0),
  edition               TEXT NOT NULL CHECK(edition IN ('2015', '2018', '2021', '2024')),
  -- The crate's implicit prelude: `std`, `core` under `#![no_std]`, or none
  -- under `#![no_core]` (which wins over `no_std`), read from the crate root
  -- file's `source_rust_inner_attributes`.
  prelude               TEXT NOT NULL CHECK(prelude IN ('std', 'core', 'none')),
  -- the cfg set as a JSON array of atoms: ["test", "unix", "feature=\"serde\""];
  -- read whole by the cfg evaluator at derivation, never joined
  cfg_atoms             BLOB NOT NULL CHECK(json_valid(cfg_atoms, 8) AND json_type(cfg_atoms) = 'array'),
  inventory_complete    INTEGER NOT NULL CHECK(inventory_complete IN (0, 1)),
  export_surface_digest BLOB
    CHECK(export_surface_digest IS NULL OR
          (typeof(export_surface_digest) = 'blob' AND length(export_surface_digest) = 32)),
  publication_state     TEXT NOT NULL CHECK(publication_state IN ('building', 'complete')),
  CHECK((publication_state = 'complete') = (export_surface_digest IS NOT NULL))
) STRICT;

CREATE TABLE rust_crate_trait_impls (
  topology_id INTEGER NOT NULL,
  -- Both ends are the declaration itself, as `rust_crate_exports` identifies
  -- one: a type reached through a re-export and the same type reached through
  -- its declaring module are one row here, where a (crate, module, name)
  -- triple would have been two that miss each other. A reader that wants the
  -- names joins `rust_crate_exports` by `rust_crate_exports_declaration`.
  --
  -- Each end also carries its placement: the file the crate places the
  -- declaring module in, as `rust_crate_container_sources.rel_path` spells it.
  -- A declaration's `(blob, site)` is content-addressed, so two byte-identical
  -- files declare one `(blob, site)`; the placement is what keeps
  -- `one::Runnable` and `two::Runnable` two ends, the way a resolution mount
  -- keeps them two mounts. A reader asks by a `CodeUnit`, whose file is this
  -- path. The impl's own crate is `topology_id`; an end declared in another
  -- crate names no topology, because crate rows refer across crates by crate
  -- key and a dependency's topology can be replaced without this crate being
  -- derived again.
  subject_declaration_blob_id INTEGER NOT NULL,
  subject_declaration_site INTEGER NOT NULL
    CHECK(subject_declaration_site BETWEEN 0 AND 4294967295),
  subject_rel_path TEXT NOT NULL CHECK(length(subject_rel_path) > 0),
  trait_declaration_blob_id INTEGER NOT NULL,
  trait_declaration_site INTEGER NOT NULL
    CHECK(trait_declaration_site BETWEEN 0 AND 4294967295),
  trait_rel_path TEXT NOT NULL CHECK(length(trait_rel_path) > 0),
  impl_blob_id INTEGER NOT NULL,
  impl_site INTEGER NOT NULL CHECK(impl_site BETWEEN 0 AND 4294967295),
  impl_rel_path TEXT NOT NULL CHECK(length(impl_rel_path) > 0),
  -- The impl item's own source declaration, the key the hierarchy source
  -- facts address it by. `impl_site` is the subject type's resolution site,
  -- which no source fact names; the derivation reaches the declaration through
  -- that reference's source occurrence, the path segment it is, and the impl
  -- item whose subject type the segment belongs to. NULL when that bridge does
  -- not name exactly one impl item, in which case a reader resolves the header.
  impl_declaration_id INTEGER
    CHECK(impl_declaration_id IS NULL OR impl_declaration_id BETWEEN 0 AND 4294967295),
  PRIMARY KEY(topology_id, subject_declaration_blob_id, subject_declaration_site,
              subject_rel_path, trait_declaration_blob_id, trait_declaration_site,
              trait_rel_path, impl_blob_id, impl_site, impl_rel_path),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE,
  FOREIGN KEY(subject_declaration_blob_id) REFERENCES blobs(id),
  FOREIGN KEY(trait_declaration_blob_id) REFERENCES blobs(id),
  FOREIGN KEY(impl_blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_unresolved_trait_impls (
  topology_id INTEGER NOT NULL,
  -- Which half of `impl Trait for Type` did not reach a declaration. Both
  -- halves are recorded: a reader asking whether a trait's implementations
  -- are enumerable wants the `trait` side, and one asking whether a type's
  -- implemented traits are wants `subject`.
  side TEXT NOT NULL CHECK(side IN ('subject', 'trait')),
  -- The head nominal name the unresolved side demanded, as written. This is
  -- the column the question is asked by: `rust_crate_gaps` already records
  -- the same evidence, but only inside its `detail` JSON keyed by module
  -- path, so asking "is anything spelled `Display` unbound here?" meant
  -- scanning and parsing every gap row.
  spelling TEXT NOT NULL CHECK(length(spelling) > 0),
  impl_blob_id INTEGER NOT NULL,
  impl_site INTEGER NOT NULL CHECK(impl_site BETWEEN 0 AND 4294967295),
  -- The file the crate places the impl in. Two byte-identical files are one
  -- blob, so without it an impl in either would send a reader to both.
  impl_rel_path TEXT NOT NULL CHECK(length(impl_rel_path) > 0),
  -- The impl item's source declaration, as `rust_crate_trait_impls` carries
  -- it; NULL when the bridge does not name exactly one impl item.
  impl_declaration_id INTEGER
    CHECK(impl_declaration_id IS NULL OR impl_declaration_id BETWEEN 0 AND 4294967295),
  -- `unbound` when no route bound this side at all, `bound_without_declaration`
  -- when a route bound a name whose declaration the derivation could not
  -- reach, and `resolved` when this side was fine and the impl is here because
  -- its other side was not. Part of the key so that one impl placed in two
  -- modules keeps both verdicts rather than letting an arbitrary one win.
  reason TEXT NOT NULL CHECK(reason IN ('unbound', 'bound_without_declaration', 'resolved')),
  -- The module the route reached, when it reached one.
  target_module_path TEXT CHECK(target_module_path IS NULL OR length(target_module_path) > 0),
  PRIMARY KEY(topology_id, side, spelling, impl_blob_id, impl_site, impl_rel_path, reason),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id) ON DELETE CASCADE,
  FOREIGN KEY(impl_blob_id) REFERENCES resolution_fragment_interiors(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE rust_crate_versions(
  workspace_id              TEXT NOT NULL CHECK(length(workspace_id) = 64),
  lang                      TEXT NOT NULL,
  generation                INTEGER NOT NULL CHECK(generation >= 0),
  crate_key                 BLOB NOT NULL
    CHECK(typeof(crate_key) = 'blob' AND length(crate_key) = 32),
  valid_from                INTEGER NOT NULL CHECK(valid_from > 0),
  valid_until               INTEGER CHECK(valid_until IS NULL OR valid_until > valid_from),
  manifest_file_version_id  INTEGER,                       -- NULL for detached
  topology_id               INTEGER NOT NULL,
  PRIMARY KEY(workspace_id, lang, generation, crate_key, valid_from),
  FOREIGN KEY(manifest_file_version_id) REFERENCES workspace_file_versions(file_version_id),
  FOREIGN KEY(topology_id) REFERENCES rust_crate_topologies(topology_id)
) WITHOUT ROWID, STRICT;

-- The last complete crate reconcile of one workspace generation: the head
-- revision it made the crate rows current for and the derivation version it
-- derived under. A from-scratch pass writes the row; a scoped pass after an
-- incremental update advances `revision` only from the revision it started
-- at. A warm start whose head revision and derivation version both match
-- skips the from-scratch pass, because every input of every topology digest
-- is then unchanged.
CREATE TABLE rust_crate_reconciliations(
  workspace_id        TEXT NOT NULL CHECK(length(workspace_id) = 64),
  generation          INTEGER NOT NULL CHECK(generation >= 0),
  revision            INTEGER NOT NULL CHECK(revision > 0),
  derivation_version  TEXT NOT NULL CHECK(length(derivation_version) > 0),
  PRIMARY KEY(workspace_id, generation)
) WITHOUT ROWID, STRICT;

CREATE TABLE "rust_exports"(
  blob_id          INTEGER NOT NULL,
  lang             TEXT NOT NULL,
  ordinal          INTEGER NOT NULL,
  source_import_id INTEGER CHECK(source_import_id >= 0),
  exported_name    TEXT,
  source_path      TEXT,
  imported_name    TEXT,
  is_glob          INTEGER DEFAULT 0 CHECK(is_glob IS NULL OR is_glob IN (0, 1)),
  CHECK(source_import_id IS NULL OR (
    source_path IS NULL AND imported_name IS NULL AND is_glob IS NULL
  )),
  CHECK(source_import_id IS NOT NULL OR (source_path IS NOT NULL AND is_glob IS NOT NULL)),
  PRIMARY KEY(blob_id, lang, ordinal),
  FOREIGN KEY(blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, source_import_id) REFERENCES source_imports(blob_id, import_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE "rust_identifier_occurrences"(
  blob_id      INTEGER NOT NULL,
  lang         TEXT    NOT NULL,
  identifier   TEXT    NOT NULL,
  context_mask INTEGER NOT NULL,
  PRIMARY KEY(blob_id, identifier),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "rust_import_targets"(
  declaration_start_byte INTEGER CHECK(declaration_start_byte >= 0) CHECK((declaration_occurrence_id IS NULL) = (declaration_start_byte IS NULL)),
  declaration_end_byte INTEGER CHECK(declaration_end_byte >= declaration_start_byte) CHECK((declaration_occurrence_id IS NULL) = (declaration_end_byte IS NULL)),
  target_start_byte INTEGER CHECK(target_start_byte >= 0) CHECK((target_occurrence_id IS NULL) = (target_start_byte IS NULL)),
  target_end_byte INTEGER CHECK(target_end_byte >= target_start_byte) CHECK((target_occurrence_id IS NULL) = (target_end_byte IS NULL)),
  alias_start_byte INTEGER CHECK(alias_start_byte >= 0) CHECK((alias_occurrence_id IS NULL) = (alias_start_byte IS NULL)),
  alias_end_byte INTEGER CHECK(alias_end_byte >= alias_start_byte) CHECK((alias_occurrence_id IS NULL) = (alias_end_byte IS NULL)),
  blob_id                    INTEGER NOT NULL,
  lang                       TEXT NOT NULL,
  ordinal                    INTEGER NOT NULL,
  source_import_id           INTEGER CHECK(source_import_id >= 0),
  source_context_occurrence_id INTEGER
    CHECK(source_context_occurrence_id IS NULL OR source_context_occurrence_id >= 0),
  module_path                TEXT NOT NULL,
  bound_name                 TEXT,
  imported_name              TEXT,
  is_glob                    INTEGER DEFAULT 0 CHECK(is_glob IS NULL OR is_glob IN (0, 1)),
  visibility                 TEXT,
  owner_module               TEXT,
  owner_start                INTEGER,
  owner_end                  INTEGER,
  local_start                INTEGER,
  local_end                  INTEGER,
  cfg_condition              TEXT DEFAULT 'always',
  is_extern_crate            INTEGER DEFAULT 0 CHECK(is_extern_crate IS NULL OR is_extern_crate IN (0, 1)),
  is_macro_use               INTEGER DEFAULT 0 CHECK(is_macro_use IS NULL OR is_macro_use IN (0, 1)),
  leading_absolute           INTEGER DEFAULT 0 CHECK(leading_absolute IS NULL OR leading_absolute IN (0, 1)),
  declaration_occurrence_id  INTEGER CHECK(declaration_occurrence_id IS NULL OR declaration_occurrence_id >= 0),
  target_occurrence_id       INTEGER CHECK(target_occurrence_id IS NULL OR target_occurrence_id >= 0),
  alias_occurrence_id        INTEGER CHECK(alias_occurrence_id IS NULL OR alias_occurrence_id >= 0),
  CHECK(source_context_occurrence_id IS NULL OR source_import_id IS NOT NULL),
  CHECK(source_context_occurrence_id IS NULL OR (
    imported_name IS NULL AND is_glob IS NULL AND leading_absolute IS NULL
    AND is_extern_crate IS NULL AND is_macro_use IS NULL AND declaration_occurrence_id IS NULL
    AND target_occurrence_id IS NULL AND alias_occurrence_id IS NULL
    AND owner_module IS NULL AND owner_start IS NULL AND owner_end IS NULL
    AND local_start IS NULL AND local_end IS NULL
    AND visibility IS NULL AND cfg_condition IS NULL
  )),
  CHECK(source_context_occurrence_id IS NOT NULL OR (
    owner_module IS NOT NULL AND owner_start IS NOT NULL AND owner_end IS NOT NULL
    AND visibility IS NOT NULL AND cfg_condition IS NOT NULL
  )),
  CHECK(source_import_id IS NULL OR source_context_occurrence_id IS NOT NULL OR (
    imported_name IS NULL AND is_glob IS NULL AND leading_absolute IS NULL
    AND is_extern_crate IS NULL AND is_macro_use IS NULL AND declaration_occurrence_id IS NULL
    AND target_occurrence_id IS NULL AND alias_occurrence_id IS NULL
  )),
  CHECK(source_import_id IS NOT NULL OR (
    is_glob IS NOT NULL AND leading_absolute IS NOT NULL AND is_extern_crate IS NOT NULL AND is_macro_use IS NOT NULL
  )),
  CHECK(source_import_id IS NOT NULL OR (
    declaration_occurrence_id IS NOT NULL
    OR (target_occurrence_id IS NULL AND alias_occurrence_id IS NULL)
  )),
  CHECK(source_import_id IS NOT NULL OR declaration_occurrence_id IS NULL
    OR (is_glob = 1 AND target_occurrence_id IS NULL AND alias_occurrence_id IS NULL)
    OR (is_glob = 0 AND target_occurrence_id IS NOT NULL)),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, source_import_id) REFERENCES source_imports(blob_id, import_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, source_context_occurrence_id)
    REFERENCES source_rust_import_contexts(blob_id, declaration_occurrence_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE "rust_include_edges"(
  blob_id       INTEGER NOT NULL,
  lang          TEXT    NOT NULL,
  ordinal       INTEGER NOT NULL,
  relative_path TEXT    NOT NULL,
  file_name     TEXT    NOT NULL,
  include_start INTEGER NOT NULL,
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "rust_include_host_bindings"(
  blob_id          INTEGER NOT NULL,
  lang             TEXT    NOT NULL,
  edge_ordinal     INTEGER NOT NULL,
  ordinal          INTEGER NOT NULL,
  local_name       TEXT    NOT NULL,
  module_specifier TEXT    NOT NULL,
  imported_name    TEXT,
  scope_start      INTEGER NOT NULL,
  kind             TEXT    NOT NULL,
  PRIMARY KEY(blob_id, edge_ordinal, ordinal),
  FOREIGN KEY(blob_id, lang)
    REFERENCES "blobs"(id, lang) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "scala_exports"(
  blob_id    INTEGER NOT NULL,
  lang       TEXT    NOT NULL,
  owner_key  INTEGER NOT NULL,
  ordinal    INTEGER NOT NULL,
  info       BLOB    NOT NULL,
  PRIMARY KEY(blob_id, owner_key, ordinal),
  FOREIGN KEY(blob_id, owner_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "scala_traits"(
  blob_id  INTEGER NOT NULL,
  lang     TEXT    NOT NULL,
  unit_key INTEGER NOT NULL,
  PRIMARY KEY(blob_id, unit_key),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE semantic_pack_active_members(
  ordinal INTEGER PRIMARY KEY CHECK(ordinal >= 0),
  manifest_digest TEXT NOT NULL UNIQUE
    CHECK(length(manifest_digest) = 64 AND manifest_digest NOT GLOB '*[^0-9a-f]*'),
  source_kind TEXT NOT NULL CHECK(source_kind IN (
    'installed',
    'generated',
    'pre_shipped',
    'workspace_produced',
    'embedded',
    'ephemeral_workspace'
  )),
  source_id TEXT NOT NULL CHECK(length(source_id) > 0),
  workspace_produced INTEGER NOT NULL CHECK(workspace_produced IN (0, 1))
) STRICT;

CREATE TABLE semantic_pack_active_state(
  singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
  active_set_digest TEXT NOT NULL
    CHECK(length(active_set_digest) = 64 AND active_set_digest NOT GLOB '*[^0-9a-f]*'),
  updated_at INTEGER NOT NULL
) STRICT;

CREATE TABLE source_cpp_alias_components(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_base_components(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  base_ordinal INTEGER NOT NULL CHECK(base_ordinal >= 0),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, base_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, base_ordinal)
    REFERENCES source_cpp_bases(blob_id, declaration_id, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_bases(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  is_virtual INTEGER NOT NULL CHECK(is_virtual IN (0, 1)),
  absolute INTEGER NOT NULL CHECK(absolute IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_callable_shapes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  parameter_id INTEGER,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, parameter_id)
    REFERENCES source_cpp_comparable_parameters(blob_id, parameter_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind = 0) = (parameter_id IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_comparable_node_arguments(
  blob_id INTEGER NOT NULL,
  parameter_id INTEGER NOT NULL,
  node_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_node_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, parameter_id, node_id, ordinal),
  FOREIGN KEY(blob_id, parameter_id, node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, parameter_id, child_node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_comparable_node_names(
  blob_id INTEGER NOT NULL,
  parameter_id INTEGER NOT NULL,
  node_id INTEGER NOT NULL,
  axis INTEGER NOT NULL CHECK(axis IN (0, 1)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL,
  PRIMARY KEY(blob_id, parameter_id, node_id, axis, ordinal),
  FOREIGN KEY(blob_id, parameter_id, node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_comparable_nodes(
  blob_id INTEGER NOT NULL,
  parameter_id INTEGER NOT NULL,
  node_id INTEGER NOT NULL CHECK(node_id >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 4),
  inner_node_id INTEGER,
  base_node_id INTEGER,
  primitive INTEGER CHECK(primitive IS NULL OR primitive IN (0, 1)),
  konst INTEGER CHECK(konst IS NULL OR konst IN (0, 1)),
  volatil INTEGER CHECK(volatil IS NULL OR volatil IN (0, 1)),
  absolute INTEGER CHECK(absolute IS NULL OR absolute IN (0, 1)),
  PRIMARY KEY(blob_id, parameter_id, node_id),
  FOREIGN KEY(blob_id, parameter_id, inner_node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, parameter_id, base_node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind IN (1, 2, 3)) = (inner_node_id IS NOT NULL)),
  CHECK((kind = 4) = (base_node_id IS NOT NULL)),
  CHECK(kind = 0 OR primitive IS NULL),
  CHECK(kind IN (0, 1) OR (konst IS NULL AND volatil IS NULL)),
  CHECK(kind = 0 OR absolute IS NULL),
  FOREIGN KEY(blob_id) REFERENCES blobs(id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_comparable_parameters(
  blob_id INTEGER NOT NULL,
  parameter_id INTEGER NOT NULL CHECK(parameter_id >= 0),
  root_node_id INTEGER NOT NULL CHECK(root_node_id >= 0),
  PRIMARY KEY(blob_id, parameter_id),
  FOREIGN KEY(blob_id, parameter_id, root_node_id)
    REFERENCES source_cpp_comparable_nodes(blob_id, parameter_id, node_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id) REFERENCES blobs(id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_declaration_contexts(
  callable_guard_completion_byte INTEGER CHECK(callable_guard_completion_byte IS NULL OR callable_guard_completion_byte >= 0),
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  callable_activation INTEGER CHECK(callable_activation IS NULL OR callable_activation >= 0),
  exhaustive_family INTEGER,
  displaced_closing_brace INTEGER,
  flattened_namespace_present INTEGER NOT NULL CHECK(flattened_namespace_present IN (0, 1)),
  file_alias_name TEXT,
  file_alias_target TEXT,
  file_alias_namespace TEXT,
  CHECK((file_alias_name IS NULL) = (file_alias_target IS NULL)),
  CHECK(file_alias_name IS NOT NULL OR file_alias_namespace IS NULL),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_declaration_paths(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  path_kind INTEGER NOT NULL CHECK(path_kind IN (0, 1, 2)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, path_kind, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_declarations(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  occurrence_role INTEGER NOT NULL CHECK(occurrence_role BETWEEN 0 AND 3),
  conditional_family_occurrence_id INTEGER,
  class_strength INTEGER NOT NULL CHECK(class_strength BETWEEN 0 AND 2),
  enum_kind INTEGER NOT NULL CHECK(enum_kind BETWEEN 0 AND 2),
  field_type_text TEXT,
  field_indirection INTEGER,
  alias_kind INTEGER CHECK(alias_kind IS NULL OR alias_kind IN (0, 1)),
  alias_global INTEGER CHECK(alias_global IS NULL OR alias_global IN (0, 1)),
  alias_target_text TEXT,
  adds_indirection INTEGER NOT NULL CHECK(adds_indirection IN (0, 1)),
  names_function_type INTEGER NOT NULL CHECK(names_function_type IN (0, 1)),
  trailing_qualifiers TEXT NOT NULL,
  callable_shapes_present INTEGER NOT NULL CHECK(callable_shapes_present IN (0, 1)),
  callable_identity_suffix TEXT,
  callable_is_constructor INTEGER NOT NULL CHECK(callable_is_constructor IN (0, 1)),
  callable_is_deduction_guide INTEGER NOT NULL CHECK(callable_is_deduction_guide IN (0, 1)),
  callable_is_template INTEGER NOT NULL CHECK(callable_is_template IN (0, 1)),
  field_arguments_present INTEGER NOT NULL CHECK(field_arguments_present IN (0, 1)),
  alias_arguments_present INTEGER NOT NULL CHECK(alias_arguments_present IN (0, 1)),
  field_binds_indirectly INTEGER
    CHECK ((field_type_text IS NULL AND field_binds_indirectly IS NULL)
        OR (field_type_text IS NOT NULL AND field_binds_indirectly IS NOT NULL
            AND field_binds_indirectly IN (0, 1))),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  CHECK((field_type_text IS NULL) = (field_indirection IS NULL)),
  CHECK(alias_kind IS NOT NULL OR alias_global IS NULL),
  CHECK(alias_kind IS NULL OR alias_target_text IS NOT NULL),
  CHECK(alias_kind <> 0 OR alias_global IS NULL),
  CHECK(field_arguments_present = 0 OR field_type_text IS NOT NULL),
  CHECK(alias_arguments_present = 0 OR alias_kind IS 1)
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_flattened_namespaces(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_cpp_declaration_contexts(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_guard_edges(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  guard_kind INTEGER NOT NULL,
  parent_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < parent_id),
  PRIMARY KEY(blob_id, declaration_id, guard_kind, parent_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id, guard_kind, parent_id) REFERENCES source_cpp_guard_nodes(blob_id, declaration_id, guard_kind, node_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id, guard_kind, child_id) REFERENCES source_cpp_guard_nodes(blob_id, declaration_id, guard_kind, node_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_guard_nodes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  guard_kind INTEGER NOT NULL,
  node_id INTEGER NOT NULL CHECK(node_id >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 11),
  text TEXT,
  constant INTEGER CHECK(constant IS NULL OR constant IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, guard_kind, node_id),
  FOREIGN KEY(blob_id, declaration_id, guard_kind) REFERENCES source_cpp_guard_sets(blob_id, declaration_id, guard_kind) ON DELETE CASCADE,
  CHECK((kind IN (0,1,3,4,6,7,8,9)) = (text IS NOT NULL)),
  CHECK((kind = 5) = (constant IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_guard_roots(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  guard_kind INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  node_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, guard_kind, ordinal),
  FOREIGN KEY(blob_id, declaration_id, guard_kind) REFERENCES source_cpp_guard_sets(blob_id, declaration_id, guard_kind) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id, guard_kind, node_id) REFERENCES source_cpp_guard_nodes(blob_id, declaration_id, guard_kind, node_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_guard_sets(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  guard_kind INTEGER NOT NULL CHECK(guard_kind IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, guard_kind),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_cpp_declaration_contexts(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_includes(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  declaration_occurrence_id INTEGER NOT NULL,
  target_occurrence_id INTEGER NOT NULL,
  path TEXT NOT NULL,
  quoted INTEGER NOT NULL CHECK(quoted IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id) REFERENCES blobs(id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_cpp_member_using_scopes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  using_ordinal INTEGER NOT NULL CHECK(using_ordinal >= 0),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, using_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, using_ordinal)
    REFERENCES source_cpp_member_usings(blob_id, declaration_id, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_member_usings(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  member TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_template_expressions(
  blob_id INTEGER NOT NULL,
  expression_id INTEGER NOT NULL CHECK(expression_id >= 0),
  declaration_id INTEGER NOT NULL,
  owner_kind INTEGER NOT NULL CHECK(owner_kind IN (0, 1)),
  argument_ordinal INTEGER NOT NULL CHECK(argument_ordinal >= 0),
  text TEXT NOT NULL,
  root_term_id INTEGER NOT NULL CHECK(root_term_id >= 0),
  PRIMARY KEY(blob_id, expression_id),
  UNIQUE(blob_id, declaration_id, owner_kind, argument_ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_cpp_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, expression_id, root_term_id)
    REFERENCES source_cpp_template_terms(blob_id, expression_id, term_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_template_terms(
  blob_id INTEGER NOT NULL,
  term_id INTEGER NOT NULL CHECK(term_id >= 0),
  expression_id INTEGER NOT NULL,
  parent_term_id INTEGER CHECK(parent_term_id IS NULL OR (parent_term_id >= 0 AND parent_term_id < term_id)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  text TEXT,
  atom_kind TEXT,
  PRIMARY KEY(blob_id, term_id),
  UNIQUE(blob_id, expression_id, term_id),
  FOREIGN KEY(blob_id, expression_id)
    REFERENCES source_cpp_template_expressions(blob_id, expression_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, parent_term_id)
    REFERENCES source_cpp_template_terms(blob_id, term_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind = 0) = (atom_kind IS NULL)),
  CHECK(kind = 2 OR text IS NOT NULL),
  CHECK((kind = 2) = (text IS NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_cpp_using_namespaces(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL,
  namespace TEXT NOT NULL,
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id) REFERENCES blobs(id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_declaration_metadata_bridges(
  blob_id          INTEGER NOT NULL,
  declaration_id   INTEGER NOT NULL CHECK(declaration_id >= 0),
  unit_key         INTEGER NOT NULL CHECK(unit_key >= 0),
  metadata_ordinal INTEGER NOT NULL CHECK(metadata_ordinal >= 0),
  PRIMARY KEY(blob_id, declaration_id, unit_key, metadata_ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, unit_key)
    REFERENCES source_declaration_units(blob_id, declaration_id, unit_key)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, unit_key, metadata_ordinal)
    REFERENCES unit_signature_metadata(blob_id, unit_key, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_declaration_units(
  blob_id        INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  unit_key       INTEGER NOT NULL CHECK(unit_key >= 0),
  PRIMARY KEY(blob_id, declaration_id, unit_key),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES code_units(blob_id, unit_key)
) WITHOUT ROWID, STRICT;

CREATE TABLE source_declaration_visibilities(
  blob_id        INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  visibility     TEXT NOT NULL CHECK(visibility IN (
    'public', 'protected', 'internal', 'package_private', 'private',
    'crate_or_module', 'unknown'
  )),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_declaration_visibility_manifests(
  blob_id                  INTEGER NOT NULL,
  facts_version            INTEGER NOT NULL CHECK(facts_version = 1),
  visibility_count         INTEGER NOT NULL CHECK(visibility_count >= 0),
  native_bridge_count      INTEGER NOT NULL CHECK(native_bridge_count >= 0),
  metadata_bridge_count    INTEGER NOT NULL CHECK(metadata_bridge_count >= 0),
  PRIMARY KEY(blob_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_declarations(
  blob_id             INTEGER NOT NULL,
  declaration_id      INTEGER NOT NULL CHECK(declaration_id >= 0),
  occurrence_id       INTEGER NOT NULL CHECK(occurrence_id >= 0),
  name_occurrence_id  INTEGER CHECK(name_occurrence_id IS NULL OR name_occurrence_id >= 0), lexical_kind TEXT
  CHECK(lexical_kind IS NULL OR lexical_kind IN (
    'parameter', 'receiver_parameter', 'import_alias', 'statement_label',
    'local_variable', 'catch_parameter', 'enhanced_for_variable',
    'lambda_parameter', 'pattern_variable', 'resource_variable',
    'block_local_item', 'field'
  )), lexical_identifier TEXT
  CHECK(
    (lexical_identifier IS NULL AND lexical_kind IS NULL)
    OR (lexical_identifier IS NOT NULL AND lexical_kind IS NOT NULL
        AND name_occurrence_id IS NOT NULL
        AND length(CAST(lexical_identifier AS BLOB)) > 0)
  ),
  start_byte      INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte        INTEGER NOT NULL CHECK(end_byte >= start_byte),
  start_line      INTEGER NOT NULL CHECK(start_line >= 1),
  end_line        INTEGER NOT NULL CHECK(end_line >= start_line),
  name_start_byte INTEGER CHECK(name_start_byte >= 0),
  name_end_byte   INTEGER CHECK(name_end_byte >= name_start_byte),
  name_start_line INTEGER CHECK(name_start_line >= 1),
  name_end_line   INTEGER CHECK(name_end_line >= name_start_line),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, declaration_id),
  CHECK((name_occurrence_id IS NULL) = (name_start_byte IS NULL)),
  CHECK((name_start_byte IS NULL) = (name_end_byte IS NULL)),
  CHECK((name_occurrence_id IS NULL) = (name_start_line IS NULL)),
  CHECK((name_occurrence_id IS NULL) = (name_end_line IS NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_fact_manifests(
  blob_id             INTEGER NOT NULL,
  facts_version       INTEGER NOT NULL CHECK(facts_version > 0),
  source_bytes        INTEGER NOT NULL CHECK(source_bytes >= 0),
  occurrence_count    INTEGER NOT NULL CHECK(occurrence_count >= 0),
  declaration_count   INTEGER NOT NULL CHECK(declaration_count >= 0),
  declaration_unit_count INTEGER NOT NULL CHECK(declaration_unit_count >= 0),
  node_count          INTEGER NOT NULL CHECK(node_count >= 0),
  role_count          INTEGER NOT NULL CHECK(role_count >= 0),
  occurrence_role_count INTEGER NOT NULL CHECK(occurrence_role_count >= 0),
  logical_rows        INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes       INTEGER NOT NULL CHECK(payload_bytes >= 0),
  publication_state   TEXT NOT NULL CHECK(publication_state IN ('building', 'complete')), import_count INTEGER NOT NULL DEFAULT 0
    CHECK(import_count >= 0), import_segment_count INTEGER NOT NULL DEFAULT 0
    CHECK(import_segment_count >= 0), import_scope_count INTEGER NOT NULL DEFAULT 0
    CHECK(import_scope_count >= 0), import_prefix_count INTEGER NOT NULL DEFAULT 0
    CHECK(import_prefix_count >= 0), rust_import_context_count INTEGER NOT NULL DEFAULT 0
    CHECK(rust_import_context_count >= 0), rust_declaration_property_count INTEGER NOT NULL DEFAULT 0
    CHECK(rust_declaration_property_count >= 0), rust_constructor_field_count INTEGER NOT NULL DEFAULT 0
    CHECK(rust_constructor_field_count >= 0), metadata_bridge_count INTEGER
  CHECK(metadata_bridge_count IS NULL OR metadata_bridge_count >= 0), native_bridge_count INTEGER
  CHECK(native_bridge_count IS NULL OR native_bridge_count >= 0),
  PRIMARY KEY(blob_id),
  FOREIGN KEY(blob_id)
    REFERENCES blob_meta(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_go_aliases(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  name TEXT NOT NULL CHECK(length(name) > 0),
  target_type_id INTEGER,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, target_type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_callable_parameters(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  result INTEGER NOT NULL CHECK(result IN (0, 1)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  group_occurrence_id INTEGER NOT NULL,
  name_occurrence_id INTEGER,
  type_id INTEGER,
  variadic INTEGER NOT NULL CHECK(variadic IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, result, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_go_callables(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_callables(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  name TEXT NOT NULL CHECK(length(name) > 0),
  owner_type_id INTEGER,
  receiver_type_id INTEGER,
  is_method INTEGER NOT NULL CHECK(is_method IN (0, 1)),
  parameters_present INTEGER NOT NULL CHECK(parameters_present IN (0, 1)),
  result_occurrence_id INTEGER,
  body_occurrence_id INTEGER,
  file_scope INTEGER NOT NULL CHECK(file_scope IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, owner_type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, receiver_type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_embeddings(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  owner_type_id INTEGER NOT NULL,
  occurrence_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, owner_type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_fields(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  owner_type_id INTEGER NOT NULL,
  type_id INTEGER,
  name TEXT NOT NULL CHECK(length(name) > 0),
  embedded INTEGER NOT NULL CHECK(embedded IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, owner_type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_go_type_children(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < type_id),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_type_declarations(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  name TEXT NOT NULL CHECK(length(name) > 0),
  type_id INTEGER NOT NULL,
  file_scope INTEGER NOT NULL CHECK(file_scope IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_type_names(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal IN (0, 1)),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id) REFERENCES source_go_types(blob_id, type_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_go_types(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  type_id INTEGER NOT NULL CHECK(type_id >= 0),
  occurrence_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 14),
  child1 INTEGER CHECK(child1 IS NULL OR (child1 >= 0 AND child1 < type_id)),
  child2 INTEGER CHECK(child2 IS NULL OR (child2 >= 0 AND child2 < type_id)),
  detail_occurrence_id INTEGER,
  text TEXT,
  direction INTEGER CHECK(direction IS NULL OR direction IN (0, 1, 2)),
  has_named_children INTEGER CHECK(has_named_children IS NULL OR has_named_children IN (0, 1)),
  PRIMARY KEY(blob_id, type_id),
  UNIQUE(blob_id, occurrence_id),
  FOREIGN KEY(blob_id, child1) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, child2) REFERENCES source_go_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind IN (1, 2, 3, 4, 5, 6, 7, 11)) = (child1 IS NOT NULL)),
  CHECK((kind = 5) = (child2 IS NOT NULL)),
  CHECK((kind IN (3, 7)) = (detail_occurrence_id IS NOT NULL)),
  -- Array lengths are mandatory exact syntax; generic argument lists and
  -- opaque/inline presentations are demand-driven and may be unavailable.
  CHECK(kind IN (3, 4, 7, 12, 13, 14) OR text IS NULL),
  CHECK(text IS NULL OR length(CAST(text AS BLOB)) > 0),
  CHECK(kind <> 3 OR text IS NOT NULL),
  CHECK((kind = 6) = (direction IS NOT NULL)),
  CHECK((kind = 13) = (has_named_children IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_import_prefixes(
  blob_id   INTEGER NOT NULL,
  import_id INTEGER NOT NULL CHECK(import_id >= 0),
  ordinal   INTEGER NOT NULL CHECK(ordinal >= 0),
  prefix    TEXT NOT NULL,
  PRIMARY KEY(blob_id, import_id, ordinal),
  FOREIGN KEY(blob_id, import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_import_scopes(
  blob_id       INTEGER NOT NULL,
  import_id     INTEGER NOT NULL CHECK(import_id >= 0),
  ordinal       INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL CHECK(occurrence_id >= 0),
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte   INTEGER NOT NULL CHECK(end_byte >= start_byte),
  PRIMARY KEY(blob_id, import_id, ordinal),
  FOREIGN KEY(blob_id, import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_import_segments(
  blob_id   INTEGER NOT NULL,
  import_id INTEGER NOT NULL CHECK(import_id >= 0),
  ordinal   INTEGER NOT NULL CHECK(ordinal >= 0),
  segment   TEXT NOT NULL,
  PRIMARY KEY(blob_id, import_id, ordinal),
  FOREIGN KEY(blob_id, import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_imports(
  blob_id                   INTEGER NOT NULL,
  import_id                 INTEGER NOT NULL CHECK(import_id >= 0),
  statement                 TEXT NOT NULL,
  is_wildcard               INTEGER NOT NULL CHECK(is_wildcard IN (0, 1)),
  is_global                 INTEGER NOT NULL CHECK(is_global IN (0, 1)),
  is_macro_use              INTEGER NOT NULL DEFAULT 0 CHECK(is_macro_use IN (0, 1)),
  identifier                TEXT,
  alias                     TEXT,
  path_kind                 TEXT CHECK(path_kind IN (
    'namespace', 'import_from', 'static_member', 'extern_crate'
  )),
  declaration_occurrence_id INTEGER NOT NULL
    CHECK(declaration_occurrence_id >= 0),
  target_occurrence_id      INTEGER
    CHECK(target_occurrence_id IS NULL OR target_occurrence_id >= 0),
  alias_occurrence_id       INTEGER
    CHECK(alias_occurrence_id IS NULL OR alias_occurrence_id >= 0), has_structured_path INTEGER NOT NULL DEFAULT 1
    CHECK(has_structured_path IN (0, 1)),
  declaration_start_byte INTEGER NOT NULL CHECK(declaration_start_byte >= 0),
  declaration_end_byte   INTEGER NOT NULL CHECK(declaration_end_byte >= declaration_start_byte),
  target_start_byte      INTEGER CHECK(target_start_byte >= 0),
  target_end_byte        INTEGER CHECK(target_end_byte >= target_start_byte),
  alias_start_byte       INTEGER CHECK(alias_start_byte >= 0),
  alias_end_byte         INTEGER CHECK(alias_end_byte >= alias_start_byte),
  PRIMARY KEY(blob_id, import_id),
  CHECK((target_occurrence_id IS NULL) = (target_start_byte IS NULL)),
  CHECK((alias_occurrence_id IS NULL) = (alias_start_byte IS NULL)),
  CHECK((target_occurrence_id IS NULL) = (target_end_byte IS NULL)),
  CHECK((alias_occurrence_id IS NULL) = (alias_end_byte IS NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_java_anonymous_return_entries(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  return_occurrence_id INTEGER NOT NULL,
  object_occurrence_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_java_anonymous_returns(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_java_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_anonymous_returns(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  status INTEGER NOT NULL CHECK(status IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_callable_returns(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  type_id INTEGER,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_java_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_declaration_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_java_declaration_owners(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  owner_declaration_id INTEGER NOT NULL CHECK(owner_declaration_id < declaration_id),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, owner_declaration_id) REFERENCES source_declarations(blob_id, declaration_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_local_types(
  lexical_scope_start_byte INTEGER NOT NULL CHECK(lexical_scope_start_byte >= 0),
  lexical_scope_end_byte INTEGER NOT NULL CHECK(lexical_scope_end_byte >= lexical_scope_start_byte),
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  lexical_scope_occurrence_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_type_arguments(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < type_id),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id) REFERENCES source_java_types(blob_id, type_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id) REFERENCES source_java_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_type_bounds(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  type_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_java_type_parameters(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id) REFERENCES source_java_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_type_names(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  axis INTEGER NOT NULL CHECK(axis IN (0, 1)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, type_id, axis, ordinal),
  FOREIGN KEY(blob_id, type_id) REFERENCES source_java_types(blob_id, type_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_type_parameters(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  owner_declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, declaration_id),
  UNIQUE(blob_id, owner_declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, owner_declaration_id) REFERENCES source_declarations(blob_id, declaration_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_java_types(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  type_id INTEGER NOT NULL CHECK(type_id >= 0),
  occurrence_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 5),
  child_id INTEGER CHECK(child_id IS NULL OR (child_id >= 0 AND child_id < type_id)),
  parameter_declaration_id INTEGER,
  absolute INTEGER CHECK(absolute IS NULL OR absolute IN (0, 1)),
  array_dimensions INTEGER CHECK(array_dimensions IS NULL OR array_dimensions > 0),
  PRIMARY KEY(blob_id, type_id),
  UNIQUE(blob_id, occurrence_id),
  FOREIGN KEY(blob_id, child_id) REFERENCES source_java_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, parameter_declaration_id) REFERENCES source_java_type_parameters(blob_id, declaration_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind IN (1, 2, 3)) = (child_id IS NOT NULL)),
  CHECK(kind = 0 OR parameter_declaration_id IS NULL),
  CHECK((kind = 0) = (absolute IS NOT NULL)),
  CHECK((kind = 2) = (array_dimensions IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_bindings(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  import_id INTEGER NOT NULL CHECK(import_id >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 4),
  is_static INTEGER NOT NULL CHECK(is_static IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  UNIQUE(blob_id, import_id),
  FOREIGN KEY(blob_id, import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_component_members(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_js_ts_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_declaration_bindings(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  declaration_id INTEGER NOT NULL,
  binder_id INTEGER NOT NULL,
  name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) > 0),
  is_program INTEGER NOT NULL CHECK(is_program IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  UNIQUE(blob_id, declaration_id, name),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_js_ts_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_declaration_parameters(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  type_id INTEGER,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_js_ts_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_declarations(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  declaration_id INTEGER NOT NULL,
  is_interface INTEGER NOT NULL CHECK(is_interface IN (0, 1)),
  is_global INTEGER NOT NULL CHECK(is_global IN (0, 1)),
  is_callable INTEGER NOT NULL CHECK(is_callable IN (0, 1)),
  alias_type_id INTEGER,
  member_type_id INTEGER,
  declared_type_id INTEGER,
  return_type_id INTEGER,
  component_kind INTEGER CHECK(component_kind IS NULL OR component_kind BETWEEN 0 AND 3),
  component_type_id INTEGER,
  component_import_id INTEGER,
  component_name TEXT,
  PRIMARY KEY(blob_id, ordinal),
  UNIQUE(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, alias_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, member_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declared_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, return_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, component_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, component_import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE,
  CHECK((component_kind IS NULL AND component_type_id IS NULL AND component_import_id IS NULL AND component_name IS NULL)
     OR (component_kind = 0 AND component_type_id IS NOT NULL AND component_import_id IS NULL AND component_name IS NULL)
     OR (component_kind = 1 AND component_type_id IS NULL AND component_import_id IS NULL AND length(CAST(component_name AS BLOB)) > 0)
     OR (component_kind = 2 AND component_type_id IS NULL AND component_import_id IS NOT NULL AND component_name IS NULL)
     OR (component_kind = 3 AND component_type_id IS NOT NULL AND component_import_id IS NULL AND component_name IS NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_exports(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL,
  name TEXT,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 4),
  local_name TEXT,
  import_id INTEGER CHECK(import_id IS NULL OR import_id >= 0),
  is_esm INTEGER NOT NULL CHECK(is_esm IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, import_id)
    REFERENCES source_imports(blob_id, import_id) ON DELETE CASCADE,
  CHECK(name IS NULL OR length(CAST(name AS BLOB)) > 0),
  CHECK(local_name IS NULL OR length(CAST(local_name AS BLOB)) > 0),
  CHECK((kind = 0 AND local_name IS NOT NULL AND import_id IS NULL)
     OR (kind = 1 AND import_id IS NULL)
     OR (kind IN (2, 3, 4) AND local_name IS NULL AND import_id IS NOT NULL)),
  CHECK((kind = 4 AND name IS NULL) OR (kind <> 4 AND name IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  binding_count INTEGER NOT NULL CHECK(binding_count >= 0),
  export_count INTEGER NOT NULL CHECK(export_count >= 0),
  declaration_count INTEGER NOT NULL CHECK(declaration_count >= 0),
  type_count INTEGER NOT NULL CHECK(type_count >= 0),
  type_name_count INTEGER NOT NULL CHECK(type_name_count >= 0),
  type_child_count INTEGER NOT NULL CHECK(type_child_count >= 0),
  type_member_count INTEGER NOT NULL CHECK(type_member_count >= 0),
  type_parameter_count INTEGER NOT NULL CHECK(type_parameter_count >= 0),
  declaration_parameter_count INTEGER NOT NULL CHECK(declaration_parameter_count >= 0),
  component_member_count INTEGER NOT NULL CHECK(component_member_count >= 0),
  declaration_binding_count INTEGER NOT NULL CHECK(declaration_binding_count >= 0),
  property_receiver_count INTEGER NOT NULL CHECK(property_receiver_count >= 0),
  property_receiver_member_count INTEGER NOT NULL CHECK(property_receiver_member_count >= 0),
  file_is_external_module INTEGER NOT NULL CHECK(file_is_external_module IN (0, 1)),
  file_is_esm INTEGER NOT NULL CHECK(file_is_esm IN (0, 1)),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_js_ts_property_receiver_members(
  blob_id INTEGER NOT NULL,
  receiver_ordinal INTEGER NOT NULL CHECK(receiver_ordinal >= 0),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) > 0),
  PRIMARY KEY(blob_id, receiver_ordinal, ordinal),
  FOREIGN KEY(blob_id, receiver_ordinal)
    REFERENCES source_js_ts_property_receivers(blob_id, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_property_receivers(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  declaration_id INTEGER NOT NULL,
  property_id INTEGER NOT NULL,
  receiver_root TEXT NOT NULL CHECK(length(CAST(receiver_root AS BLOB)) > 0),
  binding INTEGER NOT NULL CHECK(binding BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_js_ts_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_type_children(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < type_id),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_type_members(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) > 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < type_id),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_type_names(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) > 0),
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_type_parameters(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER,
  PRIMARY KEY(blob_id, type_id, ordinal),
  FOREIGN KEY(blob_id, type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_js_ts_types(
  blob_id INTEGER NOT NULL,
  type_id INTEGER NOT NULL CHECK(type_id >= 0),
  occurrence_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 11),
  child_id INTEGER CHECK(child_id IS NULL OR (child_id >= 0 AND child_id < type_id)),
  result_type_id INTEGER CHECK(result_type_id IS NULL OR (result_type_id >= 0 AND result_type_id < type_id)),
  PRIMARY KEY(blob_id, type_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  UNIQUE(blob_id, occurrence_id),
  FOREIGN KEY(blob_id, child_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, result_type_id)
    REFERENCES source_js_ts_types(blob_id, type_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK((kind IN (1, 2, 5, 8) = (child_id IS NOT NULL))),
  CHECK(kind = 6 OR result_type_id IS NULL)
) STRICT, WITHOUT ROWID;

CREATE TABLE source_native_declaration_bridges(
  blob_id       INTEGER NOT NULL,
  source_site   INTEGER NOT NULL CHECK(source_site BETWEEN 0 AND 4294967295),
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  PRIMARY KEY(blob_id, source_site),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_occurrence_arenas(
  blob_id INTEGER NOT NULL,
  spans   BLOB    NOT NULL CHECK(json_valid(spans, 8) AND json_type(spans) = 'array'),
  PRIMARY KEY(blob_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_php_aliases(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  alias_id INTEGER NOT NULL CHECK(alias_id >= 0),
  source_import_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, alias_id),
  UNIQUE(blob_id, source_import_id),
  FOREIGN KEY(blob_id, source_import_id)
    REFERENCES source_imports(blob_id, import_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_context_aliases(
  blob_id INTEGER NOT NULL,
  context_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  alias_id INTEGER NOT NULL CHECK(alias_id >= 0),
  PRIMARY KEY(blob_id, context_id, ordinal),
  FOREIGN KEY(blob_id, context_id) REFERENCES source_php_contexts(blob_id, context_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, alias_id) REFERENCES source_php_aliases(blob_id, alias_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_contexts(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  context_id INTEGER NOT NULL CHECK(context_id >= 0),
  namespace TEXT NOT NULL,
  PRIMARY KEY(blob_id, context_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_declarations(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 9),
  context_id INTEGER NOT NULL,
  declared_type_occurrence_id INTEGER,
  declared_type_kind INTEGER NOT NULL CHECK(declared_type_kind BETWEEN 0 AND 6),
  class_parent_ordinal INTEGER,
  has_trait_use INTEGER NOT NULL CHECK(has_trait_use IN (0, 1)),
  doc_nominal_type TEXT,
  doc_element_type TEXT,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, context_id) REFERENCES source_php_contexts(blob_id, context_id) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, class_parent_ordinal)
    REFERENCES source_php_supertypes(blob_id, declaration_id, ordinal) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_php_nominal_arms(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  arm TEXT NOT NULL CHECK(length(arm) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_php_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_supertypes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  supertype TEXT NOT NULL CHECK(length(supertype) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_php_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_write_nominal_arms(
  blob_id INTEGER NOT NULL,
  write_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  arm TEXT NOT NULL CHECK(length(arm) > 0),
  PRIMARY KEY(blob_id, write_ordinal, ordinal),
  FOREIGN KEY(blob_id, write_ordinal) REFERENCES source_php_writes(blob_id, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_php_writes(
  blob_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL,
  class_declaration_id INTEGER NOT NULL,
  field TEXT NOT NULL CHECK(length(field) > 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  directly_in_constructor INTEGER NOT NULL CHECK(directly_in_constructor IN (0, 1)),
  value_type_kind INTEGER NOT NULL CHECK(value_type_kind BETWEEN 0 AND 6),
  doc_element_type TEXT,
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id, class_declaration_id) REFERENCES source_php_declarations(blob_id, declaration_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_python_annotation_names(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  reference_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, declaration_id, reference_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, reference_ordinal)
    REFERENCES source_python_annotation_references(blob_id, declaration_id, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_python_annotation_references(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL,
  name_kind INTEGER NOT NULL CHECK(name_kind BETWEEN 0 AND 2),
  lexical_name TEXT CHECK(lexical_name IS NULL OR length(lexical_name) > 0),
  subtree_end INTEGER NOT NULL CHECK(subtree_end > ordinal),
  lookup_depth INTEGER NOT NULL CHECK(lookup_depth BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_python_callable_returns(blob_id, declaration_id) ON DELETE CASCADE,
  CHECK((name_kind = 0) = (lexical_name IS NOT NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE source_python_callable_returns(
  return_annotation_start_byte INTEGER CHECK(return_annotation_start_byte >= 0) CHECK((return_annotation_id IS NULL) = (return_annotation_start_byte IS NULL)),
  return_annotation_end_byte INTEGER CHECK(return_annotation_end_byte >= return_annotation_start_byte) CHECK((return_annotation_id IS NULL) = (return_annotation_end_byte IS NULL)),
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  return_annotation_id INTEGER,
  runtime_type_present INTEGER NOT NULL CHECK(runtime_type_present IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  CHECK(runtime_type_present = 0 OR return_annotation_id IS NOT NULL)
) STRICT, WITHOUT ROWID;

CREATE TABLE source_python_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_python_return_names(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id) REFERENCES source_python_callable_returns(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_ruby_load_constants(
  blob_id INTEGER NOT NULL,
  import_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, import_id, ordinal),
  FOREIGN KEY(blob_id, import_id) REFERENCES source_ruby_loads(blob_id, import_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_ruby_loads(
  blob_id INTEGER NOT NULL REFERENCES blobs(id) ON DELETE CASCADE,
  import_id INTEGER NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 3),
  has_receiver INTEGER NOT NULL CHECK(has_receiver IN (0, 1)),
  has_constant INTEGER NOT NULL CHECK(has_constant IN (0, 1)),
  PRIMARY KEY(blob_id, import_id),
  FOREIGN KEY(blob_id, import_id) REFERENCES source_imports(blob_id, import_id) DEFERRABLE INITIALLY DEFERRED,
  CHECK(has_constant = 0 OR kind = 3)
) STRICT, WITHOUT ROWID;

CREATE TABLE source_ruby_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0),
  has_parse_errors INTEGER NOT NULL CHECK(has_parse_errors IN (0, 1)),
  runtime_boundary_occurrence_id INTEGER,
  runtime_boundary_kind INTEGER CHECK(runtime_boundary_kind BETWEEN 0 AND 12),
  CHECK((runtime_boundary_kind IS NULL) = (runtime_boundary_occurrence_id IS NULL))
) STRICT;

CREATE TABLE source_rust_alias_items(
  blob_id                 INTEGER NOT NULL,
  declaration_id          INTEGER NOT NULL CHECK(declaration_id >= 0),
  context_occurrence_id   INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  target_type_occurrence_id INTEGER CHECK(target_type_occurrence_id IS NULL OR target_type_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, target_type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_callable_items(
  parameters_start_byte INTEGER CHECK(parameters_start_byte >= 0) CHECK((parameters_occurrence_id IS NULL) = (parameters_start_byte IS NULL)),
  parameters_end_byte INTEGER CHECK(parameters_end_byte >= parameters_start_byte) CHECK((parameters_occurrence_id IS NULL) = (parameters_end_byte IS NULL)),
  blob_id                 INTEGER NOT NULL,
  declaration_id          INTEGER NOT NULL CHECK(declaration_id >= 0),
  context_occurrence_id   INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  parameters_occurrence_id INTEGER CHECK(parameters_occurrence_id IS NULL OR parameters_occurrence_id >= 0),
  return_type_occurrence_id INTEGER CHECK(return_type_occurrence_id IS NULL OR return_type_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, return_type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_callable_parameters(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  label_start_byte INTEGER CHECK(label_start_byte >= 0) CHECK((label_occurrence_id IS NULL) = (label_start_byte IS NULL)),
  label_end_byte INTEGER CHECK(label_end_byte >= label_start_byte) CHECK((label_occurrence_id IS NULL) = (label_end_byte IS NULL)),
  blob_id              INTEGER NOT NULL,
  declaration_id       INTEGER NOT NULL CHECK(declaration_id >= 0),
  ordinal              INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id        INTEGER NOT NULL CHECK(occurrence_id >= 0),
  syntax_kind          TEXT NOT NULL CHECK(length(syntax_kind) > 0),
  label_occurrence_id  INTEGER CHECK(label_occurrence_id IS NULL OR label_occurrence_id >= 0),
  label                TEXT CHECK(label IS NULL OR length(label) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  CHECK((label_occurrence_id IS NULL AND label IS NULL)
        OR (label_occurrence_id IS NOT NULL AND label IS NOT NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_constructor_fields(
  blob_id        INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  ordinal        INTEGER NOT NULL CHECK(ordinal >= 0),
  visibility     TEXT NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_declaration_properties(blob_id, declaration_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_declaration_properties(
  blob_id                    INTEGER NOT NULL,
  declaration_id             INTEGER NOT NULL CHECK(declaration_id >= 0),
  visibility                 TEXT NOT NULL,
  cfg_condition              TEXT NOT NULL,
  constructor_non_exhaustive INTEGER CHECK(constructor_non_exhaustive IN (0, 1)), declaration_kind INTEGER CHECK(declaration_kind BETWEEN 0 AND 14), macro_exported INTEGER CHECK(macro_exported IN (0, 1)), trait_impl_member INTEGER CHECK(trait_impl_member IN (0, 1)), has_impl_or_trait_ancestor INTEGER
  CHECK(has_impl_or_trait_ancestor IN (0, 1)), nearest_declaration_boundary INTEGER
  CHECK(nearest_declaration_boundary BETWEEN 0 AND 3),
  -- A struct or enum whose `#[serde(..)]` helper is inert exactly when this
  -- bare derive name, which the item's file does not bind, is serde's derive;
  -- NULL for every other declaration. The selected stage decides it through
  -- the crate rows and closes the declaration's open binder gap.
  serde_helper_derive TEXT CHECK(serde_helper_derive IS NULL OR serde_helper_derive IN ('Serialize', 'Deserialize')),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id) REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_impl_items(
  body_start_byte INTEGER CHECK(body_start_byte >= 0) CHECK((body_occurrence_id IS NULL) = (body_start_byte IS NULL)),
  body_end_byte INTEGER CHECK(body_end_byte >= body_start_byte) CHECK((body_occurrence_id IS NULL) = (body_end_byte IS NULL)),
  negation_start_byte INTEGER CHECK(negation_start_byte >= 0) CHECK((negation_occurrence_id IS NULL) = (negation_start_byte IS NULL)),
  negation_end_byte INTEGER CHECK(negation_end_byte >= negation_start_byte) CHECK((negation_occurrence_id IS NULL) = (negation_end_byte IS NULL)),
  blob_id                 INTEGER NOT NULL,
  declaration_id          INTEGER NOT NULL CHECK(declaration_id >= 0),
  context_occurrence_id   INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  trait_type_occurrence_id INTEGER CHECK(trait_type_occurrence_id IS NULL OR trait_type_occurrence_id >= 0),
  negation_occurrence_id  INTEGER CHECK(negation_occurrence_id IS NULL OR negation_occurrence_id >= 0),
  target_type_occurrence_id INTEGER CHECK(target_type_occurrence_id IS NULL OR target_type_occurrence_id >= 0),
  body_occurrence_id      INTEGER CHECK(body_occurrence_id IS NULL OR body_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, trait_type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, target_type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_import_contexts(
  declaration_start_byte INTEGER NOT NULL CHECK(declaration_start_byte >= 0),
  declaration_end_byte INTEGER NOT NULL CHECK(declaration_end_byte >= declaration_start_byte),
  blob_id                     INTEGER NOT NULL,
  declaration_occurrence_id   INTEGER NOT NULL CHECK(declaration_occurrence_id >= 0),
  owner_module                TEXT NOT NULL,
  owner_scope_occurrence_id   INTEGER
    CHECK(owner_scope_occurrence_id IS NULL OR owner_scope_occurrence_id >= 0),
  local_scope_occurrence_id   INTEGER
    CHECK(local_scope_occurrence_id IS NULL OR local_scope_occurrence_id >= 0),
  visibility                  TEXT NOT NULL,
  cfg_condition               TEXT NOT NULL, native_scope INTEGER
  CHECK(native_scope IS NULL OR native_scope >= 0),
  owner_scope_start_byte INTEGER CHECK(owner_scope_start_byte >= 0),
  owner_scope_end_byte   INTEGER CHECK(owner_scope_end_byte >= owner_scope_start_byte),
  local_scope_start_byte INTEGER CHECK(local_scope_start_byte >= 0),
  local_scope_end_byte   INTEGER CHECK(local_scope_end_byte >= local_scope_start_byte),
  PRIMARY KEY(blob_id, declaration_occurrence_id),
  CHECK((owner_scope_occurrence_id IS NULL) = (owner_scope_start_byte IS NULL)),
  CHECK((local_scope_occurrence_id IS NULL) = (local_scope_start_byte IS NULL)),
  CHECK((owner_scope_occurrence_id IS NULL) = (owner_scope_end_byte IS NULL)),
  CHECK((local_scope_occurrence_id IS NULL) = (local_scope_end_byte IS NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  CHECK((owner_scope_occurrence_id IS NULL) = (owner_module = ''))
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_body_children(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  blob_id              INTEGER NOT NULL,
  owner_declaration_id INTEGER NOT NULL CHECK(owner_declaration_id >= 0),
  ordinal              INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id        INTEGER NOT NULL CHECK(occurrence_id >= 0),
  declaration_id       INTEGER CHECK(declaration_id IS NULL OR declaration_id >= 0),
  syntax_kind          TEXT NOT NULL CHECK(length(syntax_kind) > 0),
  PRIMARY KEY(blob_id, owner_declaration_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, owner_declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_contexts(
  blob_id               INTEGER NOT NULL,
  occurrence_id         INTEGER NOT NULL CHECK(occurrence_id >= 0),
  ordinal               INTEGER NOT NULL CHECK(ordinal >= 0),
  parent_occurrence_id  INTEGER CHECK(parent_occurrence_id IS NULL OR parent_occurrence_id >= 0),
  owner_declaration_id  INTEGER CHECK(owner_declaration_id IS NULL OR owner_declaration_id >= 0),
  context_kind          INTEGER NOT NULL CHECK(context_kind BETWEEN 0 AND 7),
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte   INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, occurrence_id),
  UNIQUE(blob_id, ordinal),
  CHECK(
    (context_kind IN (1, 2, 3, 4, 7) AND owner_declaration_id IS NOT NULL)
    OR (context_kind IN (0, 5, 6) AND owner_declaration_id IS NULL)
  ),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, occurrence_id)
    REFERENCES source_rust_item_syntax(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, parent_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, owner_declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_generic_parameters(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  name_start_byte INTEGER CHECK(name_start_byte >= 0) CHECK((name_occurrence_id IS NULL) = (name_start_byte IS NULL)),
  name_end_byte INTEGER CHECK(name_end_byte >= name_start_byte) CHECK((name_occurrence_id IS NULL) = (name_end_byte IS NULL)),
  blob_id              INTEGER NOT NULL,
  declaration_id       INTEGER NOT NULL CHECK(declaration_id >= 0),
  ordinal              INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id        INTEGER NOT NULL CHECK(occurrence_id >= 0),
  syntax_kind          TEXT NOT NULL CHECK(length(syntax_kind) > 0),
  name_occurrence_id   INTEGER CHECK(name_occurrence_id IS NULL OR name_occurrence_id >= 0),
  name                 TEXT CHECK(name IS NULL OR length(name) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  CHECK((name_occurrence_id IS NULL AND name IS NULL)
        OR (name_occurrence_id IS NOT NULL AND name IS NOT NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_import_contexts(
  blob_id                INTEGER NOT NULL,
  declaration_occurrence_id INTEGER NOT NULL CHECK(declaration_occurrence_id >= 0),
  context_occurrence_id  INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_occurrence_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_macro_expansions(
  blob_id                  INTEGER NOT NULL,
  invocation_occurrence_id INTEGER NOT NULL CHECK(invocation_occurrence_id >= 0),
  context_occurrence_id    INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  source_position          INTEGER CHECK(source_position BETWEEN 0 AND 2),
  expansion_kind           INTEGER NOT NULL CHECK(expansion_kind BETWEEN 0 AND 4),
  root_occurrence_id       INTEGER CHECK(root_occurrence_id IS NULL OR root_occurrence_id >= 0),
  invocation_start_byte INTEGER NOT NULL CHECK(invocation_start_byte >= 0),
  invocation_end_byte   INTEGER NOT NULL CHECK(invocation_end_byte >= invocation_start_byte),
  PRIMARY KEY(blob_id, invocation_occurrence_id),
  CHECK((expansion_kind = 0 AND root_occurrence_id IS NOT NULL)
        OR (expansion_kind IN (1, 2, 3, 4) AND root_occurrence_id IS NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_macros(
  blob_id       INTEGER NOT NULL,
  lang          TEXT NOT NULL,
  ordinal       INTEGER NOT NULL CHECK(ordinal >= 0),
  macro_name    TEXT NOT NULL,
  passthrough   INTEGER NOT NULL CHECK(passthrough IN (0, 1)),
  -- Every rule expands to its replayed item arguments and nothing else: the
  -- items exist exactly as the arguments write them. Implies passthrough.
  arguments_only INTEGER NOT NULL CHECK(arguments_only IN (0, 1)),
  -- The activation every rule adds to each item it replays, encoded like
  -- `source_rust_declaration_properties.cfg_condition`: the conjoined `cfg`
  -- attributes a rule writes before the replayed item (`$( #[cfg(unix)]
  -- $item )*` adds `atom unix`; nothing added is `always`). NULL when a rule
  -- adds anything else, or the rules disagree: the expansion is then not
  -- decided. Read from the definition's own rules, and from a same-file
  -- definition a delegating passthrough invokes.
  decoration_cfg TEXT CHECK(decoration_cfg IS NULL OR length(decoration_cfg) > 0),
  declaration_id INTEGER CHECK(declaration_id >= 0),
  -- No rule can write an item: every transcriber is empty or holds no item
  -- token, no nested invocation and no metavariable that could supply one.
  -- An item-position invocation of it declares nothing, whatever its input.
  declares_no_item INTEGER NOT NULL DEFAULT 0 CHECK(declares_no_item IN (0, 1)),
  -- Every rule writes only `impl` blocks and splices only `ty`, `expr`,
  -- `path` or `lifetime` fragments: an item-position invocation binds no name
  -- in its module and can only add members to types.
  writes_only_impls INTEGER NOT NULL DEFAULT 0 CHECK(writes_only_impls IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  CHECK(declares_no_item = 0 OR passthrough = 0),
  CHECK(writes_only_impls = 0 OR passthrough = 0),
  CHECK(arguments_only = 0 OR passthrough = 1),
  CHECK(decoration_cfg IS NULL OR passthrough = 1),
  CHECK(arguments_only = 0 OR decoration_cfg = 'always'),
  FOREIGN KEY(blob_id, lang) REFERENCES blobs(id, lang) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_declaration_properties(blob_id, declaration_id)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_manifests(
  blob_id       INTEGER NOT NULL PRIMARY KEY,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows  INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0), macro_facts_version INTEGER
    CHECK(macro_facts_version IS NULL OR macro_facts_version = 1), type_forms_version INTEGER
  CHECK(type_forms_version IS NULL OR type_forms_version = 1), macro_contexts_version INTEGER
    CHECK(macro_contexts_version IS NULL OR macro_contexts_version = 1),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_item_syntax(
  blob_id      INTEGER NOT NULL,
  occurrence_id INTEGER NOT NULL CHECK(occurrence_id >= 0),
  has_error    INTEGER NOT NULL CHECK(has_error IN (0, 1)),
  PRIMARY KEY(blob_id, occurrence_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_arms(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id               INTEGER NOT NULL,
  declaration_id        INTEGER NOT NULL CHECK(declaration_id >= 0),
  ordinal               INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id         INTEGER NOT NULL CHECK(occurrence_id >= 0),
  pattern_occurrence_id INTEGER CHECK(pattern_occurrence_id IS NULL OR pattern_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  UNIQUE(blob_id, occurrence_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_macro_definitions(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, ordinal, pattern_occurrence_id)
    REFERENCES source_rust_macro_pattern_nodes(
      blob_id, declaration_id, arm_ordinal, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_definitions(
  blob_id               INTEGER NOT NULL,
  declaration_id        INTEGER NOT NULL CHECK(declaration_id >= 0),
  ordinal               INTEGER NOT NULL CHECK(ordinal >= 0),
  is_macro_rules        INTEGER NOT NULL CHECK(is_macro_rules IN (0, 1)),
  context_occurrence_id INTEGER
    CHECK(context_occurrence_id IS NULL OR context_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  UNIQUE(blob_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_ident_roles(
  blob_id        INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  arm_ordinal    INTEGER NOT NULL CHECK(arm_ordinal >= 0),
  ordinal        INTEGER NOT NULL CHECK(ordinal >= 0),
  name           TEXT NOT NULL CHECK(length(name) > 0),
  role           INTEGER NOT NULL CHECK(role BETWEEN 0 AND 6),
  PRIMARY KEY(blob_id, declaration_id, arm_ordinal, ordinal),
  UNIQUE(blob_id, declaration_id, arm_ordinal, name),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, arm_ordinal)
    REFERENCES source_rust_macro_arms(blob_id, declaration_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_input_tokens(
  blob_id INTEGER NOT NULL,
  invocation_occurrence_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  source_occurrence_id INTEGER NOT NULL CHECK(source_occurrence_id >= 0),
  parent_ordinal INTEGER CHECK(parent_ordinal IS NULL OR (parent_ordinal >= 0 AND parent_ordinal < ordinal)),
  syntax_kind TEXT NOT NULL CHECK(length(syntax_kind) > 0),
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  PRIMARY KEY(blob_id, invocation_occurrence_id, ordinal),
  FOREIGN KEY(blob_id, invocation_occurrence_id)
    REFERENCES source_rust_macro_inputs(blob_id, invocation_occurrence_id)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, invocation_occurrence_id, parent_ordinal)
    REFERENCES source_rust_macro_input_tokens(blob_id, invocation_occurrence_id, ordinal)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_inputs(
  blob_id INTEGER NOT NULL,
  invocation_occurrence_id INTEGER NOT NULL,
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  source TEXT NOT NULL,
  native_gap_site INTEGER CHECK(native_gap_site BETWEEN 0 AND 4294967295),
  native_scope INTEGER CHECK(native_scope BETWEEN 0 AND 4294967295),
  invocation_start_byte INTEGER NOT NULL CHECK(invocation_start_byte >= 0),
  CHECK((native_gap_site IS NULL) = (native_scope IS NULL)),
  PRIMARY KEY(blob_id, invocation_occurrence_id),
  FOREIGN KEY(blob_id, invocation_occurrence_id)
    REFERENCES source_rust_item_macro_expansions(blob_id, invocation_occurrence_id)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_invocations(
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id       INTEGER NOT NULL,
  occurrence_id INTEGER NOT NULL CHECK(occurrence_id >= 0),
  macro_name    TEXT NOT NULL CHECK(length(macro_name) > 0),
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte   INTEGER NOT NULL CHECK(end_byte >= start_byte),
  PRIMARY KEY(blob_id, occurrence_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_macro_pattern_nodes(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id          INTEGER NOT NULL,
  declaration_id   INTEGER NOT NULL CHECK(declaration_id >= 0),
  arm_ordinal      INTEGER NOT NULL CHECK(arm_ordinal >= 0),
  ordinal          INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id    INTEGER NOT NULL CHECK(occurrence_id >= 0),
  parent_occurrence_id INTEGER CHECK(parent_occurrence_id IS NULL OR parent_occurrence_id >= 0),
  node_kind        INTEGER NOT NULL CHECK(node_kind BETWEEN 0 AND 4),
  literal_kind     TEXT,
  literal_text     TEXT,
  binding_name     TEXT,
  fragment_kind    INTEGER CHECK(fragment_kind BETWEEN 0 AND 12),
  delimiter        INTEGER CHECK(delimiter BETWEEN 0 AND 2),
  separator        TEXT,
  operator         INTEGER CHECK(operator BETWEEN 0 AND 2),
  PRIMARY KEY(blob_id, declaration_id, arm_ordinal, ordinal),
  UNIQUE(blob_id, declaration_id, arm_ordinal, occurrence_id),
  UNIQUE(blob_id, occurrence_id),
  CHECK(
    (node_kind = 0
      AND literal_kind IS NOT NULL AND length(literal_kind) > 0
      AND literal_text IS NOT NULL
      AND binding_name IS NULL AND fragment_kind IS NULL
      AND delimiter IS NULL AND separator IS NULL AND operator IS NULL)
    OR
    (node_kind = 1
      AND binding_name IS NOT NULL AND length(binding_name) > 0
      AND fragment_kind IS NOT NULL
      AND literal_kind IS NULL AND literal_text IS NULL
      AND delimiter IS NULL AND separator IS NULL AND operator IS NULL)
    OR
    (node_kind = 2
      AND literal_kind IS NULL AND literal_text IS NULL
      AND binding_name IS NULL AND fragment_kind IS NULL
      AND separator IS NULL AND operator IS NULL)
    OR
    (node_kind = 3
      AND operator IS NOT NULL
      AND (separator IS NULL OR length(separator) > 0)
      AND literal_kind IS NULL AND literal_text IS NULL
      AND binding_name IS NULL AND fragment_kind IS NULL
      AND delimiter IS NULL)
    OR
    (node_kind = 4
      AND literal_kind IS NULL AND literal_text IS NULL
      AND binding_name IS NULL AND fragment_kind IS NULL
      AND delimiter IS NULL AND separator IS NULL AND operator IS NULL)
  ),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, arm_ordinal)
    REFERENCES source_rust_macro_arms(blob_id, declaration_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id, arm_ordinal, parent_occurrence_id)
    REFERENCES source_rust_macro_pattern_nodes(
      blob_id, declaration_id, arm_ordinal, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_declarations(
  body_provenance INTEGER CHECK(body_provenance BETWEEN 0 AND 2) CHECK((body_occurrence_id IS NULL) = (body_provenance IS NULL)),
  blob_id          INTEGER NOT NULL,
  declaration_id   INTEGER NOT NULL CHECK(declaration_id >= 0),
  module_name      TEXT NOT NULL CHECK(length(module_name) > 0),
  body_occurrence_id INTEGER CHECK(body_occurrence_id IS NULL OR body_occurrence_id >= 0),
  path_attribute   TEXT,
  macro_use        INTEGER NOT NULL CHECK(macro_use IN (0, 1)),
  test_gated       INTEGER NOT NULL CHECK(test_gated IN (0, 1)),
  body_start_byte INTEGER CHECK(body_start_byte >= 0),
  body_end_byte   INTEGER CHECK(body_end_byte >= body_start_byte),
  PRIMARY KEY(blob_id, declaration_id),
  CHECK((body_occurrence_id IS NULL) = (body_start_byte IS NULL)),
  CHECK((body_start_byte IS NULL) = (body_end_byte IS NULL)),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_declaration_properties(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

-- The crate-level inner attributes (`#![name(arguments)]`) written at the top
-- of one file, in source order. Each row is one attribute: its path, and the
-- identifiers and literals of its top-level argument tokens as a JSON array of
-- strings, read from the tree-sitter attribute node. Reader: crate derivation,
-- which reads a crate root file's rows for `no_std` and `no_core` to decide
-- which prelude the crate uses (`rust_crate_topologies.prelude`).
CREATE TABLE source_rust_inner_attributes(
  blob_id    INTEGER NOT NULL,
  ordinal    INTEGER NOT NULL CHECK(ordinal >= 0),
  name       TEXT NOT NULL CHECK(length(name) > 0),
  arguments  TEXT NOT NULL CHECK(json_valid(arguments) AND json_type(arguments) = 'array'),
  PRIMARY KEY(blob_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_inventory(
  blob_id             INTEGER NOT NULL,
  ordinal             INTEGER NOT NULL CHECK(ordinal >= 0),
  parent_scope_ordinal INTEGER NOT NULL CHECK(parent_scope_ordinal >= 0),
  declaration_id      INTEGER CHECK(declaration_id IS NULL OR declaration_id >= 0),
  module_name         TEXT NOT NULL CHECK(length(module_name) > 0 OR ordinal = 0),
  PRIMARY KEY(blob_id, ordinal),
  UNIQUE(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, parent_scope_ordinal)
    REFERENCES source_rust_module_scopes(blob_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_module_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_manifests(
  root_provenance INTEGER NOT NULL CHECK(root_provenance BETWEEN 0 AND 2),
  blob_id           INTEGER NOT NULL PRIMARY KEY,
  facts_version     INTEGER NOT NULL CHECK(facts_version = 1),
  root_occurrence_id INTEGER NOT NULL CHECK(root_occurrence_id >= 0),
  root_start_byte INTEGER NOT NULL CHECK(root_start_byte >= 0),
  root_end_byte   INTEGER NOT NULL CHECK(root_end_byte >= root_start_byte),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_route_gates(
  blob_id                INTEGER NOT NULL,
  route_ordinal          INTEGER NOT NULL,
  gate_ordinal           INTEGER NOT NULL CHECK(gate_ordinal >= 0),
  invocation_occurrence_id INTEGER NOT NULL CHECK(invocation_occurrence_id >= 0),
  PRIMARY KEY(blob_id, route_ordinal, gate_ordinal),
  UNIQUE(blob_id, route_ordinal, invocation_occurrence_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, route_ordinal)
    REFERENCES source_rust_module_routes(blob_id, ordinal)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, invocation_occurrence_id)
    REFERENCES source_rust_macro_invocations(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_routes(
  blob_id        INTEGER NOT NULL,
  ordinal        INTEGER NOT NULL CHECK(ordinal >= 0),
  scope_ordinal  INTEGER NOT NULL CHECK(scope_ordinal >= 0),
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  imports_macros INTEGER NOT NULL CHECK(imports_macros IN (0, 1)),
  PRIMARY KEY(blob_id, ordinal),
  UNIQUE(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, scope_ordinal)
    REFERENCES source_rust_module_scopes(blob_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_module_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_module_scopes(
  blob_id          INTEGER NOT NULL,
  ordinal          INTEGER NOT NULL CHECK(ordinal >= 0),
  parent_ordinal   INTEGER CHECK(parent_ordinal IS NULL OR parent_ordinal >= 0),
  declaration_id   INTEGER CHECK(declaration_id IS NULL OR declaration_id >= 0),
  module_name      TEXT NOT NULL CHECK(length(module_name) > 0 OR ordinal = 0),
  imports_macros   INTEGER NOT NULL CHECK(imports_macros IN (0, 1)),
  resolution_scope INTEGER CHECK(resolution_scope IS NULL OR resolution_scope >= 0),
  PRIMARY KEY(blob_id, ordinal),
  UNIQUE(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_module_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, parent_ordinal)
    REFERENCES source_rust_module_scopes(blob_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_rust_module_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_trait_items(
  body_start_byte INTEGER CHECK(body_start_byte >= 0) CHECK((body_occurrence_id IS NULL) = (body_start_byte IS NULL)),
  body_end_byte INTEGER CHECK(body_end_byte >= body_start_byte) CHECK((body_occurrence_id IS NULL) = (body_end_byte IS NULL)),
  blob_id               INTEGER NOT NULL,
  declaration_id        INTEGER NOT NULL CHECK(declaration_id >= 0),
  context_occurrence_id INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  body_occurrence_id    INTEGER CHECK(body_occurrence_id IS NULL OR body_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_type_children(
  blob_id INTEGER NOT NULL,
  type_occurrence_id INTEGER NOT NULL CHECK(type_occurrence_id >= 0),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL CHECK(occurrence_id >= 0),
  PRIMARY KEY(blob_id, type_occurrence_id, ordinal),
  UNIQUE(blob_id, type_occurrence_id, occurrence_id),
  FOREIGN KEY(blob_id) REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id) REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, occurrence_id) REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_type_generic_arguments(
  blob_id           INTEGER NOT NULL,
  type_occurrence_id INTEGER NOT NULL CHECK(type_occurrence_id >= 0),
  segment_ordinal   INTEGER NOT NULL CHECK(segment_ordinal >= 0),
  ordinal           INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id     INTEGER NOT NULL CHECK(occurrence_id >= 0),
  PRIMARY KEY(blob_id, type_occurrence_id, segment_ordinal, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id, segment_ordinal)
    REFERENCES source_rust_type_generic_lists(blob_id, type_occurrence_id, segment_ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_type_generic_lists(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id           INTEGER NOT NULL,
  type_occurrence_id INTEGER NOT NULL CHECK(type_occurrence_id >= 0),
  segment_ordinal   INTEGER NOT NULL CHECK(segment_ordinal >= 0),
  occurrence_id     INTEGER NOT NULL CHECK(occurrence_id >= 0),
  PRIMARY KEY(blob_id, type_occurrence_id, segment_ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id, segment_ordinal)
    REFERENCES source_rust_type_segments(blob_id, type_occurrence_id, ordinal)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_type_segments(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id           INTEGER NOT NULL,
  type_occurrence_id INTEGER NOT NULL CHECK(type_occurrence_id >= 0),
  ordinal           INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id     INTEGER NOT NULL CHECK(occurrence_id >= 0),
  name              TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, type_occurrence_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_type_wrappers(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  blob_id           INTEGER NOT NULL,
  type_occurrence_id INTEGER NOT NULL CHECK(type_occurrence_id >= 0),
  ordinal           INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id     INTEGER NOT NULL CHECK(occurrence_id >= 0),
  wrapper_kind      INTEGER NOT NULL CHECK(wrapper_kind BETWEEN 0 AND 3),
  PRIMARY KEY(blob_id, type_occurrence_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_types(
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  provenance INTEGER NOT NULL CHECK(provenance BETWEEN 0 AND 2),
  unsupported_start_byte INTEGER CHECK(unsupported_start_byte >= 0) CHECK((unsupported_occurrence_id IS NULL) = (unsupported_start_byte IS NULL)),
  unsupported_end_byte INTEGER CHECK(unsupported_end_byte >= unsupported_start_byte) CHECK((unsupported_occurrence_id IS NULL) = (unsupported_end_byte IS NULL)),
  unsupported_provenance INTEGER CHECK(unsupported_provenance BETWEEN 0 AND 2) CHECK((unsupported_occurrence_id IS NULL) = (unsupported_provenance IS NULL)),
  compound_start_byte INTEGER CHECK(compound_start_byte >= 0) CHECK((compound_occurrence_id IS NULL) = (compound_start_byte IS NULL)),
  compound_end_byte INTEGER CHECK(compound_end_byte >= compound_start_byte) CHECK((compound_occurrence_id IS NULL) = (compound_end_byte IS NULL)),
  compound_provenance INTEGER CHECK(compound_provenance BETWEEN 0 AND 2) CHECK((compound_occurrence_id IS NULL) = (compound_provenance IS NULL)),
  type_parameters_start_byte INTEGER CHECK(type_parameters_start_byte >= 0) CHECK((type_parameters_occurrence_id IS NULL) = (type_parameters_start_byte IS NULL)),
  type_parameters_end_byte INTEGER CHECK(type_parameters_end_byte >= type_parameters_start_byte) CHECK((type_parameters_occurrence_id IS NULL) = (type_parameters_end_byte IS NULL)),
  type_parameters_provenance INTEGER CHECK(type_parameters_provenance BETWEEN 0 AND 2) CHECK((type_parameters_occurrence_id IS NULL) = (type_parameters_provenance IS NULL)),
  blob_id INTEGER NOT NULL,
  occurrence_id INTEGER NOT NULL CHECK(occurrence_id >= 0),
  path_kind INTEGER NOT NULL CHECK(path_kind BETWEEN 0 AND 5),
  leading_absolute INTEGER CHECK(leading_absolute IS NULL OR leading_absolute IN (0, 1)),
  unsupported_occurrence_id INTEGER CHECK(unsupported_occurrence_id IS NULL OR unsupported_occurrence_id >= 0),
  unsupported_syntax_kind TEXT,
  compound_occurrence_id INTEGER CHECK(compound_occurrence_id IS NULL OR compound_occurrence_id >= 0),
  type_parameters_occurrence_id INTEGER CHECK(type_parameters_occurrence_id IS NULL OR type_parameters_occurrence_id >= 0),
  PRIMARY KEY(blob_id, occurrence_id),
  CHECK(
    (path_kind = 0 AND leading_absolute IS NOT NULL
      AND unsupported_occurrence_id IS NULL AND unsupported_syntax_kind IS NULL
      AND compound_occurrence_id IS NULL AND type_parameters_occurrence_id IS NULL)
    OR (path_kind = 1 AND leading_absolute IS NULL
      AND unsupported_occurrence_id IS NOT NULL AND unsupported_syntax_kind IS NOT NULL
      AND length(unsupported_syntax_kind) > 0
      AND compound_occurrence_id IS NULL AND type_parameters_occurrence_id IS NULL)
    OR (path_kind BETWEEN 2 AND 5 AND leading_absolute IS NULL
      AND unsupported_occurrence_id IS NULL AND unsupported_syntax_kind IS NULL
      AND compound_occurrence_id IS NOT NULL
      AND (path_kind IN (2, 5) OR type_parameters_occurrence_id IS NULL))
  ),
  FOREIGN KEY(blob_id) REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id) REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_rust_value_items(
  blob_id                 INTEGER NOT NULL,
  declaration_id          INTEGER NOT NULL CHECK(declaration_id >= 0),
  context_occurrence_id   INTEGER NOT NULL CHECK(context_occurrence_id >= 0),
  declared_type_occurrence_id INTEGER CHECK(declared_type_occurrence_id IS NULL OR declared_type_occurrence_id >= 0),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id)
    REFERENCES source_rust_item_manifests(blob_id)
    DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, context_occurrence_id)
    REFERENCES source_rust_item_contexts(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, declared_type_occurrence_id)
    REFERENCES source_rust_types(blob_id, occurrence_id)
    ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE source_scala_callable_function_path_cells(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  list_ordinal INTEGER NOT NULL,
  parameter_ordinal INTEGER NOT NULL,
  function_ordinal INTEGER NOT NULL CHECK(function_ordinal >= 0),
  present INTEGER NOT NULL CHECK(present IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal, function_ordinal),
  FOREIGN KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal)
    REFERENCES source_scala_callable_parameters(blob_id, declaration_id, list_ordinal, ordinal)
    ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_function_path_segments(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  list_ordinal INTEGER NOT NULL,
  parameter_ordinal INTEGER NOT NULL,
  function_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal, function_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal, function_ordinal)
    REFERENCES source_scala_callable_function_path_cells(
      blob_id, declaration_id, list_ordinal, parameter_ordinal, function_ordinal
    ) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_function_paths(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  list_ordinal INTEGER NOT NULL,
  parameter_ordinal INTEGER NOT NULL,
  present INTEGER NOT NULL CHECK(present = 1),
  PRIMARY KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal),
  FOREIGN KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal)
    REFERENCES source_scala_callable_parameters(blob_id, declaration_id, list_ordinal, ordinal)
    ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_lists(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  kind INTEGER NOT NULL CHECK(kind IN (0, 1)),
  required_arity INTEGER NOT NULL CHECK(required_arity >= 0),
  total_arity INTEGER NOT NULL CHECK(total_arity >= required_arity),
  repeated INTEGER NOT NULL CHECK(repeated IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_callables(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_parameter_path_segments(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  list_ordinal INTEGER NOT NULL,
  parameter_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, list_ordinal, parameter_ordinal)
    REFERENCES source_scala_callable_parameters(blob_id, declaration_id, list_ordinal, ordinal)
    ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_parameters(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  list_ordinal INTEGER NOT NULL CHECK(list_ordinal >= 0),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  defaulted INTEGER NOT NULL CHECK(defaulted IN (0, 1)),
  function_arity INTEGER CHECK(function_arity IS NULL OR function_arity >= 0),
  type_path_present INTEGER NOT NULL CHECK(type_path_present IN (0, 1)),
  type_expression_id INTEGER,
  function_path_present INTEGER NOT NULL CHECK(function_path_present IN (0, 1)),
  PRIMARY KEY(blob_id, declaration_id, list_ordinal, ordinal),
  FOREIGN KEY(blob_id, declaration_id, list_ordinal)
    REFERENCES source_scala_callable_lists(blob_id, declaration_id, ordinal) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, type_expression_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callable_path_segments(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  path_kind INTEGER NOT NULL CHECK(path_kind IN (0, 1)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, declaration_id, path_kind, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_callables(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_callables(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  role INTEGER NOT NULL CHECK(role IN (0, 1, 2)),
  function_lists INTEGER NOT NULL CHECK(function_lists >= 0),
  result_open INTEGER NOT NULL CHECK(result_open IN (0, 1)),
  parameter_defaults_present INTEGER NOT NULL CHECK(parameter_defaults_present IN (0, 1)),
  parameter_function_arities_present INTEGER NOT NULL CHECK(parameter_function_arities_present IN (0, 1)),
  parameter_type_paths_present INTEGER NOT NULL CHECK(parameter_type_paths_present IN (0, 1)),
  parameter_type_expressions_present INTEGER NOT NULL CHECK(parameter_type_expressions_present IN (0, 1)),
  parameter_function_type_paths_present INTEGER NOT NULL CHECK(parameter_function_type_paths_present IN (0, 1)),
  extension_path_present INTEGER NOT NULL CHECK(extension_path_present IN (0, 1)),
  return_path_present INTEGER NOT NULL CHECK(return_path_present IN (0, 1)),
  return_type_is_singleton INTEGER NOT NULL CHECK(return_type_is_singleton IN (0, 1)),
  return_expression_id INTEGER,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_declarations(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, return_expression_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_declaration_lexical_prefixes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  prefix TEXT NOT NULL CHECK(length(prefix) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_declaration_lexical_scopes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  occurrence_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_declaration_manifests(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  facts_version INTEGER NOT NULL CHECK(facts_version = 1),
  logical_rows INTEGER NOT NULL CHECK(logical_rows >= 1),
  payload_bytes INTEGER NOT NULL CHECK(payload_bytes >= 0)
) STRICT;

CREATE TABLE source_scala_declaration_path_segments(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  path_kind INTEGER NOT NULL CHECK(path_kind IN (0, 1)),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, declaration_id, path_kind, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_declarations(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL CHECK(declaration_id >= 0),
  kind INTEGER NOT NULL CHECK(kind IN (0, 1, 2, 3, 4, 5, 6)),
  visibility INTEGER NOT NULL CHECK(visibility IN (0, 1, 2)),
  callable_present INTEGER NOT NULL CHECK(callable_present IN (0, 1)),
  field_type_path_present INTEGER NOT NULL CHECK(field_type_path_present IN (0, 1)),
  type_alias_path_present INTEGER NOT NULL CHECK(type_alias_path_present IN (0, 1)),
  stable_owner INTEGER NOT NULL CHECK(stable_owner IN (0, 1)),
  is_enum INTEGER NOT NULL CHECK(is_enum IN (0, 1)),
  is_term_field INTEGER NOT NULL CHECK(is_term_field IN (0, 1)),
  is_case_class INTEGER NOT NULL CHECK(is_case_class IN (0, 1)),
  is_full_enum_case INTEGER NOT NULL CHECK(is_full_enum_case IN (0, 1)),
  is_abstract_callable INTEGER NOT NULL CHECK(is_abstract_callable IN (0, 1)),
  is_explicitly_abstract INTEGER NOT NULL CHECK(is_explicitly_abstract IN (0, 1)),
  is_sealed INTEGER NOT NULL CHECK(is_sealed IN (0, 1)),
  is_final INTEGER NOT NULL CHECK(is_final IN (0, 1)),
  generic_owner_present INTEGER NOT NULL CHECK(generic_owner_present IN (0, 1)),
  CHECK(is_enum = (kind = 4)),
  CHECK(is_full_enum_case = 0 OR kind = 5),
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_generic_owners(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  PRIMARY KEY(blob_id, declaration_id),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_declarations(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_generic_parameters(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL CHECK(length(name) > 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_generic_owners(blob_id, declaration_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_generic_supertypes(
  blob_id INTEGER NOT NULL,
  declaration_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  expression_id INTEGER NOT NULL CHECK(expression_id >= 0),
  PRIMARY KEY(blob_id, declaration_id, ordinal),
  FOREIGN KEY(blob_id, declaration_id)
    REFERENCES source_scala_generic_owners(blob_id, declaration_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, expression_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_type_expression_arguments(
  blob_id INTEGER NOT NULL,
  expression_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  child_id INTEGER NOT NULL CHECK(child_id >= 0 AND child_id < expression_id),
  PRIMARY KEY(blob_id, expression_id, ordinal),
  FOREIGN KEY(blob_id, expression_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_type_expression_segments(
  blob_id INTEGER NOT NULL,
  expression_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  segment TEXT NOT NULL CHECK(length(segment) > 0),
  PRIMARY KEY(blob_id, expression_id, ordinal),
  FOREIGN KEY(blob_id, expression_id)
    REFERENCES source_scala_type_expressions(blob_id, expression_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_scala_type_expressions(
  blob_id INTEGER NOT NULL,
  expression_id INTEGER NOT NULL CHECK(expression_id >= 0),
  PRIMARY KEY(blob_id, expression_id),
  FOREIGN KEY(blob_id) REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE source_structural_nodes(
  blob_id                 INTEGER NOT NULL,
  node_id                 INTEGER NOT NULL CHECK(node_id >= 0),
  kind_code               INTEGER NOT NULL CHECK(kind_code >= 0),
  boolean_value           INTEGER CHECK(boolean_value IN (0, 1)),
  construct               TEXT,
  start_byte              INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte                INTEGER NOT NULL CHECK(end_byte >= start_byte),
  name_start_byte         INTEGER CHECK(name_start_byte >= 0),
  name_end_byte           INTEGER CHECK(name_end_byte >= name_start_byte),
  parent_node_id          INTEGER CHECK(parent_node_id >= 0 AND parent_node_id < node_id),
  subtree_end             INTEGER NOT NULL CHECK(subtree_end > node_id),
  call_kind_code          INTEGER CHECK(call_kind_code >= 0),
  call_coverage_code      INTEGER CHECK(call_coverage_code >= 0),
  continues_callee_groups INTEGER CHECK(continues_callee_groups IN (0, 1)),
  PRIMARY KEY(blob_id, node_id),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  CHECK((name_start_byte IS NULL) = (name_end_byte IS NULL)),
  CHECK(
    (call_coverage_code IS NULL AND call_kind_code IS NULL AND continues_callee_groups IS NULL)
    OR (call_coverage_code IS NOT NULL AND continues_callee_groups IS NOT NULL)
  )
) WITHOUT ROWID, STRICT;

CREATE TABLE source_structural_occurrence_roles(
  blob_id   INTEGER NOT NULL,
  node_id   INTEGER NOT NULL CHECK(node_id >= 0),
  ordinal   INTEGER NOT NULL CHECK(ordinal >= 0),
  role_code INTEGER NOT NULL CHECK(role_code >= 0),
  PRIMARY KEY(blob_id, node_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE source_structural_roles(
  blob_id             INTEGER NOT NULL,
  source_node_id      INTEGER NOT NULL CHECK(source_node_id >= 0),
  ordinal             INTEGER NOT NULL CHECK(ordinal >= 0),
  role_code           INTEGER NOT NULL CHECK(role_code >= 0),
  spread              INTEGER NOT NULL CHECK(spread IN (0, 1)),
  target_node_id      INTEGER CHECK(target_node_id >= 0),
  start_byte          INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte            INTEGER NOT NULL CHECK(end_byte >= start_byte),
  name_start_byte     INTEGER CHECK(name_start_byte >= 0),
  name_end_byte       INTEGER CHECK(name_end_byte >= name_start_byte),
  keyword_start_byte  INTEGER CHECK(keyword_start_byte >= 0),
  keyword_end_byte    INTEGER CHECK(keyword_end_byte >= keyword_start_byte),
  PRIMARY KEY(blob_id, source_node_id, ordinal),
  FOREIGN KEY(blob_id)
    REFERENCES source_fact_manifests(blob_id) ON DELETE CASCADE,
  CHECK((name_start_byte IS NULL) = (name_end_byte IS NULL)),
  CHECK((keyword_start_byte IS NULL) = (keyword_end_byte IS NULL))
) WITHOUT ROWID, STRICT;

CREATE TABLE "unit_children"(
  blob_id     INTEGER NOT NULL,
  lang        TEXT    NOT NULL,
  parent_key  INTEGER NOT NULL,
  child_key   INTEGER NOT NULL,
  ordinal     INTEGER NOT NULL,
  PRIMARY KEY(blob_id, parent_key, child_key, ordinal),
  CHECK(parent_key <> child_key),
  FOREIGN KEY(blob_id, parent_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, child_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_cpp_class_template_alias_components(
  blob_id INTEGER NOT NULL,
  unit_key INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  component TEXT NOT NULL,
  PRIMARY KEY(blob_id, unit_key, ordinal),
  FOREIGN KEY(blob_id, unit_key) REFERENCES unit_cpp_class_templates(blob_id, unit_key)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_cpp_class_template_expressions(
  blob_id INTEGER NOT NULL,
  expression_id INTEGER NOT NULL CHECK(expression_id >= 0),
  unit_key INTEGER NOT NULL,
  role INTEGER NOT NULL CHECK(role BETWEEN 0 AND 2),
  owner_ordinal INTEGER NOT NULL CHECK(owner_ordinal >= 0),
  text TEXT NOT NULL,
  root_term_id INTEGER NOT NULL CHECK(root_term_id >= 0),
  PRIMARY KEY(blob_id, expression_id),
  UNIQUE(blob_id, unit_key, role, owner_ordinal),
  FOREIGN KEY(blob_id, unit_key) REFERENCES unit_cpp_class_templates(blob_id, unit_key)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, expression_id, root_term_id)
    REFERENCES unit_cpp_class_template_terms(blob_id, expression_id, term_id)
    DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_cpp_class_template_parameters(
  blob_id INTEGER NOT NULL,
  unit_key INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  name TEXT NOT NULL,
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  variadic INTEGER NOT NULL CHECK(variadic IN (0, 1)),
  default_present INTEGER NOT NULL CHECK(default_present IN (0, 1)),
  PRIMARY KEY(blob_id, unit_key, ordinal),
  FOREIGN KEY(blob_id, unit_key) REFERENCES unit_cpp_class_templates(blob_id, unit_key)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_cpp_class_template_terms(
  blob_id INTEGER NOT NULL,
  term_id INTEGER NOT NULL CHECK(term_id >= 0),
  expression_id INTEGER NOT NULL CHECK(expression_id >= 0),
  parent_term_id INTEGER CHECK(parent_term_id >= 0 AND parent_term_id < term_id),
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
  text TEXT,
  atom_kind TEXT,
  PRIMARY KEY(blob_id, term_id),
  UNIQUE(blob_id, expression_id, term_id),
  UNIQUE(blob_id, expression_id, parent_term_id, ordinal),
  FOREIGN KEY(blob_id, expression_id) REFERENCES unit_cpp_class_template_expressions(blob_id, expression_id)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, expression_id, parent_term_id)
    REFERENCES unit_cpp_class_template_terms(blob_id, expression_id, term_id)
    DEFERRABLE INITIALLY DEFERRED,
  CHECK(parent_term_id IS NOT NULL OR ordinal = 0),
  CHECK((kind = 0 AND text IS NOT NULL AND atom_kind IS NULL)
     OR (kind = 1 AND text IS NOT NULL AND atom_kind IS NOT NULL)
     OR (kind = 2 AND text IS NULL AND atom_kind IS NOT NULL))
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_cpp_class_templates(
  blob_id INTEGER NOT NULL,
  fact_kind INTEGER NOT NULL DEFAULT 1 CHECK(fact_kind = 1),
  unit_key INTEGER NOT NULL,
  primary_name TEXT NOT NULL,
  primary_fq_name TEXT NOT NULL,
  alias_global INTEGER CHECK(alias_global IN (0, 1)),
  alias_arguments_present INTEGER CHECK(alias_arguments_present IN (0, 1)),
  parameter_count INTEGER NOT NULL CHECK(parameter_count >= 0),
  specialization_argument_count INTEGER NOT NULL CHECK(specialization_argument_count >= 0),
  alias_component_count INTEGER NOT NULL CHECK(alias_component_count >= 0),
  alias_argument_count INTEGER NOT NULL CHECK(alias_argument_count >= 0),
  PRIMARY KEY(blob_id, unit_key),
  FOREIGN KEY(blob_id, unit_key) REFERENCES code_units(blob_id, unit_key) ON DELETE CASCADE,
  FOREIGN KEY(blob_id, fact_kind) REFERENCES blob_optional_fact_manifest(blob_id, fact_kind)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  CHECK((alias_global IS NULL) = (alias_arguments_present IS NULL)),
  CHECK(alias_global IS NOT NULL OR (alias_component_count = 0 AND alias_argument_count = 0)),
  CHECK(alias_arguments_present IS NOT 0 OR alias_argument_count = 0)
) WITHOUT ROWID, STRICT;

CREATE TABLE "unit_ranges"(
  blob_id     INTEGER NOT NULL,
  lang        TEXT    NOT NULL,
  unit_key    INTEGER NOT NULL,
  ordinal     INTEGER NOT NULL,
  start_byte  INTEGER NOT NULL,
  end_byte    INTEGER NOT NULL,
  start_line  INTEGER NOT NULL,
  end_line    INTEGER NOT NULL,
  PRIMARY KEY(blob_id, unit_key, ordinal),
  CHECK(start_byte >= 0 AND end_byte >= start_byte AND start_line >= 0 AND end_line >= start_line),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "unit_signature_metadata"(
  blob_id                             INTEGER NOT NULL,
  lang                                TEXT    NOT NULL,
  unit_key                            INTEGER NOT NULL,
  ordinal                             INTEGER NOT NULL,
  label                               TEXT    NOT NULL
    CHECK(length(CAST(label AS BLOB)) <= 8388608),
  parameters                          TEXT    NOT NULL DEFAULT '[]'
    CHECK(json_valid(parameters) AND length(CAST(parameters AS BLOB)) <= 8388608),
  return_type_text                    TEXT
    CHECK(return_type_text IS NULL
          OR length(CAST(return_type_text AS BLOB)) <= 8388608),
  return_type_identity                TEXT
    CHECK(return_type_identity IS NULL
          OR (json_valid(return_type_identity)
              AND length(CAST(return_type_identity AS BLOB)) <= 8388608)),
  underlying_type_identity            TEXT
    CHECK(underlying_type_identity IS NULL
          OR (json_valid(underlying_type_identity)
              AND length(CAST(underlying_type_identity AS BLOB)) <= 8388608)),
  declaration_only                    INTEGER NOT NULL DEFAULT 0
    CHECK(declaration_only IN (0, 1)),
  callable_arity_required             INTEGER CHECK(callable_arity_required >= 0),
  callable_arity_total                INTEGER CHECK(callable_arity_total >= 0),
  callable_arity_repeated             INTEGER CHECK(callable_arity_repeated IN (0, 1)),
  type_parameters                     TEXT    NOT NULL DEFAULT '[]'
    CHECK(json_valid(type_parameters)
          AND length(CAST(type_parameters AS BLOB)) <= 8388608),
  bare_return_type_parameter          TEXT
    CHECK(bare_return_type_parameter IS NULL
          OR length(CAST(bare_return_type_parameter AS BLOB)) <= 8388608),
  callable_linkage                    TEXT
    CHECK(callable_linkage IS NULL
          OR callable_linkage IN ('external', 'internal')),
  dispatch_extensibility              TEXT
    CHECK(dispatch_extensibility IS NULL
          OR dispatch_extensibility IN ('open', 'closed')),
  extension_receiver_type             TEXT
    CHECK(extension_receiver_type IS NULL
          OR length(CAST(extension_receiver_type AS BLOB)) <= 8388608),
  extension_receiver_type_identity    TEXT
    CHECK(extension_receiver_type_identity IS NULL
          OR (json_valid(extension_receiver_type_identity)
              AND length(CAST(extension_receiver_type_identity AS BLOB)) <= 8388608)),
  extension_receiver_is_unconstrained INTEGER NOT NULL DEFAULT 0
    CHECK(extension_receiver_is_unconstrained IN (0, 1)),
  field_is_static                     INTEGER NOT NULL DEFAULT 0
    CHECK(field_is_static IN (0, 1)),
  field_is_final                      INTEGER NOT NULL DEFAULT 0
    CHECK(field_is_final IN (0, 1)),
  field_has_initializer               INTEGER NOT NULL DEFAULT 0
    CHECK(field_has_initializer IN (0, 1)),
  cpp_field_linkage                   TEXT
    CHECK(cpp_field_linkage IS NULL
          OR cpp_field_linkage IN ('external', 'internal',
                                   'internal_unless_external_peer')),
  companion_object                    INTEGER NOT NULL DEFAULT 0
    CHECK(companion_object IN (0, 1)),
  callable_is_static                  INTEGER NOT NULL DEFAULT 0
    CHECK(callable_is_static IN (0, 1)),
  callable_is_constructor             INTEGER NOT NULL DEFAULT 0
    CHECK(callable_is_constructor IN (0, 1)),
  callable_declared_visibility        TEXT
    CHECK(callable_declared_visibility IS NULL
          OR callable_declared_visibility IN ('public', 'protected', 'internal',
                                              'package_private', 'private',
                                              'crate_or_module', 'unknown')),
  callable_modifiers_recorded         INTEGER NOT NULL DEFAULT 0
    CHECK(callable_modifiers_recorded IN (0, 1)),
  callable_parameter_types            TEXT
    CHECK(callable_parameter_types IS NULL
          OR (json_valid(callable_parameter_types)
              AND length(CAST(callable_parameter_types AS BLOB)) <= 8388608)),
  callable_is_native                  INTEGER NOT NULL DEFAULT 0
    CHECK(callable_is_native IN (0, 1)),
  class_like_is_interface             INTEGER NOT NULL DEFAULT 0
    CHECK(class_like_is_interface IN (0, 1)),
  class_like_is_static                INTEGER NOT NULL DEFAULT 0
    CHECK(class_like_is_static IN (0, 1)), type_parameters_recorded INTEGER NOT NULL DEFAULT 0
    CHECK(type_parameters_recorded IN (0, 1)), result_type_identities TEXT NOT NULL DEFAULT '[]'
    CHECK(json_valid(result_type_identities)
          AND length(CAST(result_type_identities AS BLOB)) <= 8388608), parameter_type_identities TEXT NOT NULL DEFAULT '[]'
    CHECK(json_valid(parameter_type_identities)
          AND length(CAST(parameter_type_identities AS BLOB)) <= 8388608), callable_override_modifier TEXT DEFAULT NULL
    CHECK(callable_override_modifier IS NULL
          OR callable_override_modifier IN
             ('not_declared', 'virtual', 'abstract', 'override', 'hiding')), java_constructor_shape INTEGER
  CHECK(java_constructor_shape IS NULL OR java_constructor_shape IN (0, 1, 2)), java_constructor_arity_required INTEGER
  CHECK(java_constructor_arity_required IS NULL OR java_constructor_arity_required >= 0), java_constructor_arity_total INTEGER
  CHECK(java_constructor_arity_total IS NULL OR java_constructor_arity_total >= 0), java_constructor_arity_repeated INTEGER
  CHECK(
    ((java_constructor_shape IS NULL OR java_constructor_shape IN (0, 1))
      AND java_constructor_arity_required IS NULL
      AND java_constructor_arity_total IS NULL
      AND java_constructor_arity_repeated IS NULL)
    OR (java_constructor_shape IS NOT NULL AND java_constructor_shape = 2
      AND java_constructor_arity_required IS NOT NULL
      AND java_constructor_arity_total IS NOT NULL
      AND java_constructor_arity_repeated IS NOT NULL
      AND java_constructor_arity_required <= java_constructor_arity_total
      AND java_constructor_arity_repeated IN (0, 1))
  ), parameter_count INTEGER
  CHECK(parameter_count IS NULL OR parameter_count >= 0), class_like_kind TEXT
  CHECK(class_like_kind IS NULL OR class_like_kind IN ('class', 'interface', 'struct', 'enum')),
  CHECK((callable_arity_required IS NULL) = (callable_arity_total IS NULL)),
  CHECK((callable_arity_required IS NULL) = (callable_arity_repeated IS NULL)),
  CHECK(callable_arity_required IS NULL
        OR callable_arity_required <= callable_arity_total),
  PRIMARY KEY(blob_id, unit_key, ordinal),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_signature_metadata_signatures(
  blob_id          INTEGER NOT NULL,
  fact_kind        INTEGER NOT NULL DEFAULT 6 CHECK(fact_kind = 6),
  unit_key         INTEGER NOT NULL,
  metadata_ordinal INTEGER NOT NULL CHECK(metadata_ordinal >= 0),
  signature_ordinal INTEGER NOT NULL CHECK(signature_ordinal >= 0),
  PRIMARY KEY(blob_id, unit_key, metadata_ordinal),
  FOREIGN KEY(blob_id, unit_key, metadata_ordinal)
    REFERENCES unit_signature_metadata(blob_id, unit_key, ordinal)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, unit_key, signature_ordinal)
    REFERENCES unit_signatures(blob_id, unit_key, ordinal)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY(blob_id, fact_kind)
    REFERENCES blob_optional_fact_manifest(blob_id, fact_kind)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID, STRICT;

CREATE TABLE unit_signature_parameters(
  blob_id INTEGER NOT NULL,
  unit_key INTEGER NOT NULL,
  metadata_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  label TEXT NOT NULL CHECK(length(CAST(label AS BLOB)) <= 8388608),
  name TEXT CHECK(name IS NULL OR length(CAST(name AS BLOB)) <= 8388608),
  start_byte INTEGER NOT NULL CHECK(start_byte >= 0),
  end_byte INTEGER NOT NULL CHECK(end_byte >= start_byte),
  PRIMARY KEY(blob_id, unit_key, metadata_ordinal, ordinal),
  FOREIGN KEY(blob_id, unit_key, metadata_ordinal)
    REFERENCES unit_signature_metadata(blob_id, unit_key, ordinal) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE "unit_signatures"(
  blob_id     INTEGER NOT NULL,
  lang        TEXT    NOT NULL,
  unit_key    INTEGER NOT NULL,
  ordinal     INTEGER NOT NULL,
  text        TEXT    NOT NULL,
  PRIMARY KEY(blob_id, unit_key, ordinal),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE "unit_supertypes"(
  blob_id     INTEGER NOT NULL,
  lang        TEXT    NOT NULL,
  unit_key    INTEGER NOT NULL,
  ordinal     INTEGER NOT NULL,
  raw         TEXT    NOT NULL,
  lookup_path TEXT    NOT NULL DEFAULT '',
  PRIMARY KEY(blob_id, unit_key, ordinal),
  FOREIGN KEY(blob_id, unit_key)
    REFERENCES "code_units"(blob_id, unit_key) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_file_anchor_rows(
  file_version_id  INTEGER NOT NULL,
  anchor_kind      TEXT    NOT NULL CHECK(anchor_kind IN ('own_module', 'crate_root')),
  anchor_pop       INTEGER NOT NULL CHECK(anchor_pop BETWEEN 0 AND 255),
  package_name     TEXT    NOT NULL,
  PRIMARY KEY(file_version_id, anchor_kind, anchor_pop),
  CHECK(anchor_kind <> 'crate_root' OR anchor_pop = 0),
  FOREIGN KEY(file_version_id) REFERENCES workspace_file_versions(file_version_id)
    ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_file_package_edge_rows(
  file_version_id      INTEGER NOT NULL,
  parent_package_name  TEXT    NOT NULL,
  child_package_name   TEXT    NOT NULL,
  PRIMARY KEY(file_version_id, parent_package_name, child_package_name),
  CHECK(parent_package_name <> child_package_name),
  FOREIGN KEY(file_version_id) REFERENCES workspace_file_versions(file_version_id)
    ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_file_package_rows(
  file_version_id  INTEGER NOT NULL,
  package_name     TEXT    NOT NULL,
  PRIMARY KEY(file_version_id, package_name),
  FOREIGN KEY(file_version_id) REFERENCES workspace_file_versions(file_version_id)
    ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_file_path_symbol_rows(
  file_version_id  INTEGER NOT NULL,
  kind             INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 5),
  package_name     TEXT    NOT NULL,
  short_name       TEXT    NOT NULL,
  exact_fqn        TEXT    NOT NULL,
  normalized_fqn   TEXT    NOT NULL, requires_imports INTEGER NOT NULL DEFAULT 0
    CHECK(requires_imports IN (0, 1)),
  PRIMARY KEY(file_version_id, kind, exact_fqn),
  FOREIGN KEY(file_version_id) REFERENCES workspace_file_versions(file_version_id)
    ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_file_versions(
  file_version_id   INTEGER PRIMARY KEY,
  workspace_id      TEXT    NOT NULL,
  lang              TEXT    NOT NULL,
  generation        INTEGER NOT NULL,
  rel_path          TEXT    NOT NULL CHECK(length(rel_path) > 0),
  blob_oid          TEXT    NOT NULL
    CHECK(length(blob_oid) = 40 AND blob_oid NOT GLOB '*[^0-9a-f]*'),
  input_kind TEXT NOT NULL DEFAULT 'source' CHECK(input_kind IN ('source', 'configuration')),
  projection_digest TEXT
    CHECK(length(projection_digest) = 64 AND projection_digest NOT GLOB '*[^0-9a-f]*'),
  valid_from         INTEGER NOT NULL CHECK(valid_from > 0),
  valid_until        INTEGER CHECK(valid_until IS NULL OR valid_until > valid_from),
  CHECK((input_kind = 'source' AND projection_digest IS NOT NULL)
     OR (input_kind = 'configuration' AND projection_digest IS NULL)),
  UNIQUE(workspace_id, lang, generation, input_kind, rel_path, valid_from),
  FOREIGN KEY(workspace_id, lang, generation, valid_from)
    REFERENCES workspace_revisions(workspace_id, lang, generation, revision)
      ON DELETE CASCADE
) STRICT;

CREATE TABLE workspace_heads(
  workspace_id  TEXT    NOT NULL,
  lang          TEXT    NOT NULL,
  generation    INTEGER NOT NULL,
  revision      INTEGER NOT NULL,
  PRIMARY KEY(workspace_id, lang, generation),
  FOREIGN KEY(workspace_id, lang, generation, revision)
    REFERENCES workspace_revisions(workspace_id, lang, generation, revision)
) WITHOUT ROWID, STRICT;

CREATE TABLE "workspace_input_sources"(
  content_oid TEXT PRIMARY KEY
    CHECK(length(content_oid) = 40 AND content_oid NOT GLOB '*[^0-9a-f]*'),
  source_bytes BLOB NOT NULL
    CHECK(typeof(source_bytes) = 'blob')
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_revisions(
  workspace_id  TEXT    NOT NULL
    CHECK(length(workspace_id) = 64 AND workspace_id NOT GLOB '*[^0-9a-f]*'),
  lang          TEXT    NOT NULL,
  generation    INTEGER NOT NULL CHECK(generation >= 0),
  revision      INTEGER NOT NULL CHECK(revision > 0),
  PRIMARY KEY(workspace_id, lang, generation, revision)
) WITHOUT ROWID, STRICT;

CREATE INDEX class_set_field_slot_indexes_recent
  ON class_set_field_slot_indexes(lang, published_at DESC, index_id DESC);

CREATE INDEX class_set_finding_free_root_results_owner_blob
  ON class_set_finding_free_root_results(owner_blob_id, lang);

CREATE INDEX class_set_procedure_surfaces_exact_family
  ON class_set_procedure_surfaces(
    procedure_lineage, owner_rel_path, lang, schema_version,
    local_structure_digest, behavior_read_digest, surface_digest
  );

CREATE INDEX class_set_procedure_surfaces_owner_blob
  ON class_set_procedure_surfaces(owner_blob_id, lang);

CREATE INDEX class_set_root_result_generations_recent
  ON class_set_root_result_generations(lang, published_at DESC, generation_id DESC);

CREATE INDEX class_set_summaries_exact_family
  ON class_set_summaries(
    procedure_lineage, owner_rel_path, lang, schema_version, semantics_digest,
    context_digest, behavior_read_digest, carrier_digest, field_slots_digest,
    root_surface_digest, lookup_digest
  );

CREATE INDEX class_set_summaries_lineage
  ON class_set_summaries(procedure_lineage);

CREATE UNIQUE INDEX class_set_summaries_lookup
  ON class_set_summaries(lookup_digest);

CREATE INDEX class_set_summaries_owner_blob
  ON class_set_summaries(owner_blob_id, lang);

CREATE INDEX class_set_summaries_root_surface
  ON class_set_summaries(root_surface_digest);

CREATE INDEX class_set_summary_dependencies_child_lookup
  ON class_set_summary_dependencies(consumed_child_lookup_digest, summary_id);

CREATE INDEX class_set_summary_dependencies_lineage_entry
  ON class_set_summary_dependencies(
    callee_procedure_lineage, callee_entry_selector_digest, summary_id
  );

CREATE INDEX class_set_summary_reads_by_key
  ON class_set_summary_reads(key_digest, summary_id);

CREATE INDEX idx_blobs_lang_generation
  ON blobs(lang, generation, blob_oid);

CREATE INDEX idx_code_units_anchored_blob_exact_tail
  ON code_units(
    blob_id, lang, fq_anchor_kind, fq_anchor_pop, exact_fqn_tail, unit_key
  )
  WHERE fq_anchor_kind IS NOT NULL
    AND exact_fqn_tail IS NOT NULL
