CREATE INDEX source_rust_module_inventory_fk_parent_scope_ordinal
  ON source_rust_module_inventory(parent_scope_ordinal);

CREATE INDEX source_rust_module_route_gates_fk_invocation_occurrence_id
  ON source_rust_module_route_gates(invocation_occurrence_id);

CREATE INDEX source_rust_module_routes_fk_scope_ordinal
  ON source_rust_module_routes(scope_ordinal);

CREATE INDEX source_rust_module_scopes_fk_parent_ordinal
  ON source_rust_module_scopes(parent_ordinal);

CREATE INDEX source_rust_trait_items_fk_context_occurrence_id
  ON source_rust_trait_items(context_occurrence_id);

CREATE INDEX source_rust_type_children_fk_occurrence_id
  ON source_rust_type_children(occurrence_id);

CREATE INDEX source_rust_value_items_fk_context_occurrence_id
  ON source_rust_value_items(context_occurrence_id);

CREATE INDEX source_rust_value_items_fk_declared_type_occurrence_id
  ON source_rust_value_items(declared_type_occurrence_id);

CREATE INDEX source_scala_callable_parameters_fk_type_expression_id
  ON source_scala_callable_parameters(type_expression_id);

CREATE INDEX source_scala_callables_fk_return_expression_id
  ON source_scala_callables(return_expression_id);

CREATE INDEX source_scala_generic_supertypes_fk_expression_id
  ON source_scala_generic_supertypes(expression_id);

CREATE INDEX source_scala_type_expression_arguments_fk_child_id
  ON source_scala_type_expression_arguments(child_id);

CREATE VIEW live_code_units AS
SELECT units.*, live.blob_oid
FROM code_units AS units
JOIN live_parsed_blobs AS live
  ON live.blob_id = units.blob_id;

CREATE VIEW live_declarations AS
SELECT * FROM live_code_units WHERE in_declarations = 1;

CREATE VIEW live_definition_units AS
SELECT * FROM live_code_units
WHERE in_declarations = 1 OR in_definition_lookup = 1;

CREATE VIEW live_parsed_blobs AS
SELECT blobs.id AS blob_id,
       blobs.blob_oid,
       blobs.lang,
       blobs.generation,
       blob_meta.content_package
FROM blobs
JOIN blob_meta ON blob_meta.blob_id = blobs.id
JOIN source_declaration_visibility_readiness AS readiness
  ON readiness.blob_id = blob_meta.blob_id AND readiness.available = 1
LEFT JOIN analysis_epochs
  ON analysis_epochs.lang = blobs.lang
WHERE blob_meta.is_complete = 1
  AND blobs.generation = COALESCE(analysis_epochs.generation, 0);

CREATE VIEW resolution_declaration_visibility_properties AS
SELECT legacy.blob_id, legacy.definition_semantic_key, legacy.visibility
FROM legacy_resolution_declaration_visibility_properties AS legacy
LEFT JOIN blob_meta AS meta ON meta.blob_id = legacy.blob_id
WHERE (meta.blob_id IS NULL OR meta.declaration_visibility_version IS NULL)
  AND NOT EXISTS (
    SELECT 1 FROM source_declaration_visibility_manifests AS marker
    WHERE marker.blob_id = legacy.blob_id
  )
UNION ALL
SELECT site.blob_id, site.semantic_key, visibility.visibility
FROM resolution_semantic_sites AS site
JOIN source_native_declaration_bridges AS native
  ON native.blob_id = site.blob_id AND native.source_site = site.source_site
JOIN source_declaration_visibilities AS visibility
  ON visibility.blob_id = native.blob_id
 AND visibility.declaration_id = native.declaration_id
JOIN blob_meta AS meta ON meta.blob_id = site.blob_id
JOIN source_declaration_visibility_readiness AS readiness
  ON readiness.blob_id = site.blob_id AND readiness.available = 1
WHERE meta.declaration_visibility_version IS NOT NULL
  AND site.semantic_role = 'definition';

CREATE VIEW rust_item_macros AS
SELECT macro.blob_id, macro.lang, macro.ordinal, macro.macro_name,
       declaration.end_byte AS visible_after,
       context.start_byte AS scope_start,
       context.end_byte AS scope_end,
       macro.passthrough,
       property.macro_exported AS exported,
       macro.declaration_id,
       macro.arguments_only,
       macro.decoration_cfg,
       macro.declares_no_item,
       macro.writes_only_impls
FROM source_rust_item_macros AS macro
LEFT JOIN source_declarations AS declaration
  ON declaration.blob_id = macro.blob_id
 AND declaration.declaration_id = macro.declaration_id
LEFT JOIN source_rust_macro_definitions AS definition
  ON definition.blob_id = macro.blob_id
 AND definition.declaration_id = macro.declaration_id
LEFT JOIN source_rust_item_contexts AS context
  ON context.blob_id = definition.blob_id
 AND context.occurrence_id = definition.context_occurrence_id
LEFT JOIN source_rust_declaration_properties AS property
  ON property.blob_id = macro.blob_id
 AND property.declaration_id = macro.declaration_id;

CREATE VIEW rust_module_route_gates AS
SELECT gate.blob_id, 'rust' AS lang, gate.route_ordinal, gate.gate_ordinal,
       invocation.macro_name, invocation.start_byte AS invocation_start
FROM source_rust_module_manifests AS manifest
JOIN source_fact_manifests AS source_facts
  ON source_facts.blob_id = manifest.blob_id
 AND source_facts.publication_state = 'complete'
JOIN source_rust_module_route_gates AS gate
  ON gate.blob_id = manifest.blob_id
JOIN source_rust_macro_invocations AS invocation
  ON invocation.blob_id = gate.blob_id
 AND invocation.occurrence_id = gate.invocation_occurrence_id
WHERE manifest.facts_version = 1;

CREATE VIEW rust_module_routes AS
SELECT route.blob_id, 'rust' AS lang, route.ordinal, route.scope_ordinal,
       declaration.module_name, declaration.path_attribute, property.visibility,
       route.imports_macros, declaration.test_gated, property.cfg_condition,
       source.start_byte AS declaration_start,
       source.end_byte AS declaration_end
FROM source_rust_module_manifests AS manifest
JOIN source_fact_manifests AS source_facts
  ON source_facts.blob_id = manifest.blob_id
 AND source_facts.publication_state = 'complete'
JOIN source_rust_module_routes AS route
  ON route.blob_id = manifest.blob_id
JOIN source_rust_module_declarations AS declaration
  ON declaration.blob_id = route.blob_id
 AND declaration.declaration_id = route.declaration_id
JOIN source_rust_declaration_properties AS property
  ON property.blob_id = declaration.blob_id
 AND property.declaration_id = declaration.declaration_id
JOIN source_declarations AS source
  ON source.blob_id = declaration.blob_id
 AND source.declaration_id = declaration.declaration_id
WHERE manifest.facts_version = 1;

CREATE VIEW rust_module_scopes AS
SELECT scope.blob_id, 'rust' AS lang, scope.ordinal, scope.parent_ordinal,
       CASE WHEN scope.ordinal = 0 THEN '' ELSE declaration.module_name END AS module_name,
       CASE WHEN scope.ordinal = 0 THEN NULL ELSE declaration.path_attribute END AS path_attribute,
       CASE WHEN scope.ordinal = 0 THEN 'private' ELSE property.visibility END AS visibility,
       scope.imports_macros, scope.resolution_scope,
       CASE WHEN scope.ordinal = 0 THEN manifest.root_start_byte ELSE declaration.body_start_byte END AS body_start,
       CASE WHEN scope.ordinal = 0 THEN manifest.root_end_byte ELSE declaration.body_end_byte END AS body_end
FROM source_rust_module_manifests AS manifest
JOIN source_fact_manifests AS source_facts
  ON source_facts.blob_id = manifest.blob_id
 AND source_facts.publication_state = 'complete'
JOIN source_rust_module_scopes AS scope
  ON scope.blob_id = manifest.blob_id
LEFT JOIN source_rust_module_declarations AS declaration
  ON declaration.blob_id = scope.blob_id
 AND declaration.declaration_id = scope.declaration_id
LEFT JOIN source_rust_declaration_properties AS property
  ON property.blob_id = declaration.blob_id
 AND property.declaration_id = declaration.declaration_id
WHERE manifest.facts_version = 1;

CREATE VIEW rust_modules AS
SELECT item.blob_id, 'rust' AS lang, item.ordinal, item.module_name,
       CASE WHEN item.ordinal = 0 THEN 1 ELSE property.declaration_kind = 4 END AS is_inline,
       CASE WHEN item.ordinal = 0 THEN manifest.root_start_byte
            WHEN declaration.body_occurrence_id IS NULL THEN source.start_byte
            ELSE declaration.body_start_byte END AS start_byte,
       CASE WHEN item.ordinal = 0 THEN manifest.root_end_byte
            WHEN declaration.body_occurrence_id IS NULL THEN source.end_byte
            ELSE declaration.body_end_byte END AS end_byte,
       CASE WHEN item.ordinal = 0 THEN 'always' ELSE property.cfg_condition END AS cfg_condition
FROM source_rust_module_manifests AS manifest
JOIN source_fact_manifests AS source_facts
  ON source_facts.blob_id = manifest.blob_id
 AND source_facts.publication_state = 'complete'
JOIN source_rust_module_inventory AS item
  ON item.blob_id = manifest.blob_id
LEFT JOIN source_rust_module_declarations AS declaration
  ON declaration.blob_id = item.blob_id
 AND declaration.declaration_id = item.declaration_id
LEFT JOIN source_rust_declaration_properties AS property
  ON property.blob_id = declaration.blob_id
 AND property.declaration_id = declaration.declaration_id
LEFT JOIN source_declarations AS source
  ON source.blob_id = declaration.blob_id
 AND source.declaration_id = declaration.declaration_id
WHERE manifest.facts_version = 1;

CREATE VIEW rust_published_fact_blobs AS
SELECT keys.id AS blob_id, keys.blob_oid, keys.lang, keys.generation
FROM blobs AS keys
JOIN blob_meta AS meta
  ON meta.blob_id = keys.id
 AND meta.lang = keys.lang
 AND meta.is_complete = 1
JOIN source_declaration_visibility_readiness AS readiness
  ON readiness.blob_id = keys.id AND readiness.available = 1
JOIN source_fact_manifests AS source
  ON source.blob_id = keys.id
 AND source.publication_state = 'complete'
JOIN source_rust_module_manifests AS module
  ON module.blob_id = keys.id
 AND module.facts_version = 1
JOIN source_rust_item_manifests AS item
  ON item.blob_id = keys.id
 AND item.facts_version = 1
 AND item.macro_facts_version = 1
 AND item.type_forms_version = 1
 AND item.macro_contexts_version = 1
JOIN source_rust_module_scopes AS scope
  ON scope.blob_id = module.blob_id AND scope.ordinal = 0
JOIN source_rust_module_inventory AS inventory
  ON inventory.blob_id = module.blob_id AND inventory.ordinal = 0
WHERE keys.lang = 'rust';

CREATE VIEW source_cpp_fact_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_cpp_declaration_contexts WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_flattened_namespaces WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_guard_sets WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_guard_nodes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_guard_edges WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_guard_roots WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_includes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_using_namespaces WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_declarations WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_callable_shapes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_comparable_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_comparable_nodes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_comparable_node_names WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_comparable_node_arguments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_declaration_paths WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_alias_components WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_member_usings WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_member_using_scopes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_bases WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_base_components WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_template_expressions WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_cpp_template_terms WHERE blob_id = blob.id) AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(path AS BLOB))) FROM source_cpp_includes WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(namespace AS BLOB))) FROM source_cpp_using_namespaces WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(COALESCE(length(CAST(field_type_text AS BLOB)), 0)
                          + COALESCE(length(CAST(alias_target_text AS BLOB)), 0)
                          + length(CAST(trailing_qualifiers AS BLOB))
                          + COALESCE(length(CAST(callable_identity_suffix AS BLOB)), 0))
                   FROM source_cpp_declarations WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component AS BLOB))) FROM source_cpp_declaration_paths WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component AS BLOB))) FROM source_cpp_alias_components WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(member AS BLOB))) FROM source_cpp_member_usings WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component AS BLOB))) FROM source_cpp_member_using_scopes WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component AS BLOB))) FROM source_cpp_base_components WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_cpp_comparable_node_names WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(text AS BLOB))) FROM source_cpp_template_expressions WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(COALESCE(length(CAST(text AS BLOB)), 0)
                          + COALESCE(length(CAST(atom_kind AS BLOB)), 0))
                   FROM source_cpp_template_terms WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(COALESCE(length(CAST(file_alias_name AS BLOB)), 0)
           + COALESCE(length(CAST(file_alias_target AS BLOB)), 0)
           + COALESCE(length(CAST(file_alias_namespace AS BLOB)), 0))
           FROM source_cpp_declaration_contexts WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component AS BLOB))) FROM source_cpp_flattened_namespaces WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(text AS BLOB))) FROM source_cpp_guard_nodes WHERE blob_id = blob.id), 0) AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_declaration_visibility_readiness AS
SELECT meta.blob_id,
       CASE
         WHEN meta.source_facts_version IS NOT NULL
          AND (source.blob_id IS NULL OR source.facts_version <> meta.source_facts_version
               OR source.publication_state <> 'complete') THEN 0
         WHEN meta.metadata_bridges_required = 1 AND source.metadata_bridge_count IS NULL THEN 0
         WHEN meta.native_bridges_required = 1 AND source.native_bridge_count IS NULL THEN 0
         WHEN meta.declaration_visibility_version IS NULL
          AND marker.blob_id IS NULL THEN 1
         WHEN source.blob_id IS NOT NULL
          AND source.publication_state = 'complete'
          AND marker.blob_id IS NOT NULL
          AND marker.facts_version = meta.declaration_visibility_version
         THEN 1
         ELSE 0
       END AS available
FROM blob_meta AS meta
LEFT JOIN source_fact_manifests AS source ON source.blob_id = meta.blob_id
LEFT JOIN source_declaration_visibility_manifests AS marker ON marker.blob_id = meta.blob_id;

CREATE VIEW source_fact_readiness AS
SELECT visibility.blob_id,
       CASE WHEN visibility.available = 1 AND (
         (meta.go_source_version IS NULL AND go_marker.blob_id IS NULL)
         OR (meta.go_source_version = go_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.java_source_version IS NULL AND java_marker.blob_id IS NULL)
         OR (meta.java_source_version = java_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.ruby_source_version IS NULL AND ruby_marker.blob_id IS NULL)
         OR (meta.ruby_source_version = ruby_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.php_source_version IS NULL AND php_marker.blob_id IS NULL)
         OR (meta.php_source_version = php_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.scala_source_version IS NULL AND scala_marker.blob_id IS NULL)
         OR (meta.scala_source_version = scala_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.cpp_source_version IS NULL AND cpp_marker.blob_id IS NULL)
         OR (meta.cpp_source_version = cpp_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.js_ts_source_version IS NULL AND js_ts_marker.blob_id IS NULL)
         OR (meta.js_ts_source_version = js_ts_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         (meta.python_source_version IS NULL AND python_marker.blob_id IS NULL)
         OR (meta.python_source_version = python_marker.facts_version AND source.publication_state = 'complete')
       ) AND (
         meta.lang <> 'rust'
         OR (
           source.publication_state = 'complete'
           AND rust_module.facts_version = 1
           AND rust_item.facts_version = 1
           AND rust_item.macro_facts_version = 1
           AND rust_item.type_forms_version = 1
           AND rust_item.macro_contexts_version = 1
         )
       ) THEN 1 ELSE 0 END AS available
FROM source_declaration_visibility_readiness AS visibility
JOIN blob_meta AS meta ON meta.blob_id = visibility.blob_id
LEFT JOIN source_fact_manifests AS source ON source.blob_id = meta.blob_id
LEFT JOIN source_go_manifests AS go_marker ON go_marker.blob_id = meta.blob_id
LEFT JOIN source_java_declaration_manifests AS java_marker ON java_marker.blob_id = meta.blob_id
LEFT JOIN source_ruby_manifests AS ruby_marker ON ruby_marker.blob_id = meta.blob_id
LEFT JOIN source_php_manifests AS php_marker ON php_marker.blob_id = meta.blob_id
LEFT JOIN source_scala_declaration_manifests AS scala_marker ON scala_marker.blob_id = meta.blob_id
LEFT JOIN source_cpp_manifests AS cpp_marker ON cpp_marker.blob_id = meta.blob_id
LEFT JOIN source_js_ts_manifests AS js_ts_marker ON js_ts_marker.blob_id = meta.blob_id
LEFT JOIN source_python_manifests AS python_marker ON python_marker.blob_id = meta.blob_id
LEFT JOIN source_rust_module_manifests AS rust_module ON rust_module.blob_id = meta.blob_id
LEFT JOIN source_rust_item_manifests AS rust_item ON rust_item.blob_id = meta.blob_id;

CREATE VIEW source_go_fact_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_go_types WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_type_names WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_type_children WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_type_declarations WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_aliases WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_fields WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_callables WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_callable_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_go_embeddings WHERE blob_id = blob.id) AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(text AS BLOB))) FROM source_go_types WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_go_type_names WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_go_type_declarations WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_go_aliases WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_go_fields WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_go_callables WHERE blob_id = blob.id), 0) AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_import_lexical_prefixes AS
SELECT import.blob_id, import.lang, import.ordinal,
       prefix.ordinal AS prefix_ordinal, prefix.prefix
FROM import_statements AS import
JOIN source_import_prefixes AS prefix
  ON prefix.blob_id = import.blob_id AND prefix.import_id = import.source_import_id
WHERE import.source_import_id IS NOT NULL;

CREATE VIEW source_import_lexical_scopes AS
SELECT import.blob_id, import.lang, import.ordinal, scope.ordinal AS scope_ordinal,
       scope.start_byte, scope.end_byte, scope.occurrence_id
FROM import_statements AS import
JOIN source_import_scopes AS scope
  ON scope.blob_id = import.blob_id AND scope.import_id = import.source_import_id
WHERE import.source_import_id IS NOT NULL;

CREATE VIEW source_import_path_segments AS
SELECT import.blob_id, import.lang, import.ordinal, segment.ordinal AS seg_ordinal, segment.segment
FROM import_statements AS import
JOIN source_import_segments AS segment
  ON segment.blob_id = import.blob_id AND segment.import_id = import.source_import_id
WHERE import.source_import_id IS NOT NULL;

CREATE VIEW source_import_statements AS
SELECT import.blob_id, import.lang, import.ordinal,
       CASE WHEN import.source_import_id IS NULL THEN import.statement
            ELSE (SELECT source.statement FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS statement,
       CASE WHEN import.source_import_id IS NULL THEN import.is_wildcard
            ELSE (SELECT source.is_wildcard FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS is_wildcard,
       CASE WHEN import.source_import_id IS NULL THEN import.is_global
            ELSE (SELECT source.is_global FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS is_global,
       CASE WHEN import.source_import_id IS NULL THEN import.identifier
            ELSE (SELECT source.identifier FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS identifier,
       CASE WHEN import.source_import_id IS NULL THEN import.alias
            ELSE (SELECT source.alias FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS alias,
       CASE WHEN import.source_import_id IS NULL THEN import.path_kind
            ELSE (SELECT source.path_kind FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS path_kind,
       CASE WHEN import.source_import_id IS NOT NULL THEN
              (SELECT source.declaration_start_byte FROM source_imports AS source
               WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id)
            ELSE import.declaration_start_byte END AS declaration_start_byte,
       CASE WHEN import.source_import_id IS NOT NULL THEN
              (SELECT COALESCE(source.alias_start_byte, source.target_start_byte) FROM source_imports AS source
               WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id)
            ELSE import.binder_start END AS binder_start,
       CASE WHEN import.source_import_id IS NOT NULL THEN
              (SELECT COALESCE(source.alias_end_byte, source.target_end_byte) FROM source_imports AS source
               WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id)
            ELSE import.binder_end END AS binder_end,
       CASE WHEN import.source_import_id IS NULL THEN import.declaration_occurrence_id
            ELSE (SELECT source.declaration_occurrence_id FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS declaration_occurrence_id,
       CASE WHEN import.source_import_id IS NULL THEN import.binder_occurrence_id
            ELSE (SELECT COALESCE(source.alias_occurrence_id, source.target_occurrence_id) FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END AS binder_occurrence_id,
       CASE WHEN import.source_import_id IS NULL THEN
              CASE WHEN import.declaration_start_byte IS NOT NULL
                         OR import.declaration_occurrence_id IS NOT NULL
                   THEN 1 ELSE 0 END
            ELSE (SELECT source.has_structured_path FROM source_imports AS source
                  WHERE source.blob_id = import.blob_id AND source.import_id = import.source_import_id) END
         AS has_structured_path
FROM import_statements AS import;

CREATE VIEW source_java_declaration_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_java_types WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_type_names WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_type_arguments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_type_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_type_bounds WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_callable_returns WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_local_types WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_anonymous_returns WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_anonymous_return_entries WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_java_declaration_owners WHERE blob_id = blob.id) AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_java_type_names WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_java_type_parameters WHERE blob_id = blob.id), 0) AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_js_ts_fact_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_js_ts_bindings WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_exports WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_declarations WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_types WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_type_names WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_type_children WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_type_members WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_type_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_declaration_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_component_members WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_declaration_bindings WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_property_receivers WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_js_ts_property_receiver_members WHERE blob_id = blob.id) AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(name AS BLOB))
                         + COALESCE(length(CAST(local_name AS BLOB)), 0))
                   FROM source_js_ts_exports WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_js_ts_type_names WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_js_ts_type_members WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_js_ts_component_members WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(component_name AS BLOB)))
                   FROM source_js_ts_declarations WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_js_ts_declaration_bindings WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(receiver_root AS BLOB)))
                   FROM source_js_ts_property_receivers WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_js_ts_property_receiver_members WHERE blob_id = blob.id), 0)
       AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_occurrences AS
SELECT arena.blob_id,
       CAST(entry.key AS INTEGER) AS occurrence_id,
       json_extract(CASE WHEN entry.type = 'array' THEN entry.value ELSE '[]' END, '$[0]') AS start_byte,
       json_extract(CASE WHEN entry.type = 'array' THEN entry.value ELSE '[]' END, '$[1]') AS end_byte,
       json_extract(CASE WHEN entry.type = 'array' THEN entry.value ELSE '[]' END, '$[2]') AS start_line,
       json_extract(CASE WHEN entry.type = 'array' THEN entry.value ELSE '[]' END, '$[3]') AS end_line,
       CASE json_extract(CASE WHEN entry.type = 'array' THEN entry.value ELSE '[]' END, '$[4]')
            WHEN 0 THEN 'primary_node'
            WHEN 1 THEN 'explicit_subspan'
            WHEN 2 THEN 'embedded' END AS provenance
FROM source_occurrence_arenas AS arena,
     json_each(arena.spans) AS entry;

CREATE VIEW source_php_fact_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_php_contexts WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_aliases WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_context_aliases WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_declarations WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_nominal_arms WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_supertypes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_writes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_php_write_nominal_arms WHERE blob_id = blob.id) AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(namespace AS BLOB))) FROM source_php_contexts WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(COALESCE(length(CAST(doc_nominal_type AS BLOB)), 0)
                         + COALESCE(length(CAST(doc_element_type AS BLOB)), 0))
                  FROM source_php_declarations WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(arm AS BLOB))) FROM source_php_nominal_arms WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(supertype AS BLOB))) FROM source_php_supertypes WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(field AS BLOB))
                         + COALESCE(length(CAST(doc_element_type AS BLOB)), 0))
                  FROM source_php_writes WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(arm AS BLOB))) FROM source_php_write_nominal_arms WHERE blob_id = blob.id), 0) AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_python_costs AS
SELECT blob.id AS blob_id,
  1 + (SELECT COUNT(*) FROM source_python_callable_returns WHERE blob_id = blob.id)
    + (SELECT COUNT(*) FROM source_python_return_names WHERE blob_id = blob.id)
    + (SELECT COUNT(*) FROM source_python_annotation_references WHERE blob_id = blob.id)
    + (SELECT COUNT(*) FROM source_python_annotation_names WHERE blob_id = blob.id) AS logical_rows,
  COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_python_return_names WHERE blob_id = blob.id), 0)
    + COALESCE((SELECT SUM(length(CAST(lexical_name AS BLOB))) FROM source_python_annotation_references WHERE blob_id = blob.id), 0)
    + COALESCE((SELECT SUM(length(CAST(name AS BLOB))) FROM source_python_annotation_names WHERE blob_id = blob.id), 0) AS payload_bytes
FROM blobs AS blob;

CREATE VIEW source_ruby_costs AS
SELECT meta.blob_id,
  1 + (SELECT COUNT(*) FROM source_ruby_loads WHERE blob_id = meta.blob_id)
    + (SELECT COUNT(*) FROM source_ruby_load_constants WHERE blob_id = meta.blob_id) AS logical_rows,
  COALESCE((SELECT SUM(length(CAST(segment AS BLOB))) FROM source_ruby_load_constants WHERE blob_id = meta.blob_id), 0) AS payload_bytes
FROM blob_meta AS meta WHERE meta.ruby_source_version IS NOT NULL;

CREATE VIEW source_rust_exports AS
SELECT export.blob_id, export.lang, export.ordinal, export.exported_name,
       CASE WHEN export.source_import_id IS NULL THEN export.source_path ELSE
         COALESCE((SELECT group_concat(segment.segment, '::' ORDER BY segment.ordinal)
                   FROM source_import_segments AS segment
                   WHERE segment.blob_id = source.blob_id
                     AND segment.import_id = source.import_id
                     AND (source.is_wildcard = 1 OR segment.ordinal <
                          (SELECT MAX(last_segment.ordinal) FROM source_import_segments AS last_segment
                           WHERE last_segment.blob_id = source.blob_id
                             AND last_segment.import_id = source.import_id))), '') END
         AS source_path,
       CASE WHEN export.source_import_id IS NULL THEN export.imported_name ELSE source.identifier END
         AS imported_name,
       CASE WHEN export.source_import_id IS NULL THEN export.is_glob
            ELSE source.is_wildcard END AS is_glob,
       export.source_import_id AS source_import_id
FROM rust_exports AS export
LEFT JOIN source_imports AS source
  ON source.blob_id = export.blob_id AND source.import_id = export.source_import_id;

CREATE VIEW source_rust_import_module_segments AS
SELECT target.blob_id, target.lang, target.ordinal AS import_ordinal,
       segment.ordinal AS ordinal, segment.segment
FROM rust_import_targets AS target
JOIN source_imports AS source
  ON source.blob_id = target.blob_id AND source.import_id = target.source_import_id
JOIN source_import_segments AS segment
  ON segment.blob_id = source.blob_id AND segment.import_id = source.import_id
WHERE target.source_import_id IS NOT NULL
  AND (source.is_wildcard = 1 OR segment.ordinal <
       (SELECT MAX(last_segment.ordinal) FROM source_import_segments AS last_segment
        WHERE last_segment.blob_id = source.blob_id AND last_segment.import_id = source.import_id));

CREATE VIEW source_rust_import_targets AS
SELECT target.blob_id, target.lang, target.ordinal, target.module_path, target.bound_name,
       CASE WHEN target.source_import_id IS NULL THEN target.imported_name ELSE source.identifier END
         AS imported_name,
       CASE WHEN target.source_import_id IS NULL THEN target.is_glob
            ELSE source.is_wildcard END AS is_glob,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.visibility
            ELSE context.visibility END AS visibility,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.owner_module
            WHEN context.declaration_occurrence_id IS NULL THEN NULL
            ELSE context.owner_module END AS owner_module,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.owner_start
            WHEN context.declaration_occurrence_id IS NULL THEN NULL
            WHEN context.owner_scope_occurrence_id IS NULL THEN 0
            ELSE context.owner_scope_start_byte END AS owner_start,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.owner_end
            WHEN context.declaration_occurrence_id IS NULL THEN NULL
            WHEN context.owner_scope_occurrence_id IS NULL THEN manifest.source_bytes
            ELSE context.owner_scope_end_byte END AS owner_end,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.local_start
            WHEN context.declaration_occurrence_id IS NULL OR context.local_scope_occurrence_id IS NULL THEN NULL
            ELSE context.local_scope_start_byte END AS local_start,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.local_end
            WHEN context.declaration_occurrence_id IS NULL OR context.local_scope_occurrence_id IS NULL THEN NULL
            ELSE context.local_scope_end_byte END AS local_end,
       CASE WHEN target.source_context_occurrence_id IS NULL THEN target.cfg_condition
            ELSE context.cfg_condition END AS cfg_condition,
       CASE WHEN target.source_import_id IS NULL THEN target.is_extern_crate
            ELSE CASE WHEN source.path_kind = 'extern_crate' THEN 1 ELSE 0 END END
         AS is_extern_crate,
       CASE WHEN target.source_import_id IS NULL THEN target.is_macro_use
            ELSE source.is_macro_use END AS is_macro_use,
       CASE WHEN target.source_import_id IS NULL THEN target.leading_absolute
            ELSE source.is_global END AS leading_absolute,
       CASE WHEN target.source_import_id IS NULL THEN target.declaration_occurrence_id ELSE source.declaration_occurrence_id END
         AS declaration_occurrence_id,
       CASE WHEN target.source_import_id IS NULL THEN target.target_occurrence_id ELSE source.target_occurrence_id END
         AS target_occurrence_id,
       CASE WHEN target.source_import_id IS NULL THEN target.alias_occurrence_id ELSE source.alias_occurrence_id END
         AS alias_occurrence_id,
       target.source_import_id AS source_import_id,
       context.native_scope AS native_scope
FROM rust_import_targets AS target
LEFT JOIN source_imports AS source
  ON source.blob_id = target.blob_id AND source.import_id = target.source_import_id
LEFT JOIN source_rust_import_contexts AS context
  ON context.blob_id = target.blob_id
 AND context.declaration_occurrence_id = target.source_context_occurrence_id
LEFT JOIN source_fact_manifests AS manifest
  ON manifest.blob_id = target.blob_id;

CREATE VIEW source_scala_declaration_costs AS
SELECT blob.id AS blob_id,
       1
       + (SELECT COUNT(*) FROM source_scala_declarations WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_declaration_lexical_prefixes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_declaration_lexical_scopes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_declaration_path_segments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_generic_owners WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_generic_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_generic_supertypes WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_type_expressions WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_type_expression_segments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_type_expression_arguments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callables WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_lists WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_parameters WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_parameter_path_segments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_path_segments WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_function_paths WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_function_path_cells WHERE blob_id = blob.id)
       + (SELECT COUNT(*) FROM source_scala_callable_function_path_segments WHERE blob_id = blob.id)
         AS logical_rows,
       COALESCE((SELECT SUM(length(CAST(prefix AS BLOB)))
                 FROM source_scala_declaration_lexical_prefixes WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(segment AS BLOB)))
                   FROM source_scala_declaration_path_segments WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(name AS BLOB)))
                   FROM source_scala_generic_parameters WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(segment AS BLOB)))
                   FROM source_scala_type_expression_segments WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(segment AS BLOB)))
                   FROM source_scala_callable_parameter_path_segments WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(segment AS BLOB)))
                   FROM source_scala_callable_path_segments WHERE blob_id = blob.id), 0)
       + COALESCE((SELECT SUM(length(CAST(segment AS BLOB)))
                   FROM source_scala_callable_function_path_segments WHERE blob_id = blob.id), 0)
         AS payload_bytes
FROM blobs AS blob;

CREATE VIEW structural_source_manifests AS
SELECT
  source.blob_id,
  source.facts_version,
  source.source_bytes,
  source.node_count,
  source.role_count,
  source.occurrence_role_count
FROM source_fact_manifests AS source
WHERE source.publication_state = 'complete';

CREATE VIEW structural_source_nodes AS
SELECT
  node.blob_id,
  node.node_id,
  node.kind_code AS kind,
  node.boolean_value,
  node.construct,
  node.start_byte,
  node.end_byte,
  node.parent_node_id,
  node.name_start_byte,
  node.name_end_byte,
  node.subtree_end,
  node.call_kind_code AS call_kind,
  node.call_coverage_code AS call_coverage,
  node.continues_callee_groups
FROM source_structural_nodes AS node
JOIN source_fact_manifests AS source
  ON source.blob_id = node.blob_id
 AND source.publication_state = 'complete';

CREATE VIEW structural_source_occurrence_roles AS
SELECT
  role.blob_id,
  role.node_id,
  role.ordinal,
  role.role_code AS role
FROM source_structural_occurrence_roles AS role
JOIN source_fact_manifests AS source
  ON source.blob_id = role.blob_id
 AND source.publication_state = 'complete';

CREATE VIEW structural_source_roles AS
SELECT
  role.blob_id,
  role.source_node_id,
  role.ordinal,
  role.role_code AS role,
  role.spread,
  role.keyword_start_byte,
  role.keyword_end_byte,
  role.target_node_id,
  role.start_byte AS target_start_byte,
  role.end_byte AS target_end_byte,
  role.name_start_byte,
  role.name_end_byte
FROM source_structural_roles AS role
JOIN source_fact_manifests AS source
  ON source.blob_id = role.blob_id
 AND source.publication_state = 'complete';

CREATE VIEW unit_signature_metadata_values AS
SELECT metadata.blob_id, metadata.lang, metadata.unit_key, metadata.ordinal,
       metadata.label,
       CASE WHEN metadata.parameter_count IS NULL THEN metadata.parameters
            ELSE (SELECT json_group_array(json_object(
                    'label', parameter.label, 'name', parameter.name,
                    'start_byte', parameter.start_byte, 'end_byte', parameter.end_byte)
                    ORDER BY parameter.ordinal)
                  FROM unit_signature_parameters AS parameter
                  WHERE parameter.blob_id = metadata.blob_id
                    AND parameter.unit_key = metadata.unit_key
                    AND parameter.metadata_ordinal = metadata.ordinal)
       END AS parameters,
       metadata.return_type_text,
       metadata.return_type_identity, metadata.underlying_type_identity,
       metadata.declaration_only, metadata.callable_arity_required,
       metadata.callable_arity_total, metadata.callable_arity_repeated,
       metadata.type_parameters, metadata.bare_return_type_parameter,
       metadata.callable_linkage, metadata.dispatch_extensibility,
       metadata.extension_receiver_type, metadata.extension_receiver_type_identity,
       metadata.extension_receiver_is_unconstrained, metadata.field_is_static,
       metadata.field_is_final, metadata.field_has_initializer,
       metadata.cpp_field_linkage, metadata.companion_object,
       metadata.callable_is_static, metadata.callable_is_constructor,
       CASE
         WHEN meta.declaration_visibility_version IS NOT NULL
          AND units.synthetic = 0
          THEN CASE
            WHEN readiness.available = 1
             AND (SELECT COUNT(*)
                  FROM source_declaration_metadata_bridges AS bridge
                  WHERE bridge.blob_id = metadata.blob_id
                    AND bridge.unit_key = metadata.unit_key
                    AND bridge.metadata_ordinal = metadata.ordinal) > 0
             AND (SELECT COUNT(visibility.declaration_id)
                  FROM source_declaration_metadata_bridges AS bridge
                  JOIN source_declaration_visibilities AS visibility
                    ON visibility.blob_id = bridge.blob_id
                   AND visibility.declaration_id = bridge.declaration_id
                  WHERE bridge.blob_id = metadata.blob_id
                    AND bridge.unit_key = metadata.unit_key
                    AND bridge.metadata_ordinal = metadata.ordinal)
                 = (SELECT COUNT(*)
                    FROM source_declaration_metadata_bridges AS bridge
                    WHERE bridge.blob_id = metadata.blob_id
                      AND bridge.unit_key = metadata.unit_key
                      AND bridge.metadata_ordinal = metadata.ordinal)
             AND (SELECT COUNT(DISTINCT visibility.visibility)
                  FROM source_declaration_metadata_bridges AS bridge
                  JOIN source_declaration_visibilities AS visibility
                    ON visibility.blob_id = bridge.blob_id
                   AND visibility.declaration_id = bridge.declaration_id
                  WHERE bridge.blob_id = metadata.blob_id
                    AND bridge.unit_key = metadata.unit_key
                    AND bridge.metadata_ordinal = metadata.ordinal) = 1
            THEN (SELECT MIN(visibility.visibility)
                  FROM source_declaration_metadata_bridges AS bridge
                  JOIN source_declaration_visibilities AS visibility
                    ON visibility.blob_id = bridge.blob_id
                   AND visibility.declaration_id = bridge.declaration_id
                  WHERE bridge.blob_id = metadata.blob_id
                    AND bridge.unit_key = metadata.unit_key
                    AND bridge.metadata_ordinal = metadata.ordinal)
            ELSE NULL
          END
         ELSE metadata.callable_declared_visibility
       END AS callable_declared_visibility,
       metadata.callable_modifiers_recorded, metadata.callable_parameter_types,
       metadata.callable_is_native,
       CASE WHEN metadata.class_like_kind IS NULL THEN metadata.class_like_is_interface
            ELSE metadata.class_like_kind = 'interface' END AS class_like_is_interface,
       metadata.class_like_is_static,
       metadata.type_parameters_recorded, metadata.result_type_identities,
       metadata.parameter_type_identities, metadata.callable_override_modifier,
       metadata.java_constructor_shape, metadata.java_constructor_arity_required,
       metadata.java_constructor_arity_total, metadata.java_constructor_arity_repeated,
       metadata.class_like_kind,
       CASE
         WHEN metadata.parameter_count IS NOT NULL
          AND metadata.parameter_count <> (SELECT COUNT(*) FROM unit_signature_parameters AS parameter
                 WHERE parameter.blob_id = metadata.blob_id
                   AND parameter.unit_key = metadata.unit_key
                   AND parameter.metadata_ordinal = metadata.ordinal) THEN 0
         WHEN readiness.available = 0 THEN 0
         WHEN meta.metadata_bridges_required = 1
          AND (units.synthetic = 0 OR EXISTS (
            SELECT 1 FROM source_declaration_units AS source_unit
            WHERE source_unit.blob_id = metadata.blob_id AND source_unit.unit_key = metadata.unit_key
          ))
          AND NOT EXISTS (
            SELECT 1 FROM source_declaration_metadata_bridges AS bridge
            WHERE bridge.blob_id = metadata.blob_id AND bridge.unit_key = metadata.unit_key
              AND bridge.metadata_ordinal = metadata.ordinal
          ) THEN 0
         WHEN meta.java_type_constructor_version IS NOT NULL
          AND units.kind = 0 AND units.synthetic = 0
          AND metadata.java_constructor_shape IS NULL THEN 0
         WHEN meta.declaration_visibility_version IS NULL OR units.synthetic = 1 THEN 1
         WHEN (SELECT COUNT(*)
               FROM source_declaration_metadata_bridges AS bridge
               WHERE bridge.blob_id = metadata.blob_id
                 AND bridge.unit_key = metadata.unit_key
                 AND bridge.metadata_ordinal = metadata.ordinal) > 0
          AND (SELECT COUNT(visibility.declaration_id)
               FROM source_declaration_metadata_bridges AS bridge
               JOIN source_declaration_visibilities AS visibility
                 ON visibility.blob_id = bridge.blob_id
                AND visibility.declaration_id = bridge.declaration_id
               WHERE bridge.blob_id = metadata.blob_id
                 AND bridge.unit_key = metadata.unit_key
                 AND bridge.metadata_ordinal = metadata.ordinal)
              = (SELECT COUNT(*)
                 FROM source_declaration_metadata_bridges AS bridge
                 WHERE bridge.blob_id = metadata.blob_id
                   AND bridge.unit_key = metadata.unit_key
                   AND bridge.metadata_ordinal = metadata.ordinal)
          AND (SELECT COUNT(DISTINCT visibility.visibility)
               FROM source_declaration_metadata_bridges AS bridge
               JOIN source_declaration_visibilities AS visibility
                 ON visibility.blob_id = bridge.blob_id
                AND visibility.declaration_id = bridge.declaration_id
               WHERE bridge.blob_id = metadata.blob_id
                 AND bridge.unit_key = metadata.unit_key
                 AND bridge.metadata_ordinal = metadata.ordinal) = 1
         THEN 1
         ELSE 0
       END AS metadata_available
FROM unit_signature_metadata AS metadata
JOIN blob_meta AS meta ON meta.blob_id = metadata.blob_id
JOIN code_units AS units
  ON units.blob_id = metadata.blob_id AND units.unit_key = metadata.unit_key
JOIN source_declaration_visibility_readiness AS readiness
  ON readiness.blob_id = metadata.blob_id;

CREATE TRIGGER blob_meta_cpp_source_requirement_is_immutable
BEFORE UPDATE OF cpp_source_version ON blob_meta
WHEN EXISTS (SELECT 1 FROM blobs WHERE id = OLD.blob_id)
 AND (OLD.is_complete = 1 OR EXISTS (SELECT 1 FROM source_fact_manifests
                                   WHERE blob_id = OLD.blob_id AND publication_state = 'complete'))
BEGIN SELECT RAISE(ABORT, 'sealed C++ source requirement is immutable'); END;

CREATE TRIGGER blob_meta_signature_metadata_pairs_no_update_after_seal
BEFORE UPDATE OF signature_metadata_count ON blob_meta
WHEN EXISTS (
  SELECT 1 FROM blob_optional_fact_manifest
  WHERE blob_id = OLD.blob_id AND fact_kind = 6
)
AND EXISTS (
  SELECT 1 FROM blobs WHERE id = OLD.blob_id
)
BEGIN
  SELECT RAISE(ABORT, 'sealed signature metadata pair manifest is immutable');
END;

CREATE TRIGGER blob_optional_fact_manifest_cpp_class_templates_no_delete_after_seal
BEFORE DELETE ON blob_optional_fact_manifest
WHEN OLD.fact_kind = 1 AND EXISTS (SELECT 1 FROM blobs WHERE id = OLD.blob_id)
BEGIN SELECT RAISE(ABORT, 'sealed C++ class-template manifest is immutable'); END;

CREATE TRIGGER blob_optional_fact_manifest_cpp_class_templates_no_update_after_seal
BEFORE UPDATE ON blob_optional_fact_manifest
WHEN (OLD.fact_kind = 1 OR NEW.fact_kind = 1)
 AND (EXISTS (SELECT 1 FROM blobs WHERE id = OLD.blob_id) OR EXISTS (SELECT 1 FROM blobs WHERE id = NEW.blob_id))
BEGIN SELECT RAISE(ABORT, 'sealed C++ class-template manifest is immutable'); END;

CREATE TRIGGER blob_optional_fact_manifest_signature_metadata_pairs_no_delete_after_seal
BEFORE DELETE ON blob_optional_fact_manifest
WHEN OLD.fact_kind = 6
 AND EXISTS (
   SELECT 1 FROM blob_optional_fact_manifest
   WHERE blob_id = OLD.blob_id AND fact_kind = 6
 )
 AND EXISTS (
   SELECT 1 FROM blobs WHERE id = OLD.blob_id
 )
BEGIN
  SELECT RAISE(ABORT, 'sealed signature metadata pair manifest is immutable');
END;

CREATE TRIGGER blob_optional_fact_manifest_signature_metadata_pairs_no_update_after_seal
BEFORE UPDATE ON blob_optional_fact_manifest
WHEN (OLD.fact_kind = 6 OR NEW.fact_kind = 6)
 AND (
   EXISTS (SELECT 1 FROM blobs WHERE id = OLD.blob_id)
   OR EXISTS (SELECT 1 FROM blobs WHERE id = NEW.blob_id)
 )
BEGIN
  SELECT RAISE(ABORT, 'sealed signature metadata pair manifest is immutable');
END;

CREATE TRIGGER blob_optional_fact_manifest_validate_cpp_class_templates
BEFORE INSERT ON blob_optional_fact_manifest
WHEN NEW.fact_kind = 1
BEGIN
  SELECT CASE WHEN (SELECT is_complete FROM blob_meta WHERE blob_id = NEW.blob_id) IS NOT 1
    THEN RAISE(ABORT, 'C++ class-template manifest requires a complete blob') END;
  SELECT CASE WHEN NEW.row_count <> (SELECT COUNT(*) FROM unit_cpp_class_templates WHERE blob_id = NEW.blob_id)
    THEN RAISE(ABORT, 'C++ class-template manifest count is inconsistent') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_templates AS header
    WHERE header.blob_id = NEW.blob_id AND (
      header.parameter_count <> (SELECT COUNT(*) FROM unit_cpp_class_template_parameters AS parameter WHERE parameter.blob_id = header.blob_id AND parameter.unit_key = header.unit_key)
      OR header.specialization_argument_count <> (SELECT COUNT(*) FROM unit_cpp_class_template_expressions AS expression WHERE expression.blob_id = header.blob_id AND expression.unit_key = header.unit_key AND expression.role = 1)
      OR header.alias_component_count <> (SELECT COUNT(*) FROM unit_cpp_class_template_alias_components AS component WHERE component.blob_id = header.blob_id AND component.unit_key = header.unit_key)
      OR header.alias_argument_count <> (SELECT COUNT(*) FROM unit_cpp_class_template_expressions AS expression WHERE expression.blob_id = header.blob_id AND expression.unit_key = header.unit_key AND expression.role = 2)
    )) THEN RAISE(ABORT, 'C++ class-template child counts are inconsistent') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_template_parameters AS parameter
    WHERE parameter.blob_id = NEW.blob_id AND parameter.default_present <> EXISTS (
      SELECT 1 FROM unit_cpp_class_template_expressions AS expression
      WHERE expression.blob_id = parameter.blob_id AND expression.unit_key = parameter.unit_key
        AND expression.role = 0 AND expression.owner_ordinal = parameter.ordinal
    )) OR EXISTS (
      SELECT 1 FROM unit_cpp_class_template_expressions AS expression
      WHERE expression.blob_id = NEW.blob_id AND expression.role = 0 AND NOT EXISTS (
        SELECT 1 FROM unit_cpp_class_template_parameters AS parameter
        WHERE parameter.blob_id = expression.blob_id AND parameter.unit_key = expression.unit_key
          AND parameter.ordinal = expression.owner_ordinal AND parameter.default_present = 1
      )
    ) THEN RAISE(ABORT, 'C++ class-template parameter defaults are inconsistent') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_templates AS header
    WHERE header.blob_id = NEW.blob_id AND (
      (header.parameter_count > 0 AND (SELECT MAX(ordinal) FROM unit_cpp_class_template_parameters WHERE blob_id = header.blob_id AND unit_key = header.unit_key) <> header.parameter_count - 1)
      OR (header.specialization_argument_count > 0 AND (SELECT MAX(owner_ordinal) FROM unit_cpp_class_template_expressions WHERE blob_id = header.blob_id AND unit_key = header.unit_key AND role = 1) <> header.specialization_argument_count - 1)
      OR (header.alias_component_count > 0 AND (SELECT MAX(ordinal) FROM unit_cpp_class_template_alias_components WHERE blob_id = header.blob_id AND unit_key = header.unit_key) <> header.alias_component_count - 1)
      OR (header.alias_argument_count > 0 AND (SELECT MAX(owner_ordinal) FROM unit_cpp_class_template_expressions WHERE blob_id = header.blob_id AND unit_key = header.unit_key AND role = 2) <> header.alias_argument_count - 1)
    )) THEN RAISE(ABORT, 'C++ class-template child ordinals are not dense') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_template_expressions AS expression
    WHERE expression.blob_id = NEW.blob_id AND (
      (SELECT COUNT(*) FROM unit_cpp_class_template_terms AS term WHERE term.blob_id = expression.blob_id AND term.expression_id = expression.expression_id AND term.parent_term_id IS NULL) <> 1
      OR NOT EXISTS (SELECT 1 FROM unit_cpp_class_template_terms AS root WHERE root.blob_id = expression.blob_id AND root.expression_id = expression.expression_id AND root.term_id = expression.root_term_id AND root.parent_term_id IS NULL AND root.ordinal = 0)
    )) THEN RAISE(ABORT, 'C++ class-template expression root is inconsistent') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_template_terms AS child
    WHERE child.blob_id = NEW.blob_id AND child.parent_term_id IS NOT NULL
    GROUP BY child.blob_id, child.expression_id, child.parent_term_id
    HAVING MIN(child.ordinal) <> 0 OR MAX(child.ordinal) <> COUNT(*) - 1
  ) THEN RAISE(ABORT, 'C++ class-template child term ordinals are not dense') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM unit_cpp_class_template_terms AS child
    JOIN unit_cpp_class_template_terms AS parent
      ON parent.blob_id = child.blob_id
     AND parent.expression_id = child.expression_id
     AND parent.term_id = child.parent_term_id
    WHERE child.blob_id = NEW.blob_id AND parent.kind <> 2
  ) THEN RAISE(ABORT, 'C++ class-template leaf term cannot own children') END;
END;

CREATE TRIGGER blob_optional_fact_manifest_validate_signature_metadata_pairs
BEFORE INSERT ON blob_optional_fact_manifest
WHEN NEW.fact_kind = 6
BEGIN
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM blob_optional_fact_manifest
    WHERE blob_id = NEW.blob_id AND fact_kind = 6
  ) THEN RAISE(ABORT, 'sealed signature metadata pair manifest is immutable') END;
  SELECT CASE WHEN (
    SELECT is_complete FROM blob_meta
    WHERE blob_id = NEW.blob_id
  ) IS NOT 1 THEN RAISE(ABORT, 'signature metadata pair manifest requires a complete blob') END;
  SELECT CASE WHEN NEW.row_count <> (
    SELECT COUNT(*)
    FROM unit_signature_metadata_signatures
    WHERE blob_id = NEW.blob_id
  ) THEN RAISE(ABORT, 'signature metadata pair count is inconsistent') END;
  SELECT CASE WHEN NEW.row_count <> (
    SELECT signature_metadata_count FROM blob_meta
    WHERE blob_id = NEW.blob_id
  ) THEN RAISE(ABORT, 'signature metadata pair manifest count is inconsistent') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM unit_signature_metadata AS metadata
    LEFT JOIN unit_signature_metadata_signatures AS pair
      ON pair.blob_id = metadata.blob_id
     AND pair.unit_key = metadata.unit_key
     AND pair.metadata_ordinal = metadata.ordinal
    WHERE metadata.blob_id = NEW.blob_id
      AND pair.metadata_ordinal IS NULL
  ) THEN RAISE(ABORT, 'signature metadata rows are missing pairs') END;
END;

