CREATE TRIGGER source_cpp_context_validate
BEFORE INSERT ON source_cpp_manifests
BEGIN
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM source_cpp_declarations AS declaration
    WHERE declaration.blob_id = NEW.blob_id AND NOT EXISTS
      (SELECT 1 FROM source_cpp_declaration_contexts AS context
       WHERE context.blob_id = declaration.blob_id AND context.declaration_id = declaration.declaration_id)
  ) OR EXISTS (
    SELECT 1 FROM source_cpp_declaration_contexts AS context
    JOIN source_fact_manifests AS source USING(blob_id)
    WHERE context.blob_id = NEW.blob_id AND context.callable_activation > source.source_bytes
  ) OR EXISTS (
    SELECT 1 FROM source_cpp_flattened_namespaces AS namespace
    JOIN source_cpp_declaration_contexts AS context USING(blob_id, declaration_id)
    WHERE namespace.blob_id = NEW.blob_id AND context.flattened_namespace_present = 0
  ) OR EXISTS (
    SELECT 1 FROM source_cpp_guard_roots AS root
    JOIN source_cpp_guard_nodes AS node ON node.blob_id = root.blob_id
      AND node.declaration_id = root.declaration_id AND node.guard_kind = root.guard_kind
      AND node.node_id = root.node_id
    WHERE root.blob_id = NEW.blob_id AND node.kind NOT IN (0,1,2,3,4,5)
  ) OR EXISTS (
    SELECT 1 FROM source_cpp_guard_edges AS edge
    JOIN source_cpp_guard_nodes AS node ON node.blob_id = edge.blob_id
      AND node.declaration_id = edge.declaration_id AND node.guard_kind = edge.guard_kind
      AND node.node_id = edge.child_id
    WHERE edge.blob_id = NEW.blob_id AND node.kind IN (2,3,4)
  ) OR EXISTS (
    SELECT 1 FROM source_cpp_guard_nodes AS node
    WHERE node.blob_id = NEW.blob_id AND (
      (SELECT COUNT(*) FROM source_cpp_guard_edges AS edge
       WHERE edge.blob_id = node.blob_id AND edge.declaration_id = node.declaration_id
         AND edge.guard_kind = node.guard_kind AND edge.child_id = node.node_id)
      + (SELECT COUNT(*) FROM source_cpp_guard_roots AS root
         WHERE root.blob_id = node.blob_id AND root.declaration_id = node.declaration_id
           AND root.guard_kind = node.guard_kind AND root.node_id = node.node_id) <> 1
      OR (node.kind = 2 AND (SELECT COUNT(*) FROM source_cpp_guard_edges AS edge
        WHERE edge.blob_id = node.blob_id AND edge.declaration_id = node.declaration_id
          AND edge.guard_kind = node.guard_kind AND edge.parent_id = node.node_id) <> 1)
      OR (node.kind NOT IN (2,10,11) AND EXISTS(SELECT 1 FROM source_cpp_guard_edges AS edge
        WHERE edge.blob_id = node.blob_id AND edge.declaration_id = node.declaration_id
          AND edge.guard_kind = node.guard_kind AND edge.parent_id = node.node_id))))
  THEN RAISE(ABORT, 'C++ source publication has invalid declaration context') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM source_cpp_flattened_namespaces WHERE blob_id = NEW.blob_id
    GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) + 1 <> COUNT(*))
    THEN RAISE(ABORT, 'C++ declaration context ordinals are not dense') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM source_cpp_guard_nodes WHERE blob_id = NEW.blob_id
    GROUP BY declaration_id, guard_kind HAVING MIN(node_id) <> 0 OR MAX(node_id) + 1 <> COUNT(*))
    THEN RAISE(ABORT, 'C++ declaration context ordinals are not dense') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM source_cpp_guard_edges WHERE blob_id = NEW.blob_id
    GROUP BY declaration_id, guard_kind, parent_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) + 1 <> COUNT(*))
    THEN RAISE(ABORT, 'C++ declaration context ordinals are not dense') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM source_cpp_guard_roots WHERE blob_id = NEW.blob_id
    GROUP BY declaration_id, guard_kind HAVING MIN(ordinal) <> 0 OR MAX(ordinal) + 1 <> COUNT(*))
    THEN RAISE(ABORT, 'C++ declaration context ordinals are not dense') END;
END;

