CREATE TRIGGER source_go_manifests_validate
BEFORE INSERT ON source_go_manifests
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM blob_meta AS meta
    WHERE meta.blob_id = NEW.blob_id AND meta.go_source_version = NEW.facts_version
  ) THEN RAISE(ABORT, 'Go source publication requires a matching Go blob requirement') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM source_go_fact_costs WHERE blob_id = NEW.blob_id
      AND logical_rows = NEW.logical_rows AND payload_bytes = NEW.payload_bytes
  ) THEN RAISE(ABORT, 'Go source publication accounting is inconsistent') END;
  SELECT CASE WHEN (
    (SELECT COUNT(*) FROM source_go_types WHERE blob_id = NEW.blob_id)
      <> COALESCE((SELECT MAX(type_id) + 1 FROM source_go_types WHERE blob_id = NEW.blob_id), 0)
    OR (SELECT COUNT(*) FROM source_go_embeddings WHERE blob_id = NEW.blob_id)
      <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_go_embeddings WHERE blob_id = NEW.blob_id), 0)
    OR EXISTS (SELECT 1 FROM source_go_type_names WHERE blob_id = NEW.blob_id
               GROUP BY type_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_go_type_children WHERE blob_id = NEW.blob_id
               GROUP BY type_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_go_callable_parameters WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id, result HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (
      SELECT 1 FROM source_go_types AS ty WHERE ty.blob_id = NEW.blob_id
        AND ((ty.kind = 0) <> EXISTS (SELECT 1 FROM source_go_type_names AS name
             WHERE name.blob_id = ty.blob_id AND name.type_id = ty.type_id))
    )
    OR EXISTS (
      SELECT 1 FROM source_go_type_children AS edge JOIN source_go_types AS ty
        ON ty.blob_id = edge.blob_id AND ty.type_id = edge.type_id
      WHERE edge.blob_id = NEW.blob_id AND ty.kind NOT IN (7, 8, 9, 10)
    )
    OR EXISTS (
      SELECT 1 FROM source_go_fields AS field JOIN source_go_types AS owner
        ON owner.blob_id = field.blob_id AND owner.type_id = field.owner_type_id
      WHERE field.blob_id = NEW.blob_id AND owner.kind <> 12
    )
    OR EXISTS (
      SELECT 1 FROM source_go_callables AS callable JOIN source_go_types AS owner
        ON owner.blob_id = callable.blob_id AND owner.type_id = callable.owner_type_id
      WHERE callable.blob_id = NEW.blob_id AND owner.kind <> 13
    )
    OR EXISTS (
      SELECT 1 FROM source_go_embeddings AS embedding JOIN source_go_types AS owner
        ON owner.blob_id = embedding.blob_id AND owner.type_id = embedding.owner_type_id
      WHERE embedding.blob_id = NEW.blob_id AND owner.kind NOT IN (12, 13)
    )
    OR EXISTS (
      SELECT 1 FROM source_go_callable_parameters AS parameter JOIN source_go_callables AS callable
        ON callable.blob_id = parameter.blob_id AND callable.declaration_id = parameter.declaration_id
      WHERE parameter.blob_id = NEW.blob_id
        AND ((parameter.result = 0 AND callable.parameters_present = 0)
          OR (parameter.result = 1 AND callable.result_occurrence_id IS NULL))
    )
  ) THEN RAISE(ABORT, 'Go source publication has invalid ordered syntax or ownership') END;
END;

