CREATE TRIGGER source_inline_occurrences_validate_seal
BEFORE UPDATE OF publication_state ON source_fact_manifests
WHEN OLD.publication_state = 'building' AND NEW.publication_state = 'complete'
BEGIN
  -- Range/value validation proves occurrence existence; this shared check
  -- proves every inline copy agrees with the arena. Language predicates use
  -- indexed owning facts and retain LEFT JOIN checks for missing owner rows.
  WITH arena AS MATERIALIZED (
    SELECT * FROM source_occurrences WHERE blob_id = NEW.blob_id
  )
  SELECT CASE WHEN EXISTS (
    SELECT * FROM (
      SELECT binder_occurrence_id, occurrence_binder_start_byte, occurrence_binder_end_byte FROM import_statements WHERE blob_id=NEW.blob_id AND binder_occurrence_id IS NOT NULL
      UNION ALL
      SELECT declaration_occurrence_id, occurrence_declaration_start_byte, occurrence_declaration_end_byte FROM import_statements WHERE blob_id=NEW.blob_id AND declaration_occurrence_id IS NOT NULL
      UNION ALL
      SELECT alias_occurrence_id, alias_start_byte, alias_end_byte FROM rust_import_targets WHERE blob_id=NEW.blob_id AND alias_occurrence_id IS NOT NULL
      UNION ALL
      SELECT declaration_occurrence_id, declaration_start_byte, declaration_end_byte FROM rust_import_targets WHERE blob_id=NEW.blob_id AND declaration_occurrence_id IS NOT NULL
      UNION ALL
      SELECT target_occurrence_id, target_start_byte, target_end_byte FROM rust_import_targets WHERE blob_id=NEW.blob_id AND target_occurrence_id IS NOT NULL
      UNION ALL
      SELECT name_occurrence_id, name_start_byte, name_end_byte FROM source_declarations WHERE blob_id=NEW.blob_id AND name_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_declarations WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_import_scopes WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT alias_occurrence_id, alias_start_byte, alias_end_byte FROM source_imports WHERE blob_id=NEW.blob_id AND alias_occurrence_id IS NOT NULL
      UNION ALL
      SELECT declaration_occurrence_id, declaration_start_byte, declaration_end_byte FROM source_imports WHERE blob_id=NEW.blob_id AND declaration_occurrence_id IS NOT NULL
      UNION ALL
      SELECT target_occurrence_id, target_start_byte, target_end_byte FROM source_imports WHERE blob_id=NEW.blob_id AND target_occurrence_id IS NOT NULL
      UNION ALL
      SELECT lexical_scope_occurrence_id, lexical_scope_start_byte, lexical_scope_end_byte FROM source_java_local_types WHERE blob_id=NEW.blob_id AND lexical_scope_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_python_annotation_references WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT parameters_occurrence_id, parameters_start_byte, parameters_end_byte FROM source_rust_callable_items WHERE blob_id=NEW.blob_id AND parameters_occurrence_id IS NOT NULL
      UNION ALL
      SELECT label_occurrence_id, label_start_byte, label_end_byte FROM source_rust_callable_parameters WHERE blob_id=NEW.blob_id AND label_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_callable_parameters WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT body_occurrence_id, body_start_byte, body_end_byte FROM source_rust_impl_items WHERE blob_id=NEW.blob_id AND body_occurrence_id IS NOT NULL
      UNION ALL
      SELECT negation_occurrence_id, negation_start_byte, negation_end_byte FROM source_rust_impl_items WHERE blob_id=NEW.blob_id AND negation_occurrence_id IS NOT NULL
      UNION ALL
      SELECT declaration_occurrence_id, declaration_start_byte, declaration_end_byte FROM source_rust_import_contexts WHERE blob_id=NEW.blob_id AND declaration_occurrence_id IS NOT NULL
      UNION ALL
      SELECT local_scope_occurrence_id, local_scope_start_byte, local_scope_end_byte FROM source_rust_import_contexts WHERE blob_id=NEW.blob_id AND local_scope_occurrence_id IS NOT NULL
      UNION ALL
      SELECT owner_scope_occurrence_id, owner_scope_start_byte, owner_scope_end_byte FROM source_rust_import_contexts WHERE blob_id=NEW.blob_id AND owner_scope_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_item_body_children WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_item_contexts WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT name_occurrence_id, name_start_byte, name_end_byte FROM source_rust_item_generic_parameters WHERE blob_id=NEW.blob_id AND name_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_item_generic_parameters WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT invocation_occurrence_id, invocation_start_byte, invocation_end_byte FROM source_rust_item_macro_expansions WHERE blob_id=NEW.blob_id AND invocation_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_macro_arms WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT source_occurrence_id, start_byte, end_byte FROM source_rust_macro_input_tokens WHERE blob_id=NEW.blob_id AND source_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_macro_invocations WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_macro_pattern_nodes WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT body_occurrence_id, body_start_byte, body_end_byte FROM source_rust_module_declarations WHERE blob_id=NEW.blob_id AND body_occurrence_id IS NOT NULL
      UNION ALL
      SELECT root_occurrence_id, root_start_byte, root_end_byte FROM source_rust_module_manifests WHERE blob_id=NEW.blob_id AND root_occurrence_id IS NOT NULL
      UNION ALL
      SELECT body_occurrence_id, body_start_byte, body_end_byte FROM source_rust_trait_items WHERE blob_id=NEW.blob_id AND body_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_type_generic_lists WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_type_segments WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_type_wrappers WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT compound_occurrence_id, compound_start_byte, compound_end_byte FROM source_rust_types WHERE blob_id=NEW.blob_id AND compound_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_byte, end_byte FROM source_rust_types WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT type_parameters_occurrence_id, type_parameters_start_byte, type_parameters_end_byte FROM source_rust_types WHERE blob_id=NEW.blob_id AND type_parameters_occurrence_id IS NOT NULL
      UNION ALL
      SELECT unsupported_occurrence_id, unsupported_start_byte, unsupported_end_byte FROM source_rust_types WHERE blob_id=NEW.blob_id AND unsupported_occurrence_id IS NOT NULL
      UNION ALL
      SELECT return_annotation_id, return_annotation_start_byte, return_annotation_end_byte
      FROM source_python_callable_returns WHERE blob_id=NEW.blob_id AND return_annotation_id IS NOT NULL
    )
    EXCEPT SELECT occurrence_id, start_byte, end_byte FROM arena
  )
  OR EXISTS (
    SELECT * FROM (
      SELECT occurrence_id, provenance FROM source_declarations WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_item_contexts WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_macro_arms WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_macro_invocations WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_macro_pattern_nodes WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT body_occurrence_id, body_provenance FROM source_rust_module_declarations WHERE blob_id=NEW.blob_id AND body_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_type_generic_lists WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_type_segments WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_type_wrappers WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT compound_occurrence_id, compound_provenance FROM source_rust_types WHERE blob_id=NEW.blob_id AND compound_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, provenance FROM source_rust_types WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
      UNION ALL
      SELECT type_parameters_occurrence_id, type_parameters_provenance FROM source_rust_types WHERE blob_id=NEW.blob_id AND type_parameters_occurrence_id IS NOT NULL
      UNION ALL
      SELECT unsupported_occurrence_id, unsupported_provenance FROM source_rust_types WHERE blob_id=NEW.blob_id AND unsupported_occurrence_id IS NOT NULL
      UNION ALL
      SELECT root_occurrence_id, root_provenance FROM source_rust_module_manifests WHERE blob_id=NEW.blob_id
    )
    EXCEPT SELECT occurrence_id, CASE provenance WHEN 'primary_node' THEN 0 WHEN 'explicit_subspan' THEN 1 WHEN 'embedded' THEN 2 END FROM arena
  )
  OR EXISTS (
    SELECT * FROM (
      SELECT name_occurrence_id, name_start_line, name_end_line FROM source_declarations WHERE blob_id=NEW.blob_id AND name_occurrence_id IS NOT NULL
      UNION ALL
      SELECT occurrence_id, start_line, end_line FROM source_declarations WHERE blob_id=NEW.blob_id AND occurrence_id IS NOT NULL
    )
    EXCEPT SELECT occurrence_id, start_line, end_line FROM arena
  )
  OR EXISTS (
    SELECT invocation_occurrence_id, invocation_start_byte
    FROM source_rust_macro_inputs WHERE blob_id = NEW.blob_id
    EXCEPT SELECT occurrence_id, start_byte FROM arena
  )
  THEN RAISE(ABORT, 'inline source occurrence fields are inconsistent with arena') END;
END;

