BEGIN SELECT RAISE(ABORT, 'sealed Java source facts are immutable'); END;

CREATE TRIGGER source_java_declaration_manifests_validate
BEFORE INSERT ON source_java_declaration_manifests
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM blob_meta AS meta
    WHERE meta.blob_id = NEW.blob_id AND meta.java_source_version = NEW.facts_version
  ) THEN RAISE(ABORT, 'Java source publication requires a matching Java blob requirement') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM source_java_declaration_costs WHERE blob_id = NEW.blob_id
      AND logical_rows = NEW.logical_rows AND payload_bytes = NEW.payload_bytes
  ) THEN RAISE(ABORT, 'Java source publication accounting is inconsistent') END;
  SELECT CASE WHEN (
    (SELECT COUNT(*) FROM source_java_types WHERE blob_id = NEW.blob_id)
      <> COALESCE((SELECT MAX(type_id) + 1 FROM source_java_types WHERE blob_id = NEW.blob_id), 0)
    OR EXISTS (SELECT 1 FROM source_java_type_names WHERE blob_id = NEW.blob_id
               GROUP BY type_id, axis HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_java_type_arguments WHERE blob_id = NEW.blob_id
               GROUP BY type_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_java_type_bounds WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_java_anonymous_return_entries WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_java_types AS ty WHERE ty.blob_id = NEW.blob_id
        AND ((ty.kind = 0) <> EXISTS (SELECT 1 FROM source_java_type_names AS name
            WHERE name.blob_id = ty.blob_id AND name.type_id = ty.type_id AND name.axis = 0)))
    OR EXISTS (SELECT 1 FROM source_java_type_names AS name JOIN source_java_types AS ty
        ON ty.blob_id = name.blob_id AND ty.type_id = name.type_id
        WHERE name.blob_id = NEW.blob_id AND ty.kind <> 0)
    OR EXISTS (SELECT 1 FROM source_java_type_arguments AS argument JOIN source_java_types AS ty
        ON ty.blob_id = argument.blob_id AND ty.type_id = argument.type_id
        WHERE argument.blob_id = NEW.blob_id AND ty.kind <> 1)
    OR EXISTS (SELECT 1 FROM source_java_anonymous_returns AS fact
        WHERE fact.blob_id = NEW.blob_id AND fact.status = 0
          AND NOT EXISTS (SELECT 1 FROM source_java_anonymous_return_entries AS entry
                          WHERE entry.blob_id = fact.blob_id AND entry.declaration_id = fact.declaration_id))
    OR EXISTS (SELECT 1 FROM source_java_anonymous_returns AS fact
        JOIN source_java_anonymous_return_entries AS entry
          ON entry.blob_id = fact.blob_id AND entry.declaration_id = fact.declaration_id
        WHERE fact.blob_id = NEW.blob_id AND fact.status = 1)
    OR EXISTS (
      SELECT 1 FROM source_java_types AS ty
      JOIN source_java_type_parameters AS parameter
        ON parameter.blob_id = ty.blob_id AND parameter.declaration_id = ty.parameter_declaration_id
      WHERE ty.blob_id = NEW.blob_id AND (
        ty.absolute <> 0
        OR (SELECT COUNT(*) FROM source_java_type_names AS name
            WHERE name.blob_id = ty.blob_id AND name.type_id = ty.type_id AND name.axis = 0) <> 1
        OR NOT EXISTS (SELECT 1 FROM source_java_type_names AS name
            WHERE name.blob_id = ty.blob_id AND name.type_id = ty.type_id
              AND name.axis = 0 AND name.ordinal = 0 AND name.name = parameter.name)
      )
    )
    OR EXISTS (
      SELECT 1 FROM source_java_declaration_owners AS pair
      JOIN source_declarations AS child ON child.blob_id = pair.blob_id AND child.declaration_id = pair.declaration_id
      JOIN source_declarations AS owner ON owner.blob_id = pair.blob_id AND owner.declaration_id = pair.owner_declaration_id
      WHERE pair.blob_id = NEW.blob_id AND (child.start_byte < owner.start_byte OR child.end_byte > owner.end_byte)
    )
    OR EXISTS (
      SELECT 1 FROM source_java_local_types AS local
      JOIN source_declarations AS declaration ON declaration.blob_id = local.blob_id AND declaration.declaration_id = local.declaration_id
      WHERE local.blob_id = NEW.blob_id AND (declaration.start_byte < local.lexical_scope_start_byte OR declaration.end_byte > local.lexical_scope_end_byte)
    )
  ) THEN RAISE(ABORT, 'Java source publication has invalid ordered syntax or ownership') END;
END;

