CREATE TRIGGER source_js_ts_manifests_validate
BEFORE INSERT ON source_js_ts_manifests
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM blob_meta AS meta
    WHERE meta.blob_id = NEW.blob_id
      AND meta.js_ts_source_version = NEW.facts_version
  ) THEN RAISE(ABORT, 'JS/TS source publication requires a matching JS/TS blob requirement') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM source_js_ts_fact_costs
    WHERE blob_id = NEW.blob_id
      AND logical_rows = NEW.logical_rows
      AND payload_bytes = NEW.payload_bytes
  ) THEN RAISE(ABORT, 'JS/TS source publication accounting is inconsistent') END;
  SELECT CASE WHEN (
    NEW.binding_count <> (SELECT COUNT(*) FROM source_js_ts_bindings WHERE blob_id = NEW.blob_id)
    OR NEW.export_count <> (SELECT COUNT(*) FROM source_js_ts_exports WHERE blob_id = NEW.blob_id)
    OR NEW.declaration_count <> (SELECT COUNT(*) FROM source_js_ts_declarations WHERE blob_id = NEW.blob_id)
    OR NEW.type_count <> (SELECT COUNT(*) FROM source_js_ts_types WHERE blob_id = NEW.blob_id)
    OR NEW.type_name_count <> (SELECT COUNT(*) FROM source_js_ts_type_names WHERE blob_id = NEW.blob_id)
    OR NEW.type_child_count <> (SELECT COUNT(*) FROM source_js_ts_type_children WHERE blob_id = NEW.blob_id)
    OR NEW.type_member_count <> (SELECT COUNT(*) FROM source_js_ts_type_members WHERE blob_id = NEW.blob_id)
    OR NEW.type_parameter_count <> (SELECT COUNT(*) FROM source_js_ts_type_parameters WHERE blob_id = NEW.blob_id)
    OR NEW.declaration_parameter_count <> (SELECT COUNT(*) FROM source_js_ts_declaration_parameters WHERE blob_id = NEW.blob_id)
    OR NEW.component_member_count <> (SELECT COUNT(*) FROM source_js_ts_component_members WHERE blob_id = NEW.blob_id)
    OR NEW.declaration_binding_count <> (SELECT COUNT(*) FROM source_js_ts_declaration_bindings WHERE blob_id = NEW.blob_id)
    OR NEW.property_receiver_count <> (SELECT COUNT(*) FROM source_js_ts_property_receivers WHERE blob_id = NEW.blob_id)
    OR NEW.property_receiver_member_count <> (SELECT COUNT(*) FROM source_js_ts_property_receiver_members WHERE blob_id = NEW.blob_id)
    OR NEW.file_is_external_module NOT IN (0, 1)
    OR NEW.file_is_esm NOT IN (0, 1)
    OR NEW.binding_count <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_js_ts_bindings WHERE blob_id = NEW.blob_id), 0)
    OR NEW.export_count <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_js_ts_exports WHERE blob_id = NEW.blob_id), 0)
    OR NEW.declaration_count <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_js_ts_declarations WHERE blob_id = NEW.blob_id), 0)
    OR NEW.type_count <> COALESCE((SELECT MAX(type_id) + 1 FROM source_js_ts_types WHERE blob_id = NEW.blob_id), 0)
    OR EXISTS (SELECT 1 FROM source_js_ts_type_names WHERE blob_id = NEW.blob_id GROUP BY type_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_type_children WHERE blob_id = NEW.blob_id GROUP BY type_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_type_members WHERE blob_id = NEW.blob_id GROUP BY type_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_type_parameters WHERE blob_id = NEW.blob_id GROUP BY type_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_declaration_parameters WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_component_members WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR NEW.declaration_binding_count <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_js_ts_declaration_bindings WHERE blob_id = NEW.blob_id), 0)
    OR NEW.property_receiver_count <> COALESCE((SELECT MAX(ordinal) + 1 FROM source_js_ts_property_receivers WHERE blob_id = NEW.blob_id), 0)
    OR EXISTS (SELECT 1 FROM source_js_ts_property_receiver_members WHERE blob_id = NEW.blob_id
               GROUP BY receiver_ordinal HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_js_ts_declarations AS declaration
               WHERE declaration.blob_id = NEW.blob_id
                 AND (((COALESCE(declaration.component_kind, -1) = 3) <> EXISTS
                       (SELECT 1 FROM source_js_ts_component_members AS member
                        WHERE member.blob_id = declaration.blob_id
                          AND member.declaration_id = declaration.declaration_id))
                  OR (COALESCE(declaration.component_kind, -1) <> 3 AND EXISTS
                      (SELECT 1 FROM source_js_ts_component_members AS member
                       WHERE member.blob_id = declaration.blob_id
                         AND member.declaration_id = declaration.declaration_id))))
    OR EXISTS (SELECT 1 FROM source_js_ts_types AS type
               WHERE type.blob_id = NEW.blob_id
                 AND (((type.kind = 0) <> EXISTS
                       (SELECT 1 FROM source_js_ts_type_names AS name
                        WHERE name.blob_id = type.blob_id AND name.type_id = type.type_id))
                  OR (type.kind NOT IN (1, 3, 4, 6, 7, 9)
                      AND EXISTS (SELECT 1 FROM source_js_ts_type_children AS child
                                 WHERE child.blob_id = type.blob_id AND child.type_id = type.type_id))
                  OR (type.kind <> 7 AND EXISTS (SELECT 1 FROM source_js_ts_type_members AS member
                                 WHERE member.blob_id = type.blob_id AND member.type_id = type.type_id))
                  OR (type.kind <> 6 AND EXISTS (SELECT 1 FROM source_js_ts_type_parameters AS parameter
                                 WHERE parameter.blob_id = type.blob_id AND parameter.type_id = type.type_id)))
  )) THEN RAISE(ABORT, 'JS/TS source publication has invalid dense rows') END;
END;

