CREATE TRIGGER source_native_declaration_bridges_require_expected
BEFORE INSERT ON source_native_declaration_bridges
WHEN NOT EXISTS (
  SELECT 1 FROM source_fact_manifests
  WHERE blob_id = NEW.blob_id AND native_bridge_count IS NOT NULL
) AND NOT EXISTS (
  SELECT 1 FROM blob_meta
  WHERE blob_id = NEW.blob_id AND declaration_visibility_version IS NOT NULL
)
BEGIN SELECT RAISE(ABORT, 'source native declaration bridge has no blob requirement'); END;

