BEGIN SELECT RAISE(ABORT, 'sealed source facts are immutable'); END;

CREATE TRIGGER source_occurrence_arenas_validate_seal
BEFORE UPDATE OF publication_state ON source_fact_manifests
WHEN OLD.publication_state = 'building' AND NEW.publication_state = 'complete'
 AND (NOT EXISTS (SELECT 1 FROM source_occurrence_arenas WHERE blob_id = NEW.blob_id)
 OR EXISTS (
   SELECT 1 FROM source_occurrence_arenas AS arena, json_each(arena.spans) AS entry
   WHERE arena.blob_id = NEW.blob_id
     AND CASE WHEN entry.type <> 'array' THEN 1 ELSE (
       json_array_length(entry.value) <> 5
       OR json_type(entry.value, '$[0]') IS NOT 'integer' OR typeof(json_extract(entry.value, '$[0]')) <> 'integer'
       OR json_type(entry.value, '$[1]') IS NOT 'integer' OR typeof(json_extract(entry.value, '$[1]')) <> 'integer'
       OR json_type(entry.value, '$[2]') IS NOT 'integer' OR typeof(json_extract(entry.value, '$[2]')) <> 'integer'
       OR json_type(entry.value, '$[3]') IS NOT 'integer' OR typeof(json_extract(entry.value, '$[3]')) <> 'integer'
       OR json_type(entry.value, '$[4]') IS NOT 'integer' OR typeof(json_extract(entry.value, '$[4]')) <> 'integer'
       OR json_extract(entry.value, '$[0]') < 0
       OR json_extract(entry.value, '$[1]') < json_extract(entry.value, '$[0]')
       OR json_extract(entry.value, '$[2]') < 1
       OR json_extract(entry.value, '$[3]') < json_extract(entry.value, '$[2]')
       OR json_extract(entry.value, '$[4]') NOT BETWEEN 0 AND 2
     ) END
 )
 )
BEGIN SELECT RAISE(ABORT, 'source occurrence arena is inconsistent'); END;

