BEGIN SELECT RAISE(ABORT, 'sealed Python source facts are immutable'); END;

CREATE TRIGGER source_python_manifests_validate
BEFORE INSERT ON source_python_manifests
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM blob_meta WHERE blob_id = NEW.blob_id AND python_source_version = NEW.facts_version
  ) THEN RAISE(ABORT, 'Python source facts require a matching blob requirement') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM source_python_costs WHERE blob_id = NEW.blob_id
      AND logical_rows = NEW.logical_rows AND payload_bytes = NEW.payload_bytes
  ) THEN RAISE(ABORT, 'Python source fact accounting is inconsistent') END;
  SELECT CASE WHEN (
    EXISTS (SELECT 1 FROM source_python_return_names WHERE blob_id = NEW.blob_id
      GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_python_callable_returns AS fact
      WHERE fact.blob_id = NEW.blob_id AND fact.runtime_type_present <> EXISTS (
        SELECT 1 FROM source_python_return_names AS name
        WHERE name.blob_id = fact.blob_id AND name.declaration_id = fact.declaration_id))
    OR EXISTS (SELECT 1 FROM source_python_callable_returns AS fact
      JOIN source_declarations AS declaration
        ON declaration.blob_id = fact.blob_id AND declaration.declaration_id = fact.declaration_id
      WHERE fact.blob_id = NEW.blob_id
        AND (fact.return_annotation_start_byte < declaration.start_byte OR fact.return_annotation_end_byte > declaration.end_byte))
    OR EXISTS (SELECT 1 FROM source_python_annotation_references WHERE blob_id = NEW.blob_id
      GROUP BY declaration_id HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1 OR MAX(subtree_end) > COUNT(*))
    OR EXISTS (SELECT 1 FROM source_python_annotation_names WHERE blob_id = NEW.blob_id
      GROUP BY declaration_id, reference_ordinal HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_python_annotation_references AS reference
      WHERE reference.blob_id = NEW.blob_id AND ((reference.name_kind = 1) <> EXISTS (
        SELECT 1 FROM source_python_annotation_names AS name WHERE name.blob_id = reference.blob_id
          AND name.declaration_id = reference.declaration_id AND name.reference_ordinal = reference.ordinal)))
    OR EXISTS (SELECT 1 FROM source_python_annotation_references AS reference
      JOIN source_python_callable_returns AS fact ON fact.blob_id = reference.blob_id AND fact.declaration_id = reference.declaration_id
      WHERE reference.blob_id = NEW.blob_id AND (fact.return_annotation_id IS NULL
        OR reference.start_byte < fact.return_annotation_start_byte OR reference.end_byte > fact.return_annotation_end_byte))
    OR EXISTS (SELECT 1 FROM source_python_annotation_references AS parent
      JOIN source_python_annotation_references AS child ON child.blob_id = parent.blob_id
        AND child.declaration_id = parent.declaration_id AND child.ordinal > parent.ordinal AND child.ordinal < parent.subtree_end
      WHERE parent.blob_id = NEW.blob_id AND child.subtree_end > parent.subtree_end)
  ) THEN RAISE(ABORT, 'Python source fact links are inconsistent') END;
END;

