WHEN (EXISTS (SELECT 1 FROM blobs WHERE id = OLD.blob_id) AND EXISTS (SELECT 1 FROM source_python_manifests WHERE blob_id = OLD.blob_id)) OR (EXISTS (SELECT 1 FROM blobs WHERE id = NEW.blob_id) AND EXISTS (SELECT 1 FROM source_python_manifests WHERE blob_id = NEW.blob_id))
