CREATE TRIGGER source_scala_declaration_manifests_validate
BEFORE INSERT ON source_scala_declaration_manifests
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM blob_meta AS meta
    WHERE meta.blob_id = NEW.blob_id AND meta.scala_source_version = NEW.facts_version
  ) THEN RAISE(ABORT, 'Scala source publication requires a matching Scala blob requirement') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM source_scala_declaration_costs
    WHERE blob_id = NEW.blob_id
      AND logical_rows = NEW.logical_rows
      AND payload_bytes = NEW.payload_bytes
  ) THEN RAISE(ABORT, 'Scala source publication accounting is inconsistent') END;
  SELECT CASE WHEN (
    (SELECT COUNT(*) FROM source_scala_type_expressions WHERE blob_id = NEW.blob_id)
      <> COALESCE((SELECT MAX(expression_id) + 1 FROM source_scala_type_expressions
                   WHERE blob_id = NEW.blob_id), 0)
    OR EXISTS (SELECT 1 FROM source_scala_declaration_lexical_prefixes
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_declaration_lexical_scopes
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_declaration_path_segments
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id, path_kind
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_generic_parameters
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_generic_supertypes
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_type_expression_segments
               WHERE blob_id = NEW.blob_id GROUP BY expression_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_type_expression_arguments
               WHERE blob_id = NEW.blob_id GROUP BY expression_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_lists
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_parameters
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id, list_ordinal
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_parameter_path_segments
               WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id, list_ordinal, parameter_ordinal
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_path_segments
               WHERE blob_id = NEW.blob_id GROUP BY declaration_id, path_kind
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_function_path_cells
               WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id, list_ordinal, parameter_ordinal
               HAVING MIN(function_ordinal) <> 0
                   OR MAX(function_ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_callable_function_path_segments
               WHERE blob_id = NEW.blob_id
               GROUP BY declaration_id, list_ordinal, parameter_ordinal, function_ordinal
               HAVING MIN(ordinal) <> 0 OR MAX(ordinal) <> COUNT(*) - 1)
    OR EXISTS (SELECT 1 FROM source_scala_declarations AS declaration
               WHERE declaration.blob_id = NEW.blob_id
                 AND ((declaration.callable_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callables AS callable
                   WHERE callable.blob_id = declaration.blob_id
                     AND callable.declaration_id = declaration.declaration_id))
    )
    OR EXISTS (SELECT 1 FROM source_scala_declarations AS declaration
               WHERE declaration.blob_id = NEW.blob_id
                 AND ((declaration.generic_owner_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_generic_owners AS owner
                   WHERE owner.blob_id = declaration.blob_id
                     AND owner.declaration_id = declaration.declaration_id))
    )
    OR EXISTS (SELECT 1 FROM source_scala_declarations AS declaration
               WHERE declaration.blob_id = NEW.blob_id
                 AND ((declaration.field_type_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_declaration_path_segments AS path
                   WHERE path.blob_id = declaration.blob_id
                     AND path.declaration_id = declaration.declaration_id
                     AND path.path_kind = 0))
    )
    OR EXISTS (SELECT 1 FROM source_scala_declarations AS declaration
               WHERE declaration.blob_id = NEW.blob_id
                 AND ((declaration.type_alias_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_declaration_path_segments AS path
                   WHERE path.blob_id = declaration.blob_id
                     AND path.declaration_id = declaration.declaration_id
                     AND path.path_kind = 1))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callables AS callable
               WHERE callable.blob_id = NEW.blob_id
                 AND ((callable.extension_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callable_path_segments AS path
                   WHERE path.blob_id = callable.blob_id
                     AND path.declaration_id = callable.declaration_id
                     AND path.path_kind = 0))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callables AS callable
               WHERE callable.blob_id = NEW.blob_id
                 AND ((callable.return_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callable_path_segments AS path
                   WHERE path.blob_id = callable.blob_id
                     AND path.declaration_id = callable.declaration_id
                     AND path.path_kind = 1))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callable_parameters AS parameter
               WHERE parameter.blob_id = NEW.blob_id
                 AND ((parameter.type_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callable_parameter_path_segments AS path
                   WHERE path.blob_id = parameter.blob_id
                     AND path.declaration_id = parameter.declaration_id
                     AND path.list_ordinal = parameter.list_ordinal
                     AND path.parameter_ordinal = parameter.ordinal))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callable_parameters AS parameter
               WHERE parameter.blob_id = NEW.blob_id
                 AND ((parameter.function_path_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callable_function_paths AS path
                   WHERE path.blob_id = parameter.blob_id
                     AND path.declaration_id = parameter.declaration_id
                     AND path.list_ordinal = parameter.list_ordinal
                     AND path.parameter_ordinal = parameter.ordinal))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callable_function_path_segments AS segment
               JOIN source_scala_callable_function_path_cells AS cell
                 ON cell.blob_id = segment.blob_id
                AND cell.declaration_id = segment.declaration_id
                AND cell.list_ordinal = segment.list_ordinal
                AND cell.parameter_ordinal = segment.parameter_ordinal
                AND cell.function_ordinal = segment.function_ordinal
               WHERE segment.blob_id = NEW.blob_id AND cell.present = 0)
    OR EXISTS (SELECT 1 FROM source_scala_callable_function_path_cells AS cell
               WHERE cell.blob_id = NEW.blob_id AND cell.present = 0
                 AND EXISTS (SELECT 1 FROM source_scala_callable_function_path_segments AS segment
                   WHERE segment.blob_id = cell.blob_id
                     AND segment.declaration_id = cell.declaration_id
                     AND segment.list_ordinal = cell.list_ordinal
                     AND segment.parameter_ordinal = cell.parameter_ordinal
                     AND segment.function_ordinal = cell.function_ordinal))
    OR EXISTS (SELECT 1 FROM source_scala_callables AS callable
               WHERE callable.blob_id = NEW.blob_id
                 AND ((callable.parameter_defaults_present = 1) <> EXISTS (
                   SELECT 1 FROM source_scala_callable_lists AS list
                   WHERE list.blob_id = callable.blob_id
                     AND list.declaration_id = callable.declaration_id))
    )
    OR EXISTS (SELECT 1 FROM source_scala_callable_lists AS list
               WHERE list.blob_id = NEW.blob_id
                 AND (SELECT COUNT(*) FROM source_scala_callable_parameters AS parameter
                      WHERE parameter.blob_id = list.blob_id
                        AND parameter.declaration_id = list.declaration_id
                        AND parameter.list_ordinal = list.ordinal) <> list.total_arity)
    OR EXISTS (SELECT 1 FROM source_scala_callables AS callable
               JOIN source_scala_callable_parameters AS parameter
                 ON parameter.blob_id = callable.blob_id
                AND parameter.declaration_id = callable.declaration_id
               WHERE callable.blob_id = NEW.blob_id
                 AND ((callable.parameter_function_arities_present = 0
                       AND parameter.function_arity IS NOT NULL)
                   OR (callable.parameter_type_paths_present = 0
                       AND parameter.type_path_present <> 0)
                   OR (callable.parameter_type_expressions_present = 0
                       AND parameter.type_expression_id IS NOT NULL)
                   OR (callable.parameter_function_type_paths_present = 0
                       AND parameter.function_path_present <> 0)))
    OR EXISTS (SELECT 1 FROM source_scala_callable_function_path_cells AS cell
               WHERE cell.blob_id = NEW.blob_id AND cell.present = 1
                 AND NOT EXISTS (SELECT 1 FROM source_scala_callable_function_path_segments AS segment
                   WHERE segment.blob_id = cell.blob_id
                     AND segment.declaration_id = cell.declaration_id
                     AND segment.list_ordinal = cell.list_ordinal
                     AND segment.parameter_ordinal = cell.parameter_ordinal
                     AND segment.function_ordinal = cell.function_ordinal))
    OR EXISTS (SELECT 1 FROM source_scala_callables AS callable
               WHERE callable.blob_id = NEW.blob_id
                 AND callable.return_type_is_singleton = 1
                 AND (callable.return_path_present = 0
                      OR callable.return_expression_id IS NULL))
    OR EXISTS (
      SELECT 1
      FROM source_scala_type_expressions AS expression
      LEFT JOIN (
        SELECT referenced_id, COUNT(*) AS reference_count
        FROM (
          SELECT child_id AS referenced_id
          FROM source_scala_type_expression_arguments
          WHERE blob_id = NEW.blob_id
          UNION ALL
          SELECT expression_id AS referenced_id
          FROM source_scala_generic_supertypes
          WHERE blob_id = NEW.blob_id
          UNION ALL
          SELECT return_expression_id AS referenced_id
          FROM source_scala_callables
          WHERE blob_id = NEW.blob_id AND return_expression_id IS NOT NULL
          UNION ALL
          SELECT type_expression_id AS referenced_id
          FROM source_scala_callable_parameters
          WHERE blob_id = NEW.blob_id AND type_expression_id IS NOT NULL
        ) AS all_references
        GROUP BY referenced_id
      ) AS references_for_expression
        ON references_for_expression.referenced_id = expression.expression_id
      WHERE expression.blob_id = NEW.blob_id
        AND COALESCE(references_for_expression.reference_count, 0) <> 1
    )
  ) THEN RAISE(ABORT, 'Scala source publication has invalid ordered syntax') END;
END;

