CREATE TRIGGER unit_signature_metadata_capture_parameters
AFTER INSERT ON unit_signature_metadata
BEGIN
  UPDATE unit_signature_metadata SET parameter_count = json_array_length(NEW.parameters)
    WHERE blob_id = NEW.blob_id AND unit_key = NEW.unit_key AND ordinal = NEW.ordinal;
  INSERT INTO unit_signature_parameters
    (blob_id, unit_key, metadata_ordinal, ordinal, label, name, start_byte, end_byte)
    SELECT NEW.blob_id, NEW.unit_key, NEW.ordinal, CAST(parameter.key AS INTEGER),
           json_extract(parameter.value, '$.label'), json_extract(parameter.value, '$.name'),
           json_extract(parameter.value, '$.start_byte'), json_extract(parameter.value, '$.end_byte')
    FROM json_each(NEW.parameters) AS parameter;
  UPDATE unit_signature_metadata SET parameters = '[]'
    WHERE blob_id = NEW.blob_id AND unit_key = NEW.unit_key AND ordinal = NEW.ordinal;
END;

CREATE TRIGGER unit_signature_metadata_java_constructor_type_only
BEFORE INSERT ON unit_signature_metadata
WHEN NEW.java_constructor_shape IS NOT NULL
 AND NOT EXISTS (
   SELECT 1 FROM code_units AS units
   WHERE units.blob_id = NEW.blob_id AND units.unit_key = NEW.unit_key
     AND units.kind = 0 AND units.synthetic = 0
 )
BEGIN
  SELECT RAISE(ABORT, 'Java constructor shape requires a nonsynthetic type');
END;

