CREATE TRIGGER unit_signature_metadata_validate_parameter_input
BEFORE INSERT ON unit_signature_metadata
BEGIN
  SELECT CASE WHEN json_type(NEW.parameters) <> 'array'
    OR EXISTS (SELECT 1 FROM json_each(NEW.parameters) AS parameter
      WHERE json_type(parameter.value) <> 'object'
         OR json_type(parameter.value, '$.label') IS NOT 'text'
         OR json_type(parameter.value, '$.start_byte') IS NOT 'integer'
         OR json_type(parameter.value, '$.end_byte') IS NOT 'integer'
         OR (json_type(parameter.value, '$.name') IS NOT NULL
             AND json_type(parameter.value, '$.name') NOT IN ('null', 'text')))
    THEN RAISE(ABORT, 'invalid signature parameter input') END;
END;

