INSERT INTO "analysis_generation_sequence" ("id", "next_generation") VALUES (1, 1);

INSERT INTO "cache_state" ("id", "schema_version", "semantic_schema_version", "analyzer_schema_version", "last_gc_at", "blobs_at_last_gc", "gc_claim_until", "embed_fingerprint", "chunker_version") VALUES (1, 1, 1, 10, 0, 0, 0, NULL, NULL);

CREATE TABLE resolution_capsule_inputs(
  blob_id INTEGER PRIMARY KEY REFERENCES blobs(id) ON DELETE CASCADE,
  host_content_oid TEXT NOT NULL
    CHECK(length(host_content_oid)=40 AND host_content_oid NOT GLOB '*[^0-9a-f]*'),
  invocation INTEGER NOT NULL CHECK(invocation BETWEEN 0 AND 4294967295),
  definition_content_oid TEXT NOT NULL
    CHECK(length(definition_content_oid)=40 AND definition_content_oid NOT GLOB '*[^0-9a-f]*'),
  selected_declaration INTEGER NOT NULL CHECK(selected_declaration BETWEEN 0 AND 4294967295),
  matched_arm_index INTEGER NOT NULL CHECK(matched_arm_index>=0),
  producer_epoch TEXT NOT NULL CHECK(length(producer_epoch)>0),
  derivation_digest BLOB NOT NULL CHECK(length(derivation_digest)=32),
  checkpoint_digest BLOB NOT NULL CHECK(length(checkpoint_digest)=32),
  host_module_scope INTEGER NOT NULL CHECK(host_module_scope BETWEEN 0 AND 4294967295),
  UNIQUE(host_content_oid, invocation, definition_content_oid,
         selected_declaration, matched_arm_index, producer_epoch)
) STRICT;

CREATE TABLE resolution_capsule_declarations(
  blob_id INTEGER NOT NULL,
  semantic_key INTEGER NOT NULL CHECK(semantic_key>=0),
  identifier TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('parameter','receiver_parameter','import_alias',
    'statement_label','local_variable','catch_parameter','enhanced_for_variable',
    'lambda_parameter','pattern_variable','resource_variable','field','block_local_item')),
  name_start_byte INTEGER NOT NULL CHECK(name_start_byte>=0),
  name_end_byte INTEGER NOT NULL CHECK(name_end_byte>=name_start_byte),
  name_start_line INTEGER NOT NULL CHECK(name_start_line>=1),
  name_end_line INTEGER NOT NULL CHECK(name_end_line>=name_start_line),
  declaration_start_byte INTEGER NOT NULL CHECK(declaration_start_byte>=0),
  declaration_end_byte INTEGER NOT NULL CHECK(declaration_end_byte>=declaration_start_byte),
  declaration_start_line INTEGER NOT NULL CHECK(declaration_start_line>=1),
  declaration_end_line INTEGER NOT NULL CHECK(declaration_end_line>=declaration_start_line),
  PRIMARY KEY(blob_id, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_capsule_inputs(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE resolution_capsule_reference_contexts(
  blob_id INTEGER NOT NULL,
  semantic_key INTEGER NOT NULL CHECK(semantic_key>=0),
  source_site INTEGER NOT NULL CHECK(source_site BETWEEN 0 AND 4294967295),
  host_occurrence INTEGER NOT NULL CHECK(host_occurrence BETWEEN 0 AND 4294967295),
  module_context INTEGER NOT NULL CHECK(module_context BETWEEN 0 AND 4294967295),
  module_declaration INTEGER CHECK(module_declaration BETWEEN 0 AND 4294967295),
  reference_owner_kind INTEGER NOT NULL CHECK(reference_owner_kind IN (0,1,2)),
  host_owner_key INTEGER CHECK(host_owner_key>=0),
  CHECK((reference_owner_kind=2)=(host_owner_key IS NOT NULL)),
  PRIMARY KEY(blob_id, semantic_key),
  FOREIGN KEY(blob_id) REFERENCES resolution_capsule_inputs(blob_id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;

CREATE TABLE workspace_resolution_content_roots(
  workspace_id TEXT NOT NULL,
  lang TEXT NOT NULL,
  generation INTEGER NOT NULL,
  revision INTEGER NOT NULL,
  blob_id INTEGER NOT NULL,
  FOREIGN KEY(blob_id,lang) REFERENCES blobs(id,lang) ON DELETE CASCADE,
  PRIMARY KEY(workspace_id,lang,generation,revision,blob_id),
  FOREIGN KEY(workspace_id,lang,generation,revision)
    REFERENCES workspace_revisions(workspace_id,lang,generation,revision) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;
-- Both collector deletion transactions probe this index by blob_id.
CREATE INDEX workspace_resolution_content_roots_blob
  ON workspace_resolution_content_roots(blob_id);
